import { Book } from "@/lib/types";

export const john: Book = {
  id: "john",
  name: "Johannes",
  shortName: "Joh",
  testament: "new",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Im Anfang war das Wort*, und das Wort war bei Gott, und das Wort war Gott*.", heading: "Das ewige Wort", footnotes: ["griech. logos; das griech. Wort bedeutet auch Rede, Grund, Gedanke, Denkvermögen\n℘ 1Jo 2,13.14; Offb 19,13", "℘ Röm 9,5; Phil 2,6; 1Jo 5,20 ⇨Esyn: Synopse Nr. 166"] },
      { number: 2, text: "Dieses war im Anfang bei Gott*.", footnotes: ["℘ Kap. 8,58"] },
      { number: 3, text: "Alles wurde durch dasselbe*, und ohne dasselbe wurde auch nicht eines, das geworden ist.", footnotes: ["℘ Ps 33,6; 1Kor 8,6; Kol 1,16; Hebr 1,2; 11,3"] },
      { number: 4, text: "In ihm war Leben*, und das Leben war das Licht der Menschen*.", footnotes: ["℘ Kap. 5,26; Ps 36,10; 1Jo 1,1.2", "℘ Kap. 8,12"] },
      { number: 5, text: "Und das Licht scheint in der Finsternis*, und die Finsternis hat es nicht erfasst*.", footnotes: ["℘ Mt 4,16", "o. überwältigt"] },
      { number: 6, text: "Da war ein Mensch, von Gott gesandt, sein Name: Johannes*.", heading: "Die Fleischwerdung des Wortes", footnotes: ["℘ Mt 3,1; Mk 1,4"] },
      { number: 7, text: "Dieser kam zum Zeugnis, dass er zeugte von dem Licht, damit alle durch ihn glaubten*.", footnotes: ["℘ Kap. 5,33-35"] },
      { number: 8, text: "Er war nicht das Licht, sondern er kam, dass er zeugte von dem Licht*.", footnotes: ["℘ V. 20; Kap. 3,28; Mt 11,13"] },
      { number: 9, text: "Das war das wahrhaftige Licht*, das, in die Welt kommend, jeden Menschen erleuchtet*.", footnotes: ["℘ Ps 27,1", "o. das jeden Menschen, der in die Welt kommt, erleuchtet\n℘ Kap. 12,46"] },
      { number: 10, text: "Er war in der Welt, und die Welt wurde durch ihn*, und die Welt kannte ihn nicht.", footnotes: ["℘ V. 3"] },
      { number: 11, text: "Er kam in das Seine*, und die Seinen* nahmen ihn nicht an*;", footnotes: ["w. in das Eigene, bzw. die Eigenen", "w. in das Eigene, bzw. die Eigenen", "℘ Kap. 3,11"] },
      { number: 12, text: "so viele ihn aber aufnahmen, denen gab er das Recht*, Kinder Gottes zu werden, denen, die an seinen Namen glauben*;", footnotes: ["o. die Macht, die Vollmacht", "℘ Röm 8,16; 1Jo 3,1.2"] },
      { number: 13, text: "die nicht aus Geblüt, auch nicht aus dem Willen des Fleisches, auch nicht aus dem Willen des Mannes, sondern aus Gott geboren sind*.", footnotes: ["℘ Kap. 3,3; Jak 1,18; 1Petr 1,3.23; 1Jo 2,29"] },
      { number: 14, text: "Und das Wort wurde Fleisch* und wohnte* unter uns, und wir haben seine Herrlichkeit angeschaut*, eine Herrlichkeit als eines Eingeborenen* vom Vater, voller Gnade und Wahrheit*. —", footnotes: ["℘ Lk 2,7; 1Tim 3,16; Hebr 2,14; 1Jo 4,2", "w. zeltete", "℘ Kap. 2,11; 11,40; 2Petr 1,16.17", "griech. monogenes; d. h. einzig in seiner Art; o. einziggeboren; o. einzig", "℘ Ps 85,11; Hebr 1,3"] },
      { number: 15, text: "Johannes zeugt von ihm und rief und sprach: Dieser war es, von dem ich sagte: Der nach mir kommt*, ist vor mir geworden, denn er war eher als ich*. —", footnotes: ["℘ Mt 3,11", "℘ V. 27.30; Apg 19,4"] },
      { number: 16, text: "Denn aus seiner Fülle* haben wir alle empfangen, und zwar Gnade um Gnade*.", footnotes: ["℘ Eph 1,23; Kol 1,19; 2,9", "℘ Apg 4,33"] },
      { number: 17, text: "Denn das Gesetz wurde durch Mose gegeben*; die Gnade und die Wahrheit* ist durch Jesus Christus geworden.", footnotes: ["℘ Kap. 7,19; Apg 7,38", "℘ Ps 85,11"] },
      { number: 18, text: "Niemand hat Gott jemals gesehen*; der eingeborene* Sohn*, der in des Vaters Schoß ist, der hat ihn kundgemacht*.", footnotes: ["℘ Kap. 5,37; 6,46; 1Tim 6,16; 1Jo 4,12", "griech. monogenes; d. h. einzig in seiner Art; o. einziggeboren; o. einzig", "mit den älteren Handschr.: der eingeborene Gott", "℘ Kap. 14,7; Mt 11,27"] },
      { number: 19, text: "*Und dies ist das Zeugnis des Johannes, als die Juden aus Jerusalem Priester und Leviten zu ihm sandten, damit sie ihn fragen sollten: Wer bist du*?", heading: "Des Täufers Zeugnis über sich", footnotes: ["℘ vgl. Mt 3,1-12; Mk 1,1-8; Lk 3,1-18", "℘ Kap. 5,33 ⇨Esyn: Synopse Nr. 13"] },
      { number: 20, text: "Und er bekannte und leugnete nicht, und er bekannte: Ich bin nicht der Christus*.", footnotes: ["℘ V. 8; Apg 13,25"] },
      { number: 21, text: "Und sie fragten ihn: Was denn? Bist du Elia*? Und er sagt: Ich bin es nicht. Bist du der Prophet*? Und er antwortete: Nein.", footnotes: ["℘ Mt 11,14", "℘ Kap. 6,14; 7,40; 5Mo 18,15.18"] },
      { number: 22, text: "Sie sprachen nun zu ihm: Wer bist du? Damit wir Antwort geben denen, die uns gesandt haben. Was sagst du von dir selbst?" },
      { number: 23, text: "Er sprach: Ich bin die »Stimme eines Rufenden in der Wüste: Macht gerade den Weg des Herrn«, wie Jesaja, der Prophet, gesagt hat*.", footnotes: ["℘ Jes 40,3"] },
      { number: 24, text: "Und sie waren abgesandt von den Pharisäern*. *", footnotes: ["religiöse Partei im Judentum, die auf genaue Einhaltung des Gesetzes Wert legte; s. auch Anm. zu Mt 3,7", "℘ ⇨Esyn: Synopse Nr. 16"] },
      { number: 25, text: "Und sie fragten ihn und sprachen zu ihm: Was taufst du denn, wenn du nicht der Christus bist noch Elia noch der Prophet?" },
      { number: 26, text: "Johannes antwortete ihnen und sprach: Ich taufe mit Wasser*; mitten unter euch steht, den ihr nicht kennt,", footnotes: ["℘ V. 31.33"] },
      { number: 27, text: "der nach mir kommt*, vor dem* ich nicht würdig bin, den Riemen seiner Sandale zu lösen.", footnotes: ["℘ V. 15", "w. dessen"] },
      { number: 28, text: "Dies geschah zu Betanien, jenseits des Jordan, wo Johannes taufte." },
      { number: 29, text: "*Am folgenden Tag sieht er Jesus zu sich kommen und spricht: Siehe, das Lamm Gottes*, das die Sünde der Welt wegnimmt*!", heading: "Des Täufers Zeugnis über Jesus", footnotes: ["℘ vgl. Mt 3,13-17; Mk 1,9-11; Lk 3,21.22", "℘ V. 36; Jes 53,7; 1Petr 1,19; Offb 5,6.12", "℘ Mt 1,21; Hebr 9,26; 1Jo 2,2; 3,5 ⇨Esyn: Synopse Nr. 18"] },
      { number: 30, text: "Dieser ist es, von dem ich sagte: Nach mir kommt ein Mann, der vor mir ist, denn er war eher als ich*.", footnotes: ["℘ V. 15"] },
      { number: 31, text: "Und ich kannte ihn nicht; aber damit er Israel offenbar werde, deswegen bin ich gekommen, mit Wasser zu taufen." },
      { number: 32, text: "Und Johannes bezeugte und sprach: Ich schaute den Geist wie eine Taube aus dem Himmel herabfahren, und er blieb auf ihm." },
      { number: 33, text: "Und ich kannte ihn nicht; aber der mich gesandt hat, mit* Wasser zu taufen*, der sprach zu mir: Auf welchen du sehen wirst den Geist herabfahren und auf ihm bleiben, dieser ist es, der mit* Heiligem Geist tauft*.", footnotes: ["o. in", "℘ V. 26", "o. in", "℘ Mt 3,11"] },
      { number: 34, text: "Und ich habe gesehen und habe bezeugt*, dass dieser der Sohn Gottes ist*.", footnotes: ["℘ 1Jo 4,14", "℘ V. 49; Mt 14,33"] },
      { number: 35, text: "Am folgenden Tag stand Johannes wieder da und zwei von seinen Jüngern*;", heading: "Die ersten Jünger", footnotes: ["℘ Kap. 3,25; Mt 9,14 ⇨Esyn: Synopse Nr. 34"] },
      { number: 36, text: "und hinblickend auf Jesus, der vorbeiging, spricht er: Siehe, das Lamm Gottes*!", footnotes: ["℘ V. 29"] },
      { number: 37, text: "Und es hörten ihn die zwei Jünger reden und folgten Jesus nach." },
      { number: 38, text: "Jesus aber wandte sich um und sah sie nachfolgen und spricht zu ihnen: Was sucht ihr? Sie aber sagten zu ihm: Rabbi* — was übersetzt heißt: Lehrer —, wo hältst du dich auf?", footnotes: ["d. h. Mein Meister!; respektvolle Anrede der geistlichen Lehrer im Spätjudentum"] },
      { number: 39, text: "Er spricht zu ihnen: Kommt, und ihr werdet sehen*! Sie kamen nun und sahen, wo er sich aufhielt, und blieben jenen Tag bei ihm. Es war um die zehnte Stunde*.", footnotes: ["mit anderen Handschr.: und seht", "In neutestamentl. Zeit teilte man Tag und Nacht in je 12 Stunden ein, wobei sich die Länge der Stunden nach der Länge des Tages zwischen Sonnenauf- und Sonnenuntergang richtete. Die 10. Stunde lag also zwei bis drei Stunden vor Sonnenuntergang."] },
      { number: 40, text: "Andreas, der Bruder des Simon Petrus*, war einer von den zweien, die es von Johannes gehört hatten und ihm nachgefolgt waren.", footnotes: ["℘ Mt 4,18"] },
      { number: 41, text: "Dieser findet zuerst seinen eigenen Bruder Simon und spricht zu ihm: Wir haben den Messias gefunden — was übersetzt ist: Christus*.", footnotes: ["d. h. der Gesalbte; griech. Übersetzung von hebr. maschiach, dem Israel verheißenen Messias\n℘ Kap. 4,25; Ps 2,2; Mk 8,29"] },
      { number: 42, text: "Und er führte ihn zu Jesus. Jesus blickte ihn an* und sprach: Du bist Simon, der Sohn des Johannes*; du wirst Kephas heißen — was übersetzt wird: Stein*.", footnotes: ["℘ Lk 22,61", "℘ Kap. 21,15-17; Mt 16,17", "griech. petros; lat. petrus\n℘ Mt 10,2; 1Kor 1,12; Gal 1,18"] },
      { number: 43, text: "Am folgenden Tag wollte er nach Galiläa aufbrechen, und er findet Philippus*; und Jesus spricht zu ihm: Folge mir nach*!", footnotes: ["℘ Mt 10,3", "℘ Kap. 21,19.22; Mt 4,19; Mk 2,14"] },
      { number: 44, text: "Philippus aber war von Betsaida*, aus der Stadt des Andreas und Petrus.", footnotes: ["℘ Kap. 12,21"] },
      { number: 45, text: "Philippus findet den Nathanael* und spricht zu ihm: Wir haben den gefunden, von dem Mose in dem Gesetz geschrieben* und die Propheten*, Jesus, den Sohn des Josef, von Nazareth*.", footnotes: ["℘ Kap. 21,2", "℘ 5Mo 18,15.18", "℘ Kap. 5,39.46; Lk 24,27", "℘ Kap. 6,42; Mt 1,16; 2,23"] },
      { number: 46, text: "Und Nathanael sprach zu ihm: Aus Nazareth kann etwas Gutes kommen? Philippus spricht zu ihm: Komm und sieh!" },
      { number: 47, text: "Jesus sah den Nathanael zu sich kommen und spricht von ihm: Siehe, wahrhaftig ein Israelit, in dem kein Trug ist*!", footnotes: ["℘ Ps 32,2"] },
      { number: 48, text: "Nathanael spricht zu ihm: Woher kennst du mich? Jesus antwortete und sprach zu ihm: Ehe Philippus dich rief, als du unter dem Feigenbaum warst, sah ich dich*.", footnotes: ["℘ Ps 139,2"] },
      { number: 49, text: "Nathanael antwortete und sprach: Rabbi, du bist der Sohn Gottes, du bist der König Israels*.", footnotes: ["℘ V. 34; Kap. 11,27; 12,13; 20,31; Ps 2,6.7"] },
      { number: 50, text: "Jesus antwortete und sprach zu ihm: Weil ich dir sagte: Ich sah dich unter dem Feigenbaum, glaubst du?* Du wirst Größeres als dies sehen.", footnotes: ["Nach manchen Auslegern kein Frage-, sondern ein Aussagesatz: Weil ich dir sagte . . . glaubst du."] },
      { number: 51, text: "Und er spricht zu ihm: Wahrlich, wahrlich, ich sage euch: Ihr werdet den Himmel geöffnet sehen und die Engel Gottes auf- und niedersteigen* auf den Sohn des Menschen*.", footnotes: ["℘ 1Mo 28,12", "℘ Mt 4,11"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und am dritten Tag war eine Hochzeit zu Kana in Galiläa; und die Mutter Jesu war dort. *", heading: "Hochzeit zu Kana", footnotes: ["℘ ⇨Esyn: Synopse Nr. 22"] },
      { number: 2, text: "Es war aber auch Jesus mit seinen Jüngern zu der Hochzeit eingeladen." },
      { number: 3, text: "Und als es an Wein mangelte, spricht die Mutter Jesu zu ihm: Sie haben keinen Wein." },
      { number: 4, text: "Jesus spricht zu ihr: Was habe ich mit dir zu schaffen*, Frau? Meine Stunde ist noch nicht gekommen*.", footnotes: ["w. Was ist mir und dir gemeinsam\n℘ Mt 8,29", "℘ Kap. 7,6.8"] },
      { number: 5, text: "Seine Mutter spricht zu den Dienern: Was er euch sagen mag, tut*!", footnotes: ["℘ 1Mo 41,55"] },
      { number: 6, text: "Es waren aber sechs steinerne Wasserkrüge dort aufgestellt nach der Reinigungssitte der Juden*, wovon jeder zwei oder drei Maß* fasste.", footnotes: ["℘ Mk 7,3.4", "w. Metretes; ein Hohlmaß von etwa 39 l; die Krüge fassten also insgesamt etwa 600 l"] },
      { number: 7, text: "Jesus spricht zu ihnen: Füllt die Wasserkrüge mit Wasser! Und sie füllten sie bis obenan." },
      { number: 8, text: "Und er spricht zu ihnen: Schöpft nun und bringt es dem Speisemeister! Und sie brachten es." },
      { number: 9, text: "Als aber der Speisemeister das Wasser gekostet hatte, das Wein geworden war — und er wusste nicht, woher er war, die Diener aber, die das Wasser geschöpft hatten, wussten es —, ruft der Speisemeister den Bräutigam" },
      { number: 10, text: "und spricht zu ihm: Jeder Mensch setzt zuerst den guten Wein vor, und wenn sie betrunken geworden sind, dann den geringeren; du hast den guten Wein bis jetzt aufbewahrt." },
      { number: 11, text: "Diesen Anfang der Zeichen machte Jesus zu Kana in Galiläa* und offenbarte seine Herrlichkeit*; und seine Jünger glaubten an ihn.", footnotes: ["℘ Kap. 4,46.54", "℘ Kap. 1,14"] },
      { number: 12, text: "Danach ging er hinab nach Kapernaum*, er und seine Mutter und seine Brüder* und seine Jünger; und dort blieben sie nicht viele Tage.", footnotes: ["℘ Lk 4,31", "℘ Kap. 7,3; Mt 12,46 ⇨Esyn: Synopse Nr. 35"] },
      { number: 13, text: "*Und das Passah* der Juden war nahe*, und Jesus ging hinauf nach Jerusalem*.", heading: "Tempelreinigung", footnotes: ["℘ vgl. Mt 21,12-17; Mk 11,15-19; Lk 19,45-48", "℘ 2Mo 12,11", "℘ Kap. 6,4; 11,55", "℘ 5Mo 16,5.6; Lk 2,41 ⇨Esyn: Synopse Nr. 24"] },
      { number: 14, text: "Und er fand im Tempel die Ochsen-, Schaf- und Taubenverkäufer und die Wechsler sitzen*.", footnotes: ["℘ 5Mo 14,24-26 ⇨Esyn: Synopse Nr. 25"] },
      { number: 15, text: "Und er machte eine Geißel aus Stricken und trieb sie alle zum Tempel hinaus, auch die Schafe und die Ochsen; und die Münzen der Wechsler schüttete er aus, und die Tische warf er um*;", footnotes: ["℘ Mal 3,1.2"] },
      { number: 16, text: "und zu den Taubenverkäufern sprach er: Nehmt dies weg von hier, macht nicht das Haus meines Vaters* zu einem Kaufhaus!", footnotes: ["℘ Lk 2,49"] },
      { number: 17, text: "Seine Jünger gedachten daran, dass geschrieben steht: »Der Eifer um dein Haus verzehrt mich.«*", footnotes: ["℘ Ps 69,10"] },
      { number: 18, text: "Die Juden nun antworteten und sprachen zu ihm: Was für ein Zeichen der Vollmacht zeigst du uns, dass du dies tust*?", footnotes: ["℘ Kap. 4,48; 6,30; Mt 12,38; 21,23"] },
      { number: 19, text: "Jesus antwortete und sprach zu ihnen: Brecht diesen Tempel ab, und in drei Tagen werde ich ihn aufrichten*.", footnotes: ["℘ Mt 26,61 ⇨Esyn: Synopse Nr. 332"] },
      { number: 20, text: "Da sprachen die Juden: 46 Jahre ist an diesem Tempel gebaut worden, und du willst ihn in drei Tagen aufrichten?" },
      { number: 21, text: "Er aber sprach von dem Tempel seines Leibes*.", footnotes: ["℘ Mt 16,21; 1Kor 6,19"] },
      { number: 22, text: "Als er nun aus den Toten auferweckt war, gedachten seine Jünger daran, dass er dies gesagt hatte*, und sie glaubten der Schrift und dem Wort, das Jesus gesprochen hatte.", footnotes: ["℘ Kap. 12,16; 14,26; Lk 24,8"] },
      { number: 23, text: "Als er aber zu Jerusalem war, am Passah, auf dem Fest, glaubten viele an seinen Namen, als sie seine Zeichen sahen, die er tat*.", footnotes: ["℘ Kap. 4,45; 6,2; 7,31; 11,45; 12,11 ⇨Esyn: Synopse Nr. 26"] },
      { number: 24, text: "Jesus selbst aber vertraute sich ihnen nicht an, weil er alle kannte*", footnotes: ["℘ Kap. 6,64"] },
      { number: 25, text: "und nicht nötig hatte, dass jemand Zeugnis gebe von dem Menschen; denn er selbst wusste, was in dem Menschen war*.", footnotes: ["℘ Kap. 16,30; 21,17; Ps 94,11; 139,1.2; Jer 17,10; Mt 9,4; Hebr 4,13; Offb 2,23"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Es war aber ein Mensch aus den Pharisäern* mit Namen Nikodemus*, ein Oberster der Juden.", heading: "Gespräch mit Nikodemus", footnotes: ["religiöse Partei im Judentum, die auf genaue Einhaltung des Gesetzes Wert legte; s. a. Anm. zu Mt 3,7", "℘ Kap. 7,50 ⇨Esyn: Synopse Nr. 27"] },
      { number: 2, text: "Dieser kam zu ihm bei Nacht* und sprach zu ihm: Rabbi*, wir wissen, dass du ein Lehrer bist, von Gott gekommen, denn niemand kann diese Zeichen tun, die du tust, es sei denn Gott mit ihm*.", footnotes: ["℘ Kap. 19,39", "d. h. Mein Meister!; respektvolle Anrede der geistlichen Lehrer im Spätjudentum", "℘ Kap. 5,36; 7,31; 9,33; Apg 2,22 ⇨Esyn: Synopse Nr. 280"] },
      { number: 3, text: "Jesus antwortete und sprach zu ihm: Wahrlich, wahrlich, ich sage dir: Wenn jemand nicht von neuem* geboren wird*, kann er das Reich* Gottes nicht sehen*.", footnotes: ["o. von oben her", "℘ Kap. 1,13", "o. die Königsherrschaft", "℘ 1Kor 15,50 ⇨Esyn: Synopse Nr. 253"] },
      { number: 4, text: "Nikodemus spricht zu ihm: Wie kann ein Mensch geboren werden, wenn er alt ist? Kann er etwa zum zweiten Mal in den Leib seiner Mutter hineingehen und geboren werden?" },
      { number: 5, text: "Jesus antwortete: Wahrlich, wahrlich, ich sage dir: Wenn jemand nicht aus Wasser und Geist geboren wird*, kann er nicht in das Reich* Gottes hineingehen.", footnotes: ["℘ Hes 36,25-27; Tit 3,5", "o. die Königsherrschaft"] },
      { number: 6, text: "Was aus dem Fleisch geboren ist, ist Fleisch*, und was aus dem Geist geboren ist, ist Geist*.", footnotes: ["℘ Röm 7,14", "℘ Röm 8,5"] },
      { number: 7, text: "Wundere dich nicht, dass ich dir sagte: Ihr müsst von neuem* geboren werden.", footnotes: ["o. von oben her"] },
      { number: 8, text: "Der Wind weht, wo er will, und du hörst sein Sausen*, aber du weißt nicht, woher er kommt und wohin er geht*; so ist jeder, der aus dem Geist* geboren ist.", footnotes: ["w. seine Stimme", "℘ Pred 11,5", "Das griech. Wort pneuma bedeutet sowohl »Geist« als auch »Wind«."] },
      { number: 9, text: "Nikodemus antwortete und sprach zu ihm: Wie kann dies geschehen*?", footnotes: ["℘ Lk 1,34"] },
      { number: 10, text: "Jesus antwortete und sprach zu ihm: Du bist der Lehrer Israels und weißt das nicht?" },
      { number: 11, text: "Wahrlich, wahrlich, ich sage dir: Wir reden, was wir wissen, und bezeugen, was wir gesehen haben, und unser Zeugnis nehmt ihr nicht an*.", footnotes: ["℘ V. 32; Kap. 1,11"] },
      { number: 12, text: "Wenn ich euch das Irdische gesagt habe, und ihr glaubt nicht, wie werdet ihr glauben, wenn ich euch das Himmlische sage*?", footnotes: ["℘ Kap. 8,45; 10,25; Lk 22,67"] },
      { number: 13, text: "Und niemand ist hinaufgestiegen in den Himmel als nur der, der aus dem Himmel herabgestiegen ist*, der Sohn des Menschen*.", footnotes: ["℘ Kap. 6,38.62; Spr 30,4; Eph 4,9.10", "Einige Handschr. fügen hinzu: der im Himmel ist"] },
      { number: 14, text: "Und wie Mose in der Wüste die Schlange erhöhte*, so muss der Sohn des Menschen erhöht werden*,", footnotes: ["℘ 4Mo 21,9", "℘ Kap. 8,28; 12,32"] },
      { number: 15, text: "damit jeder, der an ihn glaubt, ewiges Leben habe*.", footnotes: ["℘ V. 36; Kap. 5,24; 6,40.47; 20,31; Mk 16,16; Röm 6,23"] },
      { number: 16, text: "Denn so* hat Gott die Welt geliebt, dass er seinen eingeborenen* Sohn gab*, damit jeder, der an ihn glaubt, nicht verloren geht, sondern ewiges Leben hat*.", footnotes: ["o. so sehr", "griech. monogenes; d. h. einzig in seiner Art; o. einzig geboren; o. einzig", "℘ Röm 5,8; 8,32", "℘ Kap. 10,28; 11,26; 12,50; 1Tim 1,16; 1Jo 4,9"] },
      { number: 17, text: "Denn Gott hat seinen Sohn nicht in die Welt gesandt, dass er die Welt richte, sondern dass die Welt durch ihn gerettet werde*.", footnotes: ["℘ Kap. 8,11.15; 12,47; Mt 18,11; 1Tim 1,15; 2,4; 1Jo 4,14"] },
      { number: 18, text: "Wer an ihn glaubt, wird nicht gerichtet*; wer aber nicht glaubt, ist schon gerichtet, weil er nicht geglaubt hat an den Namen des eingeborenen* Sohnes Gottes*.", footnotes: ["℘ Kap. 5,24", "griech. monogenes; d. h. einzig in seiner Art; o. einzig geboren; o. einzig", "℘ V. 36; 2Thes 2,12"] },
      { number: 19, text: "Dies aber ist das Gericht, dass das Licht in die Welt gekommen ist*, und die Menschen haben die Finsternis mehr geliebt als das Licht, denn ihre Werke waren böse.", footnotes: ["℘ Kap. 1,9"] },
      { number: 20, text: "Denn jeder, der Arges tut, hasst das Licht und kommt nicht zu dem Licht, damit seine Werke nicht bloßgestellt werden*;", footnotes: ["℘ Kap. 7,7; Eph 5,13"] },
      { number: 21, text: "wer aber die Wahrheit tut, kommt zu dem Licht, damit seine Werke offenbar werden, dass sie in Gott gewirkt sind." },
      { number: 22, text: "Danach kamen Jesus und seine Jünger in das Land Judäa, und dort verweilte er mit ihnen und taufte*.", heading: "Weiteres Zeugnis des Täufers über Jesus", footnotes: ["℘ Kap. 4,1.2 ⇨Esyn: Synopse Nr. 28"] },
      { number: 23, text: "Aber auch Johannes taufte zu Änon, nahe bei Salim, weil dort viel Wasser war; und sie kamen hin und wurden getauft*.", footnotes: ["℘ Mt 3,6 ⇨Esyn: Synopse Nr. 29"] },
      { number: 24, text: "Denn Johannes war noch nicht ins Gefängnis geworfen*.", footnotes: ["℘ Mt 14,3"] },
      { number: 25, text: "Es entstand nun eine Streitfrage vonseiten der Jünger des Johannes* mit einem Juden über die Reinigung.", footnotes: ["℘ Kap. 1,35"] },
      { number: 26, text: "Und sie kamen zu Johannes und sprachen zu ihm: Rabbi*, der jenseits des Jordan bei dir war, dem du Zeugnis gegeben hast*, siehe, der tauft, und alle kommen zu ihm.", footnotes: ["d. h. Mein Meister!; respektvolle Anrede der geistlichen Lehrer im Spätjudentum", "℘ Kap. 1,26-34"] },
      { number: 27, text: "Johannes antwortete und sprach: Ein Mensch kann nichts empfangen, auch nicht eins, es sei ihm denn aus dem Himmel gegeben*.", footnotes: ["℘ Mt 21,25"] },
      { number: 28, text: "Ihr selbst gebt mir Zeugnis, dass ich sagte: Ich bin nicht der Christus, sondern ich bin vor ihm hergesandt*.", footnotes: ["℘ Kap. 1,8.20; Mt 11,10; Lk 3,15.16"] },
      { number: 29, text: "Der die Braut hat, ist der Bräutigam; der Freund des Bräutigams aber, der dasteht und ihn hört, ist hoch erfreut über die Stimme des Bräutigams; diese meine Freude nun ist erfüllt*.", footnotes: ["℘ Mt 9,15"] },
      { number: 30, text: "Er muss wachsen, ich aber abnehmen." },
      { number: 31, text: "Der von oben kommt, ist über allen; der von der Erde ist, ist von der Erde und redet von der Erde her*. Der vom Himmel kommt, ist über allen*;", footnotes: ["℘ Kap. 8,23", "℘ Mt 12,41.42; 1Kor 15,47"] },
      { number: 32, text: "was er gesehen und gehört hat, das bezeugt er*; und sein Zeugnis nimmt niemand an*.", footnotes: ["℘ Kap. 8,26", "℘ V. 11"] },
      { number: 33, text: "Wer sein Zeugnis angenommen hat, der hat besiegelt, dass Gott wahrhaftig ist*.", footnotes: ["℘ Röm 3,4; 1Jo 5,10"] },
      { number: 34, text: "Denn der, den Gott gesandt hat, redet die Worte Gottes*; denn er gibt den Geist nicht nach Maß.", footnotes: ["℘ Kap. 7,16; 8,26.28.40; 12,49; 14,10; 17,8"] },
      { number: 35, text: "Der Vater liebt den Sohn* und hat alles in seine Hand gegeben*.", footnotes: ["℘ Kap. 5,20; 10,17; 15,9; 17,23.26; Mt 3,17", "℘ Kap. 13,3; 16,15; 17,10; Mt 11,27"] },
      { number: 36, text: "Wer an den Sohn glaubt, hat ewiges Leben*; wer aber dem Sohn nicht gehorcht, wird das Leben nicht sehen, sondern der Zorn Gottes bleibt auf ihm*.", footnotes: ["℘ V. 15.16", "℘ V. 18; Röm 1,18; 1Jo 5,12"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Als nun der Herr erkannte, dass die Pharisäer gehört hatten, dass Jesus mehr Jünger mache und taufe als Johannes*", heading: "Gespräch mit der Samariterin", footnotes: ["℘ Kap. 3,22.26 ⇨Esyn: Synopse Nr. 30"] },
      { number: 2, text: "— obgleich Jesus selbst nicht taufte, sondern seine Jünger —," },
      { number: 3, text: "verließ er Judäa und zog wieder nach Galiläa*.", footnotes: ["℘ V. 43; Mt 4,12"] },
      { number: 4, text: "Er musste aber durch Samaria ziehen. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 31"] },
      { number: 5, text: "Er kommt nun in eine Stadt Samarias, genannt Sychar, nahe bei dem Feld, das Jakob seinem Sohn Josef gab*.", footnotes: ["℘ Jos 24,32"] },
      { number: 6, text: "Es war aber dort eine Quelle Jakobs. Jesus nun, ermüdet von der Reise, setzte sich ohne weiteres* an die Quelle nieder. Es war um die sechste Stunde*.", footnotes: ["w. so", "d. i. zwischen 11 und 12 Uhr vormittags; vgl. auch Anm. zu Kap. 1,39"] },
      { number: 7, text: "Da kommt eine Frau aus Samaria, Wasser zu schöpfen. Jesus spricht zu ihr: Gib mir zu trinken!" },
      { number: 8, text: "— Denn seine Jünger waren weggegangen in die Stadt, um Speise zu kaufen. —" },
      { number: 9, text: "Die samaritische Frau spricht nun zu ihm: Wie bittest du, der du ein Jude bist, von mir zu trinken, die ich eine samaritische Frau bin? — Denn die Juden verkehren nicht mit den Samaritern*. —", footnotes: ["℘ Lk 9,53"] },
      { number: 10, text: "Jesus antwortete und sprach zu ihr: Wenn du die Gabe Gottes* kenntest und wüsstest wer es ist, der zu dir spricht: Gib mir zu trinken!, so hättest du ihn gebeten, und er hätte dir lebendiges Wasser gegeben*.", footnotes: ["℘ 2Kor 9,15", "℘ Kap. 7,37"] },
      { number: 11, text: "Die Frau spricht zu ihm: Herr, du hast kein Schöpfgefäß, und der Brunnen ist tief. Woher hast du denn das lebendige Wasser?" },
      { number: 12, text: "Du bist doch nicht größer als unser Vater Jakob*, der uns den Brunnen gab, und er selbst trank daraus und seine Söhne und sein Vieh?", footnotes: ["℘ Kap. 8,53"] },
      { number: 13, text: "Jesus antwortete und sprach zu ihr: Jeden, der von diesem Wasser trinkt, wird wieder dürsten;" },
      { number: 14, text: "wer aber von dem Wasser trinken wird, das ich ihm geben werde, den wird nicht dürsten in Ewigkeit*; sondern das Wasser, das ich ihm geben werde, wird in ihm eine Quelle Wassers werden, das ins ewige Leben quillt*.", footnotes: ["griech. Äon\n℘ Kap. 6,58", "℘ Kap. 6,27.35; 7,38; Ps 36,10; Offb 21,6"] },
      { number: 15, text: "Die Frau spricht zu ihm: Herr, gib mir dieses Wasser, damit mich nicht dürste und ich nicht hierher komme, um zu schöpfen*.", footnotes: ["℘ Kap. 6,34"] },
      { number: 16, text: "Er spricht zu ihr: Geh hin, rufe deinen Mann und komm hierher!" },
      { number: 17, text: "Die Frau antwortete und sprach zu ihm: Ich habe keinen Mann. Jesus spricht zu ihr: Du hast recht gesagt: Ich habe keinen Mann;" },
      { number: 18, text: "denn fünf Männer hast du gehabt, und der, den du jetzt hast, ist nicht dein Mann; hierin* hast du wahr geredet.", footnotes: ["w. dies"] },
      { number: 19, text: "Die Frau spricht zu ihm: Herr, ich sehe, dass du ein Prophet bist*.", footnotes: ["℘ Kap. 9,17; Lk 7,16"] },
      { number: 20, text: "Unsere Väter haben auf diesem Berg angebetet, und ihr sagt, dass in Jerusalem der Ort sei, wo man anbeten müsse*.", footnotes: ["℘ 5Mo 12,5; 1Kö 9,3; Ps 122,3.4"] },
      { number: 21, text: "Jesus spricht zu ihr: Frau, glaube mir, es kommt die Stunde, da ihr weder auf diesem Berg noch in Jerusalem den Vater anbeten werdet." },
      { number: 22, text: "Ihr betet an, was ihr nicht kennt*; wir beten an, was wir kennen*, denn das Heil* ist aus den Juden*.", footnotes: ["℘ 2Kö 17,41", "℘ Ps 76,2", "o. die Rettung", "℘ Röm 9,5"] },
      { number: 23, text: "Es kommt aber die Stunde und ist jetzt, da die wahren Anbeter den Vater in Geist und Wahrheit anbeten werden*; denn auch der Vater sucht solche als seine Anbeter.", footnotes: ["℘ Phil 3,3"] },
      { number: 24, text: "Gott ist Geist, und die ihn anbeten, müssen in Geist und Wahrheit anbeten*.", footnotes: ["℘ Hebr 10,22"] },
      { number: 25, text: "Die Frau spricht zu ihm: Ich weiß, dass der Messias kommt, der Christus genannt wird*; wenn jener kommt, wird er uns alles verkündigen.", footnotes: ["℘ Kap. 1,41"] },
      { number: 26, text: "Jesus spricht zu ihr: Ich bin es, der mit dir redet*.", footnotes: ["℘ Kap. 9,37"] },
      { number: 27, text: "Und darüber kamen seine Jünger und wunderten sich, dass er mit einer Frau redete. Dennoch sagte niemand: Was suchst du? Oder: Was redest du mit ihr?", heading: "Folgen des Gesprächs mit der Samariterin: Glaube der Samariter — Vom Erntefeld Gottes" },
      { number: 28, text: "Die Frau nun ließ ihren Wasserkrug stehen und ging weg in die Stadt und sagt zu den Leuten:" },
      { number: 29, text: "Kommt, seht einen Menschen, der mir alles gesagt hat, was ich getan habe*! Dieser ist doch nicht etwa der Christus?", footnotes: ["℘ V. 39"] },
      { number: 30, text: "Sie gingen zu der Stadt hinaus und kamen zu ihm." },
      { number: 31, text: "In der Zwischenzeit baten ihn die Jünger und sprachen: Rabbi*, iss!", footnotes: ["d. h. Mein Meister!; respektvolle Anrede der geistlichen Lehrer im Spätjudentum"] },
      { number: 32, text: "Er aber sprach zu ihnen: Ich habe eine Speise zu essen, die ihr nicht kennt." },
      { number: 33, text: "Da sprachen die Jünger zueinander: Hat ihm wohl jemand zu essen gebracht?" },
      { number: 34, text: "Jesus spricht zu ihnen: Meine Speise ist, dass ich den Willen dessen tue, der mich gesandt hat*, und sein Werk vollbringe*.", footnotes: ["℘ Kap. 5,30; 6,38; 7,18; 8,29; 9,4; Ps 40,9; Mt 26,39; Hebr 10,7.9", "℘ Kap. 17,4; Mt 4,4"] },
      { number: 35, text: "Sagt ihr nicht: Es sind noch vier Monate, und die Ernte kommt? Siehe, ich sage euch: Hebt eure Augen auf und schaut die Felder an! Denn sie sind schon weiß zur Ernte." },
      { number: 36, text: "Der da erntet, empfängt Lohn und sammelt Frucht zum ewigen Leben, damit beide, der da sät und der da erntet, sich gemeinsam freuen*.", footnotes: ["℘ 1Kor 3,8.14"] },
      { number: 37, text: "Denn hierin ist der Spruch wahr: Ein anderer ist es, der da sät, und ein anderer, der da erntet." },
      { number: 38, text: "Ich habe euch gesandt zu ernten, woran ihr nicht gearbeitet habt; andere haben gearbeitet, und ihr seid in ihre Arbeit eingetreten." },
      { number: 39, text: "Aus jener Stadt aber glaubten viele von den Samaritern an ihn* um des Wortes der Frau willen, die bezeugte: Er hat mir alles gesagt, was ich getan habe*.", footnotes: ["℘ Kap. 7,31; 8,30; 10,42; 11,45; 12,11", "℘ V. 29"] },
      { number: 40, text: "Als nun die Samariter zu ihm kamen, baten sie ihn, bei ihnen zu bleiben*; und er blieb dort zwei Tage.", footnotes: ["℘ Lk 24,29; Apg 10,48"] },
      { number: 41, text: "Und noch viel mehr Leute glaubten* um seines Wortes willen;", footnotes: ["℘ Kap. 7,31; 8,30; 10,42; 11,45; 12,11"] },
      { number: 42, text: "und sie sagten zu der Frau: Wir glauben nicht mehr um deines Redens willen, denn wir selbst haben gehört und wissen, dass dieser wahrhaftig der Retter der Welt ist*.", footnotes: ["℘ Kap. 6,69; 17,8; 1Jo 4,14"] },
      { number: 43, text: "*Nach den zwei Tagen aber zog er von dort weg nach Galiläa*;", heading: "Heilung des Sohnes eines königlichen Beamten", footnotes: ["℘ vgl. Mt 8,5-13; Lk 7,1-10", "℘ V. 3 ⇨Esyn: Synopse Nr. 32"] },
      { number: 44, text: "denn Jesus selbst bezeugte, dass ein Prophet im eigenen Vaterland* kein Ansehen hat*.", footnotes: ["o. in der eigenen Vaterstadt", "℘ Mt 13,57"] },
      { number: 45, text: "Als er nun nach Galiläa kam, nahmen die Galiläer ihn auf, da sie alles gesehen, was er in Jerusalem auf dem Fest getan hatte*; denn auch sie kamen zu dem Fest*.", footnotes: ["℘ Kap. 2,23", "℘ 5Mo 16,16"] },
      { number: 46, text: "Er kam nun wieder nach Kana in Galiläa, wo er das Wasser zu Wein gemacht hatte*. Und es war in Kapernaum ein königlicher Beamter, dessen Sohn krank war.", footnotes: ["℘ Kap. 2,9 ⇨Esyn: Synopse Nr. 85"] },
      { number: 47, text: "Als dieser gehört hatte, dass Jesus aus Judäa nach Galiläa gekommen sei, ging er zu ihm hin und bat, dass er herabkomme und seinen Sohn heile; denn er lag im Sterben*.", footnotes: ["℘ Mk 5,23"] },
      { number: 48, text: "Jesus sprach nun zu ihm: Wenn ihr nicht Zeichen und Wunder seht, so werdet ihr nicht glauben*.", footnotes: ["℘ Kap. 2,18; 1Kor 1,22"] },
      { number: 49, text: "Der königliche Beamte spricht zu ihm: Herr, komm herab, ehe mein Kind stirbt!" },
      { number: 50, text: "Jesus spricht zu ihm: Geh hin! Dein Sohn lebt. Der Mann glaubte dem Wort, das Jesus zu ihm sagte, und ging hin*.", footnotes: ["℘ Mk 7,30"] },
      { number: 51, text: "Aber schon während er hinabging, kamen ihm seine Knechte* entgegen und berichteten, dass sein Junge lebe.", footnotes: ["w. Sklaven"] },
      { number: 52, text: "Er erforschte nun von ihnen die Stunde, in der es besser mit ihm geworden sei; und sie sagten zu ihm: Gestern zur siebten Stunde verließ ihn das Fieber." },
      { number: 53, text: "Da erkannte der Vater, dass es in jener Stunde war, in der Jesus zu ihm sagte: Dein Sohn lebt*. Und er glaubte, er und sein ganzes Haus*.", footnotes: ["℘ Ps 107,20", "℘ Apg 11,14"] },
      { number: 54, text: "Dies tat Jesus wieder als zweites Zeichen, als er aus Judäa nach Galiläa gekommen war*.", footnotes: ["℘ Kap. 2,11"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Danach war ein Fest der Juden*, und Jesus ging hinauf nach Jerusalem.", heading: "Heilung eines Kranken am Teich Betesda", footnotes: ["℘ Kap. 6,4; 7,2 ⇨Esyn: Synopse Nr. 140"] },
      { number: 2, text: "Es ist aber in Jerusalem bei dem Schaftor ein Teich, der auf Hebräisch Betesda* genannt wird, der fünf Säulenhallen hat. *", footnotes: ["mit anderen alten Handschr.: Bethzatha", "℘ ⇨Esyn: Synopse Nr. 141"] },
      { number: 3, text: "In diesen lag eine Menge Kranker, Blinder, Lahmer, Dürrer." },
      { number: 4, text: "[T>]*", footnotes: ["Andere Handschr. fügen hinzu: die auf die Bewegung des Wassers warteten; 4 denn ein Engel des Herrn stieg zu bestimmter Zeit in den Teich herab und bewegte das Wasser; wer nun nach der Bewegung des Wassers zuerst hineinstieg, wurde gesund, mit welcher Krankheit er auch behaftet war."] },
      { number: 5, text: "Es war aber ein Mensch dort, der achtunddreißig Jahre mit seiner Krankheit behaftet war." },
      { number: 6, text: "Als Jesus diesen daliegen sah und wusste, dass es schon lange Zeit so mit ihm steht, spricht er zu ihm: Willst du gesund werden?" },
      { number: 7, text: "Der Kranke antwortete ihm: Herr, ich habe keinen Menschen*, dass er mich, wenn das Wasser bewegt worden ist, in den Teich werfe; während ich aber komme, steigt ein anderer vor mir hinab.", footnotes: ["℘ Ps 142,5"] },
      { number: 8, text: "Jesus spricht zu ihm: Steh auf, nimm dein Bett auf und geh umher*!", footnotes: ["℘ Mt 9,6"] },
      { number: 9, text: "Und sofort wurde der Mensch gesund und nahm sein Bett auf und ging umher*. Es war aber an jenem Tag Sabbat*.", footnotes: ["℘ Lk 5,25", "℘ Kap. 9,14"] },
      { number: 10, text: "Es sagten nun die Juden zu dem Geheilten: Es ist Sabbat, es ist dir nicht erlaubt, das Bett zu tragen*.", footnotes: ["℘ Jer 17,21.22; Mt 12,2; 23,4"] },
      { number: 11, text: "Er antwortete ihnen: Der mich gesund machte, der sagte zu mir: Nimm dein Bett auf und geh umher." },
      { number: 12, text: "Sie fragten ihn: Wer ist der Mensch, der zu dir sagte: Nimm dein Bett auf und geh umher?" },
      { number: 13, text: "Der Geheilte aber wusste nicht, wer es war; denn Jesus hatte sich entfernt, weil eine Volksmenge an dem Ort war*.", footnotes: ["℘ Kap. 9,12"] },
      { number: 14, text: "Danach findet Jesus ihn im Tempel, und er sprach zu ihm: Siehe, du bist gesund geworden. Sündige nicht mehr*, damit dir nichts Ärgeres widerfahre*!", footnotes: ["℘ Kap. 8,11", "℘ Lk 11,26"] },
      { number: 15, text: "Der Mensch ging hin und verkündete den Juden, dass es Jesus war, der ihn gesund gemacht habe." },
      { number: 16, text: "Und darum verfolgten die Juden Jesus, weil er dies am Sabbat getan hatte*.", footnotes: ["℘ Kap. 7,23; 9,16; Mt 12,14; Lk 13,14"] },
      { number: 17, text: "Jesus aber antwortete ihnen: Mein Vater wirkt bis jetzt, und ich wirke*.", heading: "Jesus verteidigt sein Tun, indem er seine Gottessohnschaft bezeugt", footnotes: ["℘ Kap. 9,4"] },
      { number: 18, text: "Darum nun suchten die Juden noch mehr, ihn zu töten*, weil er nicht allein den Sabbat aufhob*, sondern auch Gott seinen eigenen Vater nannte und sich so selbst Gott gleich machte*.", footnotes: ["℘ Kap. 7,1; 8,37; 11,53", "o. brach; w. auflöste", "℘ Kap. 10,30-33; 19,7; Mt 26,63.64"] },
      { number: 19, text: "Da antwortete Jesus und sprach zu ihnen: Wahrlich, wahrlich, ich sage euch: Der Sohn kann nichts von sich selbst tun, außer was er den Vater tun sieht; denn was der tut, das tut ebenso auch der Sohn*.", footnotes: ["℘ V. 30; Kap. 8,28.36; 14,10"] },
      { number: 20, text: "Denn der Vater hat den Sohn lieb* und zeigt ihm alles, was er selbst tut; und er wird ihm größere Werke als diese zeigen, damit ihr euch wundert.", footnotes: ["℘ Kap. 3,35"] },
      { number: 21, text: "Denn wie der Vater die Toten auferweckt und lebendig macht*, so macht auch der Sohn lebendig, welche er will*.", footnotes: ["℘ 5Mo 32,39; 1Sam 2,6", "℘ 1Kor 15,45"] },
      { number: 22, text: "Denn der Vater richtet auch niemand, sondern das ganze Gericht hat er dem Sohn gegeben*,", footnotes: ["℘ V. 27; Mt 25,31.32; Apg 10,42; 2Kor 5,10"] },
      { number: 23, text: "damit alle den Sohn ehren, wie sie den Vater ehren*. Wer den Sohn nicht ehrt, ehrt den Vater nicht, der ihn gesandt hat*.", footnotes: ["℘ Phil 2,10.11", "℘ Kap. 8,49; 15,23; Lk 10,16; 1Jo 2,23"] },
      { number: 24, text: "Wahrlich, wahrlich, ich sage euch: Wer mein Wort hört und glaubt dem, der mich gesandt hat, der hat ewiges Leben und kommt nicht ins Gericht*, sondern er ist aus dem Tod in das Leben übergegangen*.", footnotes: ["℘ Kap. 3,5.16.18", "℘ 1Jo 3,14"] },
      { number: 25, text: "Wahrlich, wahrlich, ich sage euch, dass die Stunde kommt und jetzt da ist, wo die Toten die Stimme des Sohnes Gottes hören werden, und die sie gehört haben, werden leben*.", footnotes: ["℘ 1Petr 4,6"] },
      { number: 26, text: "Denn wie der Vater Leben in sich selbst hat, so hat er auch dem Sohn gegeben, Leben zu haben in sich selbst*;", footnotes: ["℘ Kap. 1,4; 10,18; 11,25; 14,6"] },
      { number: 27, text: "und er hat ihm Vollmacht gegeben, Gericht zu halten, weil er des Menschen Sohn ist*.", footnotes: ["℘ V. 22; Dan 7,13; Röm 2,16"] },
      { number: 28, text: "Wundert euch darüber nicht, denn es kommt die Stunde, in der alle, die in den Gräbern sind, seine Stimme hören" },
      { number: 29, text: "und hervorkommen werden; die das Gute getan haben zur Auferstehung des Lebens*, die aber das Böse verübt haben zur Auferstehung des Gerichts*.", footnotes: ["℘ Röm 2,7; 1Thes 4,16; Offb 20,6", "℘ Mt 25,46; Apg 24,15; Röm 2,8; Offb 20,12"] },
      { number: 30, text: "Ich kann nichts von mir selbst tun*; so wie ich höre, richte ich, und mein Gericht ist gerecht*, denn ich suche nicht meinen Willen, sondern den Willen dessen, der mich gesandt hat*.", heading: "Jesus nennt die Zeugen seiner Gottessohnschaft", footnotes: ["℘ V. 19", "℘ Kap. 8,16; 2Tim 4,8", "℘ Kap. 4,34"] },
      { number: 31, text: "Wenn ich von mir selbst zeuge, so ist mein Zeugnis nicht wahr*.", footnotes: ["d. h. beglaubigt\n℘ Kap. 8,13"] },
      { number: 32, text: "Ein anderer ist es, der von mir zeugt*, und ich weiß, dass das Zeugnis wahr ist, das er von mir zeugt*.", footnotes: ["℘ V. 37; Kap. 8,18; 1Jo 5,9", "℘ Kap. 7,28; 8,26"] },
      { number: 33, text: "Ihr habt zu Johannes gesandt, und er hat der Wahrheit Zeugnis gegeben*.", footnotes: ["℘ Kap. 1,8.19-34"] },
      { number: 34, text: "Ich aber nehme nicht Zeugnis von einem Menschen an*, sondern dies sage ich, damit ihr gerettet werdet.", footnotes: ["℘ V. 41"] },
      { number: 35, text: "Jener war die brennende und scheinende Lampe; ihr aber wolltet für eine Zeit in seinem Licht fröhlich sein*.", footnotes: ["w. jubeln"] },
      { number: 36, text: "Ich aber habe das Zeugnis, das größer ist als das des Johannes*; denn die Werke, die der Vater mir gegeben hat, dass ich sie vollende, die Werke selbst, die ich tue, zeugen von mir, dass der Vater mich gesandt hat*.", footnotes: ["℘ V. 37; Kap. 8,18; 1Jo 5,9", "℘ Kap. 3,2; 10,25; 11,42; 14,10.11; 15,24; Mt 11,5; Lk 4,18; Apg 2,22"] },
      { number: 37, text: "Und der Vater, der mich gesandt hat, er selbst hat Zeugnis von mir gegeben*. Ihr habt weder jemals seine Stimme gehört noch seine Gestalt gesehen*,", footnotes: ["℘ V. 32; Mt 3,17", "℘ Kap. 1,18"] },
      { number: 38, text: "und sein Wort habt ihr nicht bleibend in euch; denn dem, den er gesandt hat, dem glaubt ihr nicht*.", footnotes: ["℘ Kap. 8,45; 10,26"] },
      { number: 39, text: "Ihr erforscht die Schriften, denn ihr meint, in ihnen ewiges Leben zu haben*, und sie sind es, die von mir zeugen*;", footnotes: ["℘ Hes 20,11; 2Tim 3,15", "℘ V. 46; Kap. 1,45; Hebr 10,7"] },
      { number: 40, text: "und ihr wollt nicht zu mir kommen, damit ihr Leben habt*.", footnotes: ["℘ Mt 23,37"] },
      { number: 41, text: "Ich nehme nicht Ehre von Menschen*;", footnotes: ["℘ V. 34; 1Thes 2,6"] },
      { number: 42, text: "sondern ich kenne euch, dass ihr die Liebe Gottes nicht in euch habt." },
      { number: 43, text: "Ich bin in dem Namen meines Vaters gekommen*, und ihr nehmt mich nicht auf; wenn ein anderer in seinem eigenen Namen kommt, den werdet ihr aufnehmen*.", footnotes: ["℘ Kap. 7,28; 8,42", "℘ Mt 24,5"] },
      { number: 44, text: "Wie könnt ihr glauben, die ihr Ehre voneinander nehmt* und die Ehre, die von dem alleinigen Gott ist, nicht sucht*?", footnotes: ["℘ Mt 6,2; 23,5-7", "℘ Kap. 7,18; 12,43"] },
      { number: 45, text: "Meint nicht, dass ich euch bei dem Vater verklagen werde; da ist einer, der euch verklagt, Mose, auf den ihr eure Hoffnung gesetzt habt*.", footnotes: ["℘ 5Mo 31,26.27"] },
      { number: 46, text: "Denn wenn ihr Mose glaubtet, so würdet ihr mir glauben, denn er hat von mir geschrieben*.", footnotes: ["℘ V. 39; 1Mo 3,15; Ps 40,8; Apg 3,22"] },
      { number: 47, text: "Wenn ihr aber seinen Schriften nicht glaubt, wie werdet ihr meinen Worten glauben*?", footnotes: ["℘ Lk 16,31"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "*Danach ging Jesus weg auf die andere Seite des Sees von Galiläa oder von Tiberias; *", heading: "Speisung der Fünftausend", footnotes: ["℘ Mt 14,13-21; Mk 6,30-44; Lk 9,10-17; vgl. Mt 15,32-39; Mk 8,1-9", "℘ ⇨Esyn: Synopse Nr. 146"] },
      { number: 2, text: "und es folgte ihm eine große Volksmenge, weil sie die Zeichen sahen, die er an den Kranken tat*.", footnotes: ["℘ Kap. 2,23"] },
      { number: 3, text: "Jesus aber ging hinauf auf den Berg und setzte sich dort mit seinen Jüngern*.", footnotes: ["℘ Mt 5,1"] },
      { number: 4, text: "Es war aber das Passah nahe*, das Fest der Juden*.", footnotes: ["℘ Kap. 2,13", "℘ Kap. 5,1"] },
      { number: 5, text: "Als nun Jesus die Augen aufhob und sah, dass eine große Volksmenge zu ihm kommt, spricht er zu Philippus: Woher sollen wir Brote kaufen, dass diese essen?" },
      { number: 6, text: "Dies sagte er aber, um ihn zu prüfen*; denn er selbst wusste, was er tun wollte.", footnotes: ["o. zu versuchen; o. auf die Probe zu stellen"] },
      { number: 7, text: "Philippus antwortete ihm: Für zweihundert Denare Brote reichen nicht für sie hin, dass jeder auch nur ein wenig bekomme." },
      { number: 8, text: "Einer von seinen Jüngern, Andreas, der Bruder des Simon Petrus, spricht zu ihm:" },
      { number: 9, text: "Es ist ein kleiner Junge hier, der fünf Gerstenbrote und zwei Fische hat. Aber was ist dies unter so viele?" },
      { number: 10, text: "Jesus sprach: Macht, dass die Leute sich lagern! Es war aber viel Gras an dem Ort. Es lagerten sich nun die Männer, an Zahl etwa fünftausend." },
      { number: 11, text: "Jesus aber nahm die Brote, und als er gedankt hatte*, teilte er sie denen aus, die da lagerten; ebenso auch von den Fischen*, so viel sie wollten.", footnotes: ["℘ V. 23", "℘ Kap. 21,13"] },
      { number: 12, text: "Als sie aber gesättigt waren, spricht er zu seinen Jüngern: Sammelt die übrig gebliebenen Brocken, damit nichts umkomme!" },
      { number: 13, text: "Sie sammelten nun und füllten zwölf Handkörbe mit Brocken von den fünf Gerstenbroten, welche denen, die gegessen hatten, übrig blieben." },
      { number: 14, text: "Als nun die Leute das Zeichen sahen, das Jesus tat, sprachen sie: Dieser ist wahrhaftig der Prophet, der in die Welt kommen soll*.", footnotes: ["℘ Kap. 1,21"] },
      { number: 15, text: "Da nun Jesus erkannte, dass sie kommen und ihn ergreifen wollten, um ihn zum König zu machen, zog er sich wieder auf den Berg zurück*, er allein*.", footnotes: ["℘ Kap. 18,36", "℘ Mt 14,23"] },
      { number: 16, text: "*Als es aber Abend geworden war, gingen seine Jünger hinab an den See; *", heading: "Jesus geht auf dem See", footnotes: ["℘ Mt 14,22-33; Mk 6,45-52", "℘ ⇨Esyn: Synopse Nr. 147"] },
      { number: 17, text: "und sie stiegen in das Boot und fuhren über den See nach Kapernaum. Und es war schon finster geworden, und Jesus war noch nicht zu ihnen gekommen;" },
      { number: 18, text: "und der See wurde aufgewühlt, da ein starker Wind wehte*.", footnotes: ["℘ Mk 4,37"] },
      { number: 19, text: "Als sie nun etwa fünfundzwanzig oder dreißig Stadien* gerudert waren, sehen sie Jesus auf dem See dahergehen und nahe an das Boot herankommen, und sie fürchteten sich.", footnotes: ["das sind ca. 3,5 oder 5,5 km"] },
      { number: 20, text: "Er aber spricht zu ihnen: Ich bin es*, fürchtet euch nicht!", footnotes: ["℘ Kap. 18,5"] },
      { number: 21, text: "Sie wollten ihn nun in das Boot nehmen, und sogleich war das Boot am Land, wohin sie fuhren*.", footnotes: ["℘ Ps 107,30"] },
      { number: 22, text: "Am folgenden Tag sah die Volksmenge, die jenseits des Sees stand, dass dort kein anderes Boot war als nur eines*, und dass Jesus nicht mit seinen Jüngern in das Boot gestiegen, sondern seine Jünger allein weggefahren waren. *", heading: "Vom Brot des Lebens", footnotes: ["mit einigen Handschr.: jenes, in das seine Jünger gestiegen waren", "℘ ⇨Esyn: Synopse Nr. 148"] },
      { number: 23, text: "Es kamen aber andere Boote aus Tiberias nahe an den Ort, wo sie das Brot gegessen, nachdem der Herr gedankt hatte*.", footnotes: ["℘ V. 11"] },
      { number: 24, text: "Da nun die Volksmenge sah, dass Jesus nicht dort war noch seine Jünger, stiegen sie in die Boote und kamen nach Kapernaum und suchten Jesus*.", footnotes: ["℘ Kap. 11,56"] },
      { number: 25, text: "Und als sie ihn jenseits des Sees gefunden hatten, sprachen sie zu ihm: Rabbi*, wann bist du hierhergekommen?", footnotes: ["d. h. Mein Meister!; respektvolle Anrede der geistlichen Lehrer im Spätjudentum"] },
      { number: 26, text: "Jesus antwortete ihnen und sprach: Wahrlich, wahrlich, ich sage euch: Ihr sucht mich, nicht weil ihr Zeichen gesehen, sondern weil ihr von den Broten gegessen habt und gesättigt worden seid. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 149"] },
      { number: 27, text: "Wirkt nicht für die Speise, die vergeht, sondern für die Speise, die da bleibt ins ewige Leben*, die der Sohn des Menschen euch geben wird*! Denn diesen hat der Vater, Gott, beglaubigt*.", footnotes: ["℘ V. 33; Kap. 4,14", "℘ Lk 10,39.42", "w. versiegelt"] },
      { number: 28, text: "Da sprachen sie zu ihm: Was sollen wir tun*, damit wir die Werke Gottes wirken?", footnotes: ["℘ Mt 19,16; Apg 2,37"] },
      { number: 29, text: "Jesus antwortete und sprach zu ihnen: Dies ist das Werk Gottes, dass ihr an den glaubt, den er gesandt hat*.", footnotes: ["℘ Röm 2,7; 1Thes 1,3; 1Jo 3,23"] },
      { number: 30, text: "Da sprachen sie zu ihm: Was tust du nun für ein Zeichen*, damit wir sehen und dir glauben? Was wirkst du?", footnotes: ["℘ Kap. 2,18"] },
      { number: 31, text: "Unsere Väter aßen das Manna in der Wüste*, wie geschrieben steht: »Brot aus dem Himmel gab er ihnen zu essen.«*", footnotes: ["℘ 5Mo 8,3", "℘ 2Mo 16,4.15; Neh 9,15; Ps 78,24.25; Offb 2,17"] },
      { number: 32, text: "Da sprach Jesus zu ihnen: Wahrlich, wahrlich, ich sage euch: Nicht Mose hat euch das Brot aus dem Himmel gegeben, sondern mein Vater gibt euch das wahrhaftige Brot aus dem Himmel." },
      { number: 33, text: "Denn das Brot Gottes ist der, welcher aus dem Himmel herabkommt und der Welt das Leben gibt*.", footnotes: ["℘ V. 27.51.58; Kap. 10,10"] },
      { number: 34, text: "Da sprachen sie zu ihm: Herr, gib uns allezeit dieses Brot*!", footnotes: ["℘ Kap. 4,15"] },
      { number: 35, text: "Jesus sprach zu ihnen: Ich bin das Brot des Lebens*. Wer zu mir kommt, wird nicht hungern, und wer an mich glaubt, wird nie mehr dürsten*.", footnotes: ["℘ V. 48", "℘ Kap. 4,14; Mt 5,6; Offb 7,16"] },
      { number: 36, text: "Aber ich habe euch gesagt, dass ihr mich auch gesehen habt und nicht glaubt." },
      { number: 37, text: "Alles, was mir der Vater gibt*, wird zu mir kommen, und wer zu mir kommt, den werde ich nicht hinausstoßen;", footnotes: ["℘ Kap. 10,29; 17,6"] },
      { number: 38, text: "denn ich bin vom Himmel herabgekommen*, nicht dass ich meinen Willen tue, sondern den Willen dessen, der mich gesandt hat*.", footnotes: ["℘ Kap. 3,13", "℘ Kap. 4,34"] },
      { number: 39, text: "Dies aber ist der Wille dessen, der mich gesandt hat, dass ich von allem, was er mir gegeben hat, nichts verliere*, sondern es auferwecke am letzten Tag*.", footnotes: ["℘ Kap. 10,28; 17,12; 18,9", "℘ Kap. 11,24; 12,48"] },
      { number: 40, text: "Denn dies ist der Wille meines Vaters, dass jeder, der den Sohn sieht und an ihn glaubt, ewiges Leben habe*; und ich werde ihn auferwecken am letzten Tag*.", footnotes: ["℘ Kap. 3,14-16", "℘ Kap. 11,24; 12,48"] },
      { number: 41, text: "Da murrten die Juden über ihn*, weil er sagte: Ich bin das Brot, das aus dem Himmel herabgekommen ist;", footnotes: ["℘ V. 61"] },
      { number: 42, text: "und sie sprachen: Ist dieser nicht Jesus, der Sohn Josefs*, dessen Vater und Mutter wir kennen*? Wie sagt denn dieser: Ich bin aus dem Himmel herabgekommen?", footnotes: ["℘ Kap. 1,45; Lk 4,22", "℘ Kap. 7,27; 8,14; 9,29; Mt 13,55"] },
      { number: 43, text: "Da antwortete Jesus und sprach zu ihnen: Murrt nicht untereinander!" },
      { number: 44, text: "Niemand kann zu mir kommen, wenn nicht der Vater, der mich gesandt hat, ihn zieht*; und ich werde ihn auferwecken am letzten Tag*.", footnotes: ["℘ V. 65", "℘ Kap. 11,24; 12,48"] },
      { number: 45, text: "Es steht in den Propheten geschrieben: »Und sie werden alle von Gott gelehrt sein*.« Jeder, der von dem Vater gehört und gelernt hat, kommt zu mir.", footnotes: ["℘ Jes 54,13; 1Thes 4,9"] },
      { number: 46, text: "Nicht dass jemand den Vater gesehen hat, außer dem, der von Gott ist, dieser hat den Vater gesehen*.", footnotes: ["℘ Kap. 1,18"] },
      { number: 47, text: "Wahrlich, wahrlich, ich sage euch: Wer glaubt, hat ewiges Leben*.", footnotes: ["℘ Kap. 3,14-16"] },
      { number: 48, text: "Ich bin das Brot des Lebens." },
      { number: 49, text: "Eure Väter haben das Manna in der Wüste gegessen* und sind gestorben*.", footnotes: ["℘ 1Kor 10,3.5", "℘ 1Kor 10,3.5"] },
      { number: 50, text: "Dies aber ist das Brot, das aus dem Himmel herabkommt, damit man davon esse und nicht sterbe*.", footnotes: ["℘ Kap. 11,26"] },
      { number: 51, text: "Ich bin das lebendige Brot, das aus dem Himmel herabgekommen ist*; wenn jemand von diesem Brot isst, wird er leben in Ewigkeit*. Das Brot aber*, das ich geben werde, ist mein Fleisch* für das Leben der Welt.", footnotes: ["℘ V. 33; Kap. 4,14", "griech. Äon\n℘ V. 33; Kap. 4,14", "w. Und das Brot aber", "Andere Handschr. fügen hinzu: das ich geben werde"] },
      { number: 52, text: "Die Juden stritten nun untereinander und sagten: Wie kann dieser uns sein Fleisch zu essen geben?" },
      { number: 53, text: "Da sprach Jesus zu ihnen: Wahrlich, wahrlich, ich sage euch: Wenn ihr nicht das Fleisch des Sohnes des Menschen esst und sein Blut trinkt, so habt ihr kein Leben in euch selbst*.", footnotes: ["℘ 1Jo 5,12"] },
      { number: 54, text: "Wer mein Fleisch isst* und mein Blut trinkt, hat ewiges Leben, und ich werde ihn auferwecken am letzten Tag*;", footnotes: ["w. zerkaut", "℘ Kap. 11,24; 12,48"] },
      { number: 55, text: "denn mein Fleisch ist wahre Speise, und mein Blut ist wahrer Trank." },
      { number: 56, text: "Wer mein Fleisch isst* und mein Blut trinkt, bleibt in mir und ich in ihm*.", footnotes: ["w. zerkaut", "℘ Kap. 15,4; 17,26; 1Jo 3,24"] },
      { number: 57, text: "Wie der lebendige Vater mich gesandt hat, und ich lebe um des Vaters willen*, so auch, wer mich isst*, der wird auch leben um meinetwillen*.", footnotes: ["o. durch den Vater", "w. zerkaut", "o. durch mich"] },
      { number: 58, text: "Dies ist das Brot, das aus dem Himmel herabgekommen ist. Nicht wie die Väter aßen und starben; wer dieses Brot isst*, wird leben in Ewigkeit*.", footnotes: ["w. zerkaut", "griech. Äon\n℘ V. 33; Kap. 4,14"] },
      { number: 59, text: "Dies sprach er, als er in der Synagoge* zu Kapernaum lehrte.", footnotes: ["Versammlungsstätte der jüdischen Gemeinde; s. auch Anm. zu Mt 4,23"] },
      { number: 60, text: "Viele nun von seinen Jüngern, die es gehört hatten, sprachen: Diese Rede ist hart. Wer kann sie hören? *", heading: "Ablehnung der Rede Jesu — Bekenntnis des Petrus — Hinweis auf den Verräter", footnotes: ["℘ ⇨Esyn: Synopse Nr. 157"] },
      { number: 61, text: "Da aber Jesus bei sich selbst wusste, dass seine Jünger hierüber murrten*, sprach er zu ihnen: Ärgert* euch dies?", footnotes: ["℘ V. 41", "Das griech. Wort bedeutet auch: Anstoß geben, zur Sünde verleiten."] },
      { number: 62, text: "Wenn ihr nun den Sohn des Menschen dahin auffahren seht, wo er vorher war*?", footnotes: ["℘ Kap. 3,13; 20,17; Lk 24,51"] },
      { number: 63, text: "Der Geist ist es, der lebendig macht*; das Fleisch nützt nichts*. Die Worte, die ich zu euch geredet habe, sind Geist und sind Leben;", footnotes: ["℘ 2Kor 3,6", "℘ Röm 2,28.29"] },
      { number: 64, text: "aber es sind einige unter euch, die nicht glauben. Denn Jesus wusste von Anfang an, welche es waren, die nicht glaubten*, und wer es war, der ihn überliefern würde*.", footnotes: ["℘ Kap. 2,24.25", "℘ Kap. 13,11"] },
      { number: 65, text: "Und er sprach: Darum habe ich euch gesagt, dass niemand zu mir kommen kann, es sei ihm denn von dem Vater gegeben*.", footnotes: ["℘ V. 44"] },
      { number: 66, text: "Von da an gingen viele seiner Jünger zurück und gingen nicht mehr mit ihm." },
      { number: 67, text: "Da sprach Jesus zu den Zwölfen: Wollt ihr etwa auch weggehen? *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 158"] },
      { number: 68, text: "Simon Petrus antwortete ihm: Herr, zu wem sollten wir gehen? Du hast Worte ewigen Lebens*;", footnotes: ["℘ Apg 5,20"] },
      { number: 69, text: "und wir haben geglaubt und erkannt*, dass du der Heilige Gottes bist*.", footnotes: ["℘ Kap. 4,42", "℘ Mt 16,16; Mk 1,24; Lk 9,20"] },
      { number: 70, text: "Jesus antwortete ihnen: Habe ich nicht euch, die Zwölf, erwählt*? Und von euch ist einer ein Teufel.", footnotes: ["℘ Kap. 13,18; 15,16; Lk 6,13"] },
      { number: 71, text: "Er sprach aber von Judas, dem Sohn des Simon Iskariot*; denn dieser sollte ihn überliefern, einer von den Zwölfen*.", footnotes: ["Der Beiname bedeutete wahrscheinlich »Mann aus Kariot« und diente viell. zur Unterscheidung von dem anderen Jünger namens Judas (vgl. Kap. 14,22).", "℘ Kap. 12,4; 13,26; 18,2; Mt 26,21; Mk 14,10"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Und danach zog Jesus in Galiläa umher*; denn er wollte nicht in Judäa umherziehen*, weil die Juden ihn zu töten suchten*.", heading: "Reise nach Jerusalem zum Laubhüttenfest", footnotes: ["℘ Mt 15,29", "℘ Kap. 11,54", "℘ V. 19.25.30; Kap. 5,18 ⇨Esyn: Synopse Nr. 238"] },
      { number: 2, text: "Es war aber nahe das Fest der Juden*, die Laubhütten*.", footnotes: ["℘ Kap. 5,1", "℘ 3Mo 23,34; 5Mo 16,13"] },
      { number: 3, text: "Es sprachen nun seine Brüder* zu ihm: Zieh von hier fort und geh nach Judäa, dass auch deine Jünger deine Werke sehen, die du tust!", footnotes: ["℘ Kap. 2,12"] },
      { number: 4, text: "Denn niemand tut etwas im Verborgenen und sucht dabei selbst öffentlich bekannt zu sein. Wenn du diese Dinge tust, so zeige dich der Welt!" },
      { number: 5, text: "Denn auch seine Brüder glaubten nicht an ihn*.", footnotes: ["℘ Ps 69,9; Mk 3,21"] },
      { number: 6, text: "Da spricht Jesus zu ihnen: Meine Zeit ist noch nicht da*, eure Zeit aber ist stets bereit.", footnotes: ["℘ Kap. 2,4"] },
      { number: 7, text: "Die Welt kann euch nicht hassen; mich aber hasst sie*, weil ich von ihr zeuge, dass ihre Werke böse sind*.", footnotes: ["℘ Kap. 15,18", "℘ Kap. 3,19.20"] },
      { number: 8, text: "Geht ihr hinauf zu diesem Fest! Ich gehe nicht hinauf zu diesem Fest; denn meine Zeit ist noch nicht erfüllt*.", footnotes: ["℘ V. 30; Kap. 8,20"] },
      { number: 9, text: "Nachdem er dies gesagt hatte, blieb er selbst in Galiläa*.", footnotes: ["mit anderen Handschr.: Nachdem er dies zu ihnen gesagt hatte, blieb er in Galiläa"] },
      { number: 10, text: "Als aber seine Brüder hinaufgegangen waren, da ging auch er hinauf zum Fest, nicht öffentlich, sondern wie im Verborgenen. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 239"] },
      { number: 11, text: "Die Juden nun suchten ihn auf dem Fest und sprachen: Wo ist jener*?", footnotes: ["℘ Kap. 11,56"] },
      { number: 12, text: "Und viel Gemurmel war über ihn unter den Volksmengen; die einen sagten: Er ist gut; andere sagten: Nein, sondern er verführt die Volksmenge*.", footnotes: ["℘ V. 43.47; Kap. 9,16; 10,19; Mt 27,63; Lk 12,51"] },
      { number: 13, text: "Niemand jedoch sprach öffentlich von ihm, aus Furcht vor den Juden*.", footnotes: ["℘ Kap. 9,22; 12,42; 19,38; 20,19"] },
      { number: 14, text: "Als es aber schon um die Mitte des Festes war, ging Jesus hinauf in den Tempel und lehrte*.", heading: "Reden und Auseinandersetzung mit den Juden auf dem Laubhüttenfest", footnotes: ["℘ Kap. 8,2; 18,20; Mt 26,55 ⇨Esyn: Synopse Nr. 240"] },
      { number: 15, text: "Da wunderten sich die Juden und sagten: Wie kennt dieser die Schriften*, da er doch nicht gelernt hat*?", footnotes: ["o. Wie kann dieser überhaupt lesen", "℘ Mt 13,54.55; Mk 6,2; Lk 2,47"] },
      { number: 16, text: "Da antwortete ihnen Jesus und sprach: Meine Lehre ist nicht mein, sondern dessen, der mich gesandt hat*.", footnotes: ["℘ Kap. 3,34; 12,44"] },
      { number: 17, text: "Wenn jemand seinen Willen tun will, so wird er von der Lehre wissen, ob sie aus Gott ist oder ob ich aus mir selbst rede." },
      { number: 18, text: "Wer aus sich selbst redet, sucht seine eigene Ehre*; wer aber die Ehre dessen sucht, der ihn gesandt hat*, der ist wahrhaftig, und Ungerechtigkeit ist nicht in ihm*.", footnotes: ["℘ Kap. 5,41.44", "℘ Kap. 4,34; 8,50", "℘ Kap. 8,46; 18,38; 19,4.6; 1Jo 3,5"] },
      { number: 19, text: "Hat nicht Mose euch das Gesetz gegeben*? Und keiner von euch tut das Gesetz*. Was sucht ihr mich zu töten*?", footnotes: ["℘ Kap. 1,17", "℘ Röm 2,23", "℘ V. 1"] },
      { number: 20, text: "Die Volksmenge antwortete: Du hast einen Dämon*. Wer sucht dich zu töten*?", footnotes: ["℘ Kap. 8,48.52; 10,20; Mt 9,34; Lk 7,33", "℘ Kap. 5,18 ⇨Esyn: Synopse Nr. 117"] },
      { number: 21, text: "Jesus antwortete und sprach zu ihnen: Ein Werk habe ich getan, und ihr alle verwundert euch deswegen*.", footnotes: ["Andere Übersetzer ziehen »deswegen« zum folgenden Satz: Deswegen sage ich euch: Mose"] },
      { number: 22, text: "Mose gab euch die Beschneidung* — nicht dass sie von Mose sei, sondern von den Vätern* —, und am Sabbat beschneidet ihr einen Menschen.", footnotes: ["℘ 3Mo 12,3", "℘ 1Mo 17,10; Röm 4,11"] },
      { number: 23, text: "Wenn ein Mensch die Beschneidung am Sabbat empfängt*, damit das Gesetz Moses nicht aufgehoben* wird, wieso zürnt ihr mir, dass ich einen ganzen Menschen gesund gemacht habe am Sabbat*?", footnotes: ["℘ Mt 12,5", "o. gebrochen; w. aufgelöst", "℘ Kap. 5,9.16"] },
      { number: 24, text: "Richtet nicht nach dem äußeren Anschein, sondern richtet das gerechte Gericht*.", footnotes: ["o. fällt das rechte Urteil\n℘ 5Mo 1,16; 1Sam 16,7"] },
      { number: 25, text: "Es sagten nun einige von den Bewohnern Jerusalems: Ist das nicht der, den sie zu töten suchen*?", footnotes: ["℘ V. 1"] },
      { number: 26, text: "Und siehe, er redet öffentlich, und sie sagen ihm nichts. Haben etwa die Obersten wahrhaftig erkannt, dass dieser der Christus ist*?", footnotes: ["℘ V. 48"] },
      { number: 27, text: "Diesen aber kennen wir, woher er ist*; wenn aber der Christus kommt, so weiß niemand, woher er ist.", footnotes: ["℘ Kap. 6,42"] },
      { number: 28, text: "Jesus nun rief im Tempel, lehrte und sprach: Ihr kennt mich und wisst auch, woher ich bin*; und ich bin nicht von mir selbst gekommen*, sondern der mich gesandt hat, ist wahrhaftig*, den ihr nicht kennt*.", footnotes: ["℘ Kap. 6,42", "℘ Kap. 5,43", "℘ Kap. 5,32", "℘ Kap. 8,19"] },
      { number: 29, text: "Ich kenne ihn*, weil ich von ihm bin und er mich gesandt hat*.", footnotes: ["℘ Kap. 8,55; 10,15; 17,25; Mt 11,27", "℘ 1Jo 4,9.10"] },
      { number: 30, text: "Da suchten sie ihn zu greifen*; und niemand legte die Hand an ihn, weil seine Stunde noch nicht gekommen war*.", footnotes: ["℘ V. 44; Kap. 5,18; 10,39", "℘ V. 8; Kap. 12,27; 13,1; 17,1"] },
      { number: 31, text: "Viele aber von der Volksmenge glaubten an ihn* und sprachen: Wenn der Christus kommt, wird er wohl mehr Zeichen tun als die, welche dieser getan hat*?", footnotes: ["℘ Kap. 4,39", "℘ Kap. 2,23; 3,2; Lk 24,19"] },
      { number: 32, text: "Die Pharisäer hörten die Volksmenge dies über ihn murmeln; und die Pharisäer und die Hohenpriester* sandten Diener, dass sie ihn griffen*.", footnotes: ["Nicht nur der amtierende Hohepriester, sondern alle männlichen Mitglieder der hohenpriesterlichen Familien wurden zu den »Hohenpriestern« gerechnet.", "℘ V. 45"] },
      { number: 33, text: "Da sprach Jesus: Noch eine kleine Zeit bin ich bei euch*, und ich gehe hin zu dem, der mich gesandt hat*.", footnotes: ["℘ Kap. 12,35", "℘ Kap. 14,12; 16,5.16"] },
      { number: 34, text: "Ihr werdet mich suchen und nicht finden, und wo ich bin, könnt ihr nicht hinkommen*.", footnotes: ["℘ Kap. 8,21; 13,33.36"] },
      { number: 35, text: "Es sprachen nun die Juden zueinander: Wohin will dieser gehen, dass wir ihn nicht finden sollen? Will er etwa in die Zerstreuung* der Griechen* gehen und die Griechen lehren?", footnotes: ["℘ Jak 1,1", "d. h. zu den unter den Griechen zerstreut wohnenden Juden"] },
      { number: 36, text: "Was ist das für ein Wort, das er sprach: Ihr werdet mich suchen und nicht finden, und: Wo ich bin, könnt ihr nicht hinkommen?" },
      { number: 37, text: "An dem letzten, dem großen Tag des Festes* aber stand Jesus und rief und sprach: Wenn jemand dürstet, so komme er zu mir und trinke*!", footnotes: ["℘ 3Mo 23,36; 4Mo 29,35", "℘ Kap. 4,10; Jes 55,1; Offb 22,17"] },
      { number: 38, text: "Wer an mich glaubt, wie die Schrift gesagt hat, aus seinem Leibe* werden Ströme lebendigen Wassers fließen*.", footnotes: ["o. aus dessen Innerem; w. aus dessen Bauch", "℘ Kap. 4,14; Jes 58,11"] },
      { number: 39, text: "Dies aber sagte er von dem Geist, den die empfangen sollten, die an ihn glaubten*; denn noch war der Geist nicht da, weil Jesus noch nicht verherrlicht worden war*.", footnotes: ["℘ Kap. 14,16.26; 15,26; Lk 24,49", "℘ Kap. 16,7; Apg 2,33"] },
      { number: 40, text: "Einige nun aus der Volksmenge sagten, als sie diese Worte hörten: Dieser ist wahrhaftig der Prophet*.", heading: "Meinungen des Volkes und des Hohen Rates über Jesus", footnotes: ["℘ Kap. 1,21; Mt 21,11 ⇨Esyn: Synopse Nr. 241"] },
      { number: 41, text: "Andere sagten: Dieser ist der Christus. Andere aber sagten: Der Christus kommt doch nicht aus Galiläa*?", footnotes: ["℘ V. 52"] },
      { number: 42, text: "Hat nicht die Schrift gesagt: Aus der Nachkommenschaft* Davids* und aus Bethlehem, dem Dorf, wo David war, kommt der Christus*?", footnotes: ["w. Aus dem Samen", "℘ Ps 132,11; Mt 1,1; Apg 13,23", "℘ 1Sam 17,12; Mi 5,1; Mt 2,5.6; 22,42"] },
      { number: 43, text: "Es entstand nun seinetwegen eine Spaltung in der Volksmenge*.", footnotes: ["℘ V. 12"] },
      { number: 44, text: "Einige aber von ihnen wollten ihn greifen, aber keiner legte die Hände an ihn*.", footnotes: ["℘ V. 30"] },
      { number: 45, text: "Es kamen nun die Diener zu den Hohenpriestern und Pharisäern, und diese sprachen zu ihnen: Warum habt ihr ihn nicht gebracht*?", footnotes: ["℘ V. 32"] },
      { number: 46, text: "Die Diener antworteten: Niemals hat ein Mensch so geredet wie dieser Mensch*.", footnotes: ["℘ Mt 7,28.29 ⇨Esyn: Synopse Nr. 76"] },
      { number: 47, text: "Da antworteten ihnen die Pharisäer: Seid ihr denn auch verführt*?", footnotes: ["℘ V. 12"] },
      { number: 48, text: "Hat wohl jemand von den Obersten an ihn geglaubt oder von den Pharisäern*?", footnotes: ["℘ V. 26; 1Kor 1,22"] },
      { number: 49, text: "Diese Volksmenge aber, die das Gesetz nicht kennt, sie ist verflucht!" },
      { number: 50, text: "Nikodemus, der früher zu ihm gekommen war und einer von ihnen war*, spricht zu ihnen:", footnotes: ["℘ Kap. 3,1.2"] },
      { number: 51, text: "Richtet denn unser Gesetz den Menschen, ehe es vorher von ihm selbst gehört und erkannt hat, was er tut*?", footnotes: ["℘ 5Mo 1,16.17; Apg 25,16"] },
      { number: 52, text: "Sie antworteten und sprachen zu ihm: Bist du etwa auch aus Galiläa? Forsche und sieh, dass aus Galiläa kein Prophet aufsteht!" },
      { number: 53, text: "*Und jeder ging in sein Haus. *", footnotes: ["In den wichtigsten alten Handschr. ist der Abschnitt 7,53—8,11 nicht enthalten.", "℘ ⇨Esyn: Synopse Nr. 242"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Jesus aber ging nach dem Ölberg*.", footnotes: ["℘ Kap. 18,2; Lk 21,37 ⇨Esyn: Synopse Nr. 274"] },
      { number: 2, text: "Frühmorgens aber kam er wieder in den Tempel, und alles Volk kam zu ihm; und er setzte sich und lehrte sie*.", heading: "Jesus und die Ehebrecherin", footnotes: ["℘ Kap. 7,14; Lk 21,38"] },
      { number: 3, text: "Die Schriftgelehrten und die Pharisäer* aber bringen eine Frau, die beim Ehebruch ergriffen worden war, und stellen sie in die Mitte", footnotes: ["religiöse Partei im Judentum, die auf genaue Einhaltung des Gesetzes Wert legte; s. auch Anm. zu Mt 3,7"] },
      { number: 4, text: "und sagen zu ihm: Lehrer, diese Frau ist auf frischer Tat beim Ehebruch ergriffen worden." },
      { number: 5, text: "In dem Gesetz aber hat uns Mose geboten, solche zu steinigen*. Du nun, was sagst du?", footnotes: ["℘ 3Mo 20,10; 5Mo 22,22"] },
      { number: 6, text: "Dies aber sagten sie, ihn zu versuchen*, damit sie etwas hätten, um ihn anzuklagen*. Jesus aber bückte sich nieder und schrieb mit dem Finger auf die Erde*.", footnotes: ["℘ Mt 16,1; Lk 10,25", "℘ Mt 12,10; Mk 3,2; Lk 20,20", "℘ Jer 17,13"] },
      { number: 7, text: "Als sie aber fortfuhren, ihn zu fragen, richtete er sich auf und sprach zu ihnen: Wer von euch ohne Sünde ist, werfe als Erster einen Stein auf sie*.", footnotes: ["℘ Röm 2,1"] },
      { number: 8, text: "Und wieder bückte er sich nieder und schrieb auf die Erde*.", footnotes: ["℘ Jer 17,13"] },
      { number: 9, text: "Als sie aber dies hörten, gingen sie, einer nach dem anderen, hinaus*, angefangen von den Älteren*; und er wurde allein gelassen mit der Frau, die in der Mitte stand.", footnotes: ["℘ Mt 22,22", "dasselbe griech. Wort, das sonst mit »Älteste« übersetzt wird"] },
      { number: 10, text: "Jesus aber richtete sich auf und sprach zu ihr: Frau, wo sind sie? Hat niemand dich verurteilt?" },
      { number: 11, text: "Sie aber sprach: Niemand, Herr. Jesus aber sprach zu ihr: Auch ich verurteile dich nicht*. Geh hin und sündige von jetzt an nicht mehr*!*", footnotes: ["℘ Kap. 3,17", "℘ Kap. 5,14", "In den wichtigsten alten Handschr. ist der Abschnitt 7,53—8,11 nicht enthalten."] },
      { number: 12, text: "Jesus redete nun wieder zu ihnen und sprach: Ich bin das Licht der Welt*; wer mir nachfolgt, wird nicht in der Finsternis wandeln, sondern wird das Licht des Lebens haben.", heading: "Das Licht der Welt", footnotes: ["℘ Kap. 1,4-9; 9,5; 12,35.46; Jes 42,6; 49,6; 60,1; Mt 5,14 ⇨Esyn: Synopse Nr. 243"] },
      { number: 13, text: "Da sprachen die Pharisäer zu ihm: Du zeugst von dir selbst; dein Zeugnis ist nicht wahr*.", footnotes: ["℘ Kap. 5,31"] },
      { number: 14, text: "Jesus antwortete und sprach zu ihnen: Auch wenn ich von mir selbst zeuge, ist mein Zeugnis wahr, weil ich weiß, woher ich gekommen bin und wohin ich gehe*; ihr aber wisst nicht, woher ich komme oder wohin ich gehe*.", footnotes: ["℘ Kap. 13,1.3; 16,28", "℘ Kap. 7,27.28.35"] },
      { number: 15, text: "Ihr richtet nach dem Fleisch, ich richte niemand*.", footnotes: ["℘ V. 11"] },
      { number: 16, text: "Wenn ich aber auch richte, so ist mein Gericht wahr, weil ich nicht allein bin, sondern ich und der Vater, der mich gesandt hat*.", footnotes: ["℘ V. 29; Kap. 5,30; 16,32"] },
      { number: 17, text: "Aber auch in eurem Gesetz steht geschrieben, dass das Zeugnis zweier Menschen wahr ist*.", footnotes: ["℘ Mt 18,16"] },
      { number: 18, text: "Ich bin es, der von mir selbst zeugt, und der Vater, der mich gesandt hat, zeugt von mir*.", footnotes: ["℘ Kap. 5,32"] },
      { number: 19, text: "Da sprachen sie zu ihm: Wo ist dein Vater? Jesus antwortete: Ihr kennt weder mich noch meinen Vater*; wenn ihr mich gekannt hättet, so würdet ihr auch meinen Vater gekannt haben*.", footnotes: ["℘ V. 55; Kap. 7,28", "℘ Kap. 14,7; 15,21; 16,3; 17,25; Apg 13,27"] },
      { number: 20, text: "Diese Worte redete er in der Schatzkammer, als er im Tempel lehrte; und niemand legte Hand an ihn, denn seine Stunde war noch nicht gekommen*.", footnotes: ["℘ Kap. 7,8; Lk 4,30; 22,53"] },
      { number: 21, text: "Er sprach nun wieder zu ihnen: Ich gehe hin, und ihr werdet mich suchen und werdet in eurer Sünde sterben; wohin ich gehe, könnt ihr nicht hinkommen*.", heading: "Der Gesandte des Vaters", footnotes: ["℘ Kap. 7,34 ⇨Esyn: Synopse Nr. 244"] },
      { number: 22, text: "Da sagten die Juden: Er will sich doch nicht selbst töten, dass er spricht: Wohin ich gehe, könnt ihr nicht hinkommen?" },
      { number: 23, text: "Und er sprach zu ihnen: Ihr seid von dem, was unten ist, ich bin von dem, was oben ist*; ihr seid von dieser Welt, ich bin nicht von dieser Welt*.", footnotes: ["℘ Kap. 3,31", "℘ Kap. 17,16"] },
      { number: 24, text: "Daher sagte ich euch, dass ihr in euren Sünden sterben werdet; denn wenn ihr nicht glauben werdet, dass ich es bin, so werdet ihr in euren Sünden sterben*.", footnotes: ["℘ Kap. 16,9"] },
      { number: 25, text: "Da sprachen sie zu ihm: Wer bist du? Jesus sprach zu ihnen: Durchaus das, was ich auch zu euch rede.*", footnotes: ["o. Was rede ich überhaupt noch zu euch?, o. Vor allem steht fest, dass ich zu euch rede. — Die Übersetzung des schwierigen Satzes ist umstritten."] },
      { number: 26, text: "Vieles habe ich über euch zu reden und zu richten, aber der mich gesandt hat, ist wahrhaftig*; und was ich von ihm gehört habe, das rede ich zu der Welt*.", footnotes: ["℘ Kap. 5,32", "℘ V. 38.40; Kap. 3,32-34"] },
      { number: 27, text: "Sie erkannten nicht, dass er von dem Vater zu ihnen sprach." },
      { number: 28, text: "Da sprach Jesus zu ihnen: Wenn ihr den Sohn des Menschen erhöht haben werdet*, dann werdet ihr erkennen, dass ich es bin und dass ich nichts von mir selbst tue, sondern wie der Vater mich gelehrt hat, das rede ich*.", footnotes: ["℘ Kap. 3,14", "℘ Kap. 5,19; Jes 50,4.5"] },
      { number: 29, text: "Und der mich gesandt hat, ist mit mir; er hat mich nicht allein gelassen*, weil ich allezeit das ihm Wohlgefällige tue*.", footnotes: ["℘ V. 16", "℘ Kap. 4,34"] },
      { number: 30, text: "Als er dies redete, glaubten viele an ihn*.", footnotes: ["℘ Kap. 4,39 ⇨Esyn: Synopse Nr. 245"] },
      { number: 31, text: "Jesus sprach nun zu den Juden, die ihm geglaubt hatten: Wenn ihr in meinem Wort bleibt, so seid ihr wahrhaft meine Jünger*;", heading: "Wahre Freiheit", footnotes: ["℘ Kap. 15,8"] },
      { number: 32, text: "und ihr werdet die Wahrheit erkennen*, und die Wahrheit wird euch frei machen*.", footnotes: ["℘ 2Jo 1", "℘ Jak 1,25"] },
      { number: 33, text: "Sie antworteten ihm: Wir sind Abrahams Nachkommenschaft* und sind nie jemandes Sklaven gewesen*. Wie sagst du: Ihr sollt frei werden?", footnotes: ["w. Same\n℘ V. 39; Mt 3,9", "℘ 5Mo 5,6; Neh 9,36; Jes 26,13"] },
      { number: 34, text: "Jesus antwortete ihnen: Wahrlich, wahrlich, ich sage euch: Jeder, der die Sünde tut, ist der Sünde Sklave*.", footnotes: ["℘ Röm 6,16.20; 2Petr 2,19"] },
      { number: 35, text: "Der Sklave aber bleibt nicht für immer* im Haus*; der Sohn bleibt für immer*.", footnotes: ["w. in das Zeitalter (griech. Äon)", "℘ Gal 4,30", "w. in das Zeitalter (griech. Äon)"] },
      { number: 36, text: "Wenn nun der Sohn euch frei machen wird, so werdet ihr wirklich frei sein*.", footnotes: ["℘ Röm 6,18.22; 1Kor 7,22; 2Kor 3,17; Gal 5,1.13; 1Petr 2,16"] },
      { number: 37, text: "Ich weiß, dass ihr Abrahams Nachkommen seid; aber ihr sucht mich zu töten*, weil mein Wort nicht Raum in euch findet.", heading: "Wahre Nachkommen Abrahams", footnotes: ["℘ Kap. 5,18 ⇨Esyn: Synopse Nr. 246"] },
      { number: 38, text: "Ich rede, was ich bei dem Vater gesehen habe*; auch ihr nun tut, was ihr von eurem* Vater gehört habt*.", footnotes: ["℘ V. 26; Kap. 5,19", "in wichtigen Handschr. nicht enthalten", "℘ V. 44"] },
      { number: 39, text: "Sie antworteten und sprachen zu ihm: Abraham ist unser Vater*. Jesus spricht zu ihnen: Wenn ihr Abrahams Kinder wäret, so würdet ihr die Werke Abrahams tun*;", footnotes: ["℘ V. 33", "℘ Röm 9,7"] },
      { number: 40, text: "jetzt aber sucht ihr mich zu töten, einen Menschen, der ich euch die Wahrheit gesagt habe, die ich von Gott gehört habe*; das hat Abraham nicht getan.", footnotes: ["℘ V. 26"] },
      { number: 41, text: "Ihr tut die Werke eures Vaters. Sie sprachen nun zu ihm: Wir sind nicht durch Hurerei geboren*; wir haben einen Vater, Gott*.", footnotes: ["℘ Jes 57,3", "℘ Jes 63,16; Röm 2,17"] },
      { number: 42, text: "Jesus sprach zu ihnen: Wenn Gott euer Vater wäre, so würdet ihr mich lieben, denn ich bin von Gott ausgegangen und gekommen; denn ich bin auch nicht von mir selbst gekommen, sondern er hat mich gesandt*.", footnotes: ["℘ Kap. 5,43"] },
      { number: 43, text: "Warum versteht ihr meine Sprache nicht? Weil ihr mein Wort nicht hören könnt*.", footnotes: ["℘ Jer 6,10"] },
      { number: 44, text: "Ihr seid aus dem Vater, dem Teufel*, und die Begierden eures Vaters wollt ihr tun*. Jener war ein Menschenmörder von Anfang an und stand nicht in der Wahrheit, weil keine Wahrheit in ihm ist. Wenn er die Lüge redet, so redet er aus seinem Eigenen, denn er ist ein Lügner und der Vater derselben*.", footnotes: ["℘ V. 38; Mt 13,38", "℘ 1Jo 3,8", "d. h. der Lüge\n℘ 1Mo 3,4.13"] },
      { number: 45, text: "Weil ich aber die Wahrheit sage, glaubt ihr mir nicht*.", footnotes: ["℘ Kap. 3,12; 5,38"] },
      { number: 46, text: "Wer von euch überführt mich einer Sünde*? Wenn ich die Wahrheit sage, warum glaubt ihr mir nicht?", footnotes: ["w. wegen einer Sünde\n℘ Kap. 7,18; Mt 27,23; 2Kor 5,21; Hebr 4,15; 1Petr 2,22"] },
      { number: 47, text: "Wer aus Gott ist, hört die Worte Gottes. Darum hört ihr nicht, weil ihr nicht aus Gott seid*.", footnotes: ["℘ Kap. 10,27; 18,37; 1Kor 2,4.7; 1Jo 4,6"] },
      { number: 48, text: "Die Juden antworteten und sprachen zu ihm: Sagen wir nicht recht, dass du ein Samariter bist und einen Dämon hast*?", footnotes: ["℘ Kap. 7,20 ⇨Esyn: Synopse Nr. 247"] },
      { number: 49, text: "Jesus antwortete: Ich habe keinen Dämon, sondern ich ehre meinen Vater, und ihr verunehrt mich*.", footnotes: ["℘ Kap. 5,23"] },
      { number: 50, text: "Ich aber suche nicht meine Ehre*: Es ist einer, der sie sucht und der richtet*.", footnotes: ["℘ Kap. 7,18", "℘ Kap. 3,17"] },
      { number: 51, text: "Wahrlich, wahrlich, ich sage euch: Wenn jemand mein Wort bewahren* wird, so wird er den Tod nicht sehen in Ewigkeit*. *", footnotes: ["o. halten", "griech. Äon", "℘ ⇨Esyn: Synopse Nr. 367"] },
      { number: 52, text: "Die Juden sprachen nun zu ihm: Jetzt erkennen wir, dass du einen Dämon hast*. Abraham ist gestorben und die Propheten*, und du sagst: Wenn jemand mein Wort bewahren* wird, so wird er den Tod nicht schmecken in Ewigkeit*.", footnotes: ["℘ Kap. 7,20", "℘ Sach 1,5", "o. halten", "griech. Äon"] },
      { number: 53, text: "Bist du etwa größer als unser Vater Abraham, der gestorben ist*? Und die Propheten sind gestorben. Was machst du aus dir selbst?", footnotes: ["℘ Kap. 4,12"] },
      { number: 54, text: "Jesus antwortete: Wenn ich mich selbst ehre, so ist meine Ehre nichts; mein Vater ist es, der mich ehrt, von dem ihr sagt: Er ist unser Gott." },
      { number: 55, text: "Und ihr habt ihn nicht erkannt*, ich aber kenne ihn*; und wenn ich sagte: Ich kenne ihn nicht, so würde ich euch gleich sein: ein Lügner. Aber ich kenne ihn*, und ich bewahre* sein Wort.", footnotes: ["℘ V. 19", "℘ Kap. 7,29", "℘ Kap. 7,20", "o. halte"] },
      { number: 56, text: "Abraham, euer Vater, jubelte, dass er meinen Tag sehen sollte, und er sah ihn und freute sich*.", footnotes: ["℘ Hebr 11,13"] },
      { number: 57, text: "Da sprachen die Juden zu ihm: Du bist noch nicht fünfzig Jahre alt und hast Abraham gesehen?" },
      { number: 58, text: "Jesus sprach zu ihnen: Wahrlich, wahrlich, ich sage euch: Ehe Abraham war, bin ich*.", footnotes: ["℘ Kap. 1,1.2; Mi 5,1; Kol 1,17"] },
      { number: 59, text: "Da hoben sie Steine auf, um sie auf ihn zu werfen*. Jesus aber verbarg sich und ging aus dem Tempel hinaus*.", footnotes: ["℘ Kap. 10,31.39; 11,8", "℘ Kap. 12,36"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Und als er vorüberging, sah er einen Menschen, blind von Geburt. *", heading: "Heilung eines Blindgeborenen", footnotes: ["℘ ⇨Esyn: Synopse Nr. 248"] },
      { number: 2, text: "Und seine Jünger fragten ihn und sagten: Rabbi*, wer hat gesündigt, dieser oder seine Eltern, dass er blind geboren wurde*?", footnotes: ["d. h. Mein Meister!; respektvolle Anrede der geistlichen Lehrer im Spätjudentum", "℘ 2Mo 20,5; Lk 13,2"] },
      { number: 3, text: "Jesus antwortete: Weder dieser hat gesündigt noch seine Eltern, sondern damit die Werke Gottes an ihm offenbart würden*.", footnotes: ["℘ Kap. 11,4"] },
      { number: 4, text: "Wir müssen die Werke dessen wirken, der mich gesandt hat*, solange es Tag ist; es kommt die Nacht, da niemand wirken kann.", footnotes: ["℘ Kap. 4,34; 5,17.19"] },
      { number: 5, text: "Solange ich in der Welt bin, bin ich das Licht der Welt*.", footnotes: ["℘ Kap. 8,12; 11,9"] },
      { number: 6, text: "Als er dies gesagt hatte, spie er auf die Erde und bereitete einen Teig aus dem Speichel und strich den Teig auf seine Augen*;", footnotes: ["℘ Mt 9,29; Mk 7,33"] },
      { number: 7, text: "und er sprach zu ihm: Geh hin, wasche dich in dem Teich Siloah! — was übersetzt wird: Gesandter. Da ging er hin und wusch sich und kam sehend*.", footnotes: ["℘ Kap. 11,37; Mk 8,25; 10,52"] },
      { number: 8, text: "Die Nachbarn nun und die, die ihn früher gesehen hatten, dass er ein Bettler war, sprachen: Ist dieser nicht der, der da saß und bettelte?", heading: "Der Geheilte und die Juden" },
      { number: 9, text: "Einige sagten: Er ist es; andere sagten: Nein, sondern er ist ihm ähnlich. Er sagte: Ich bin es." },
      { number: 10, text: "Sie sprachen nun zu ihm: Wie sind denn deine Augen geöffnet worden?" },
      { number: 11, text: "Er antwortete: Der Mensch, der Jesus heißt, bereitete einen Teig und salbte meine Augen damit und sprach zu mir: Geh hin nach Siloah und wasche dich! Als ich aber hinging und mich wusch, wurde ich sehend." },
      { number: 12, text: "Da sprachen sie zu ihm: Wo ist jener? Er sagt: Ich weiß es nicht*.", footnotes: ["℘ Kap. 5,12.13"] },
      { number: 13, text: "Sie führen ihn, den einst Blinden, zu den Pharisäern." },
      { number: 14, text: "Es war aber Sabbat*, als Jesus den Teig bereitete und seine Augen öffnete.", footnotes: ["℘ Kap. 5,9"] },
      { number: 15, text: "Nun fragten ihn wieder auch die Pharisäer, wie er sehend geworden sei. Er aber sprach zu ihnen: Er legte Teig auf meine Augen, und ich wusch mich, und ich sehe." },
      { number: 16, text: "Da sprachen einige von den Pharisäern: Dieser Mensch ist nicht von Gott, denn er hält den Sabbat nicht*. Andere sagten: Wie kann ein sündiger Mensch solche Zeichen tun*? Und es war Zwiespalt unter ihnen*.", footnotes: ["℘ Kap. 5,16", "℘ V. 31.33", "℘ Kap. 7,12"] },
      { number: 17, text: "Sie sagen nun wieder zu dem Blinden: Was sagst du von ihm, weil er deine Augen geöffnet hat? Er aber sprach: Er ist ein Prophet*.", footnotes: ["℘ Kap. 4,19"] },
      { number: 18, text: "Es glaubten nun die Juden nicht von ihm, dass er blind war und sehend geworden, bis sie die Eltern dessen riefen, der sehend geworden war." },
      { number: 19, text: "Und sie fragten sie und sprachen: Ist dieser euer Sohn, von dem ihr sagt, dass er blind geboren wurde? Wie sieht er denn jetzt?" },
      { number: 20, text: "Seine Eltern antworteten und sprachen: Wir wissen, dass dieser unser Sohn ist und dass er blind geboren wurde;" },
      { number: 21, text: "wie er aber jetzt sieht, wissen wir nicht, oder wer seine Augen geöffnet hat, wissen wir nicht. Fragt ihn! Er ist mündig, er wird selbst über sich reden." },
      { number: 22, text: "Dies sagten seine Eltern, weil sie die Juden fürchteten*; denn die Juden waren schon übereingekommen, dass, wenn jemand ihn als Christus bekennen würde, er aus der Synagoge ausgeschlossen werden sollte*.", footnotes: ["℘ Kap. 7,13", "℘ Kap. 12,42; 16,2"] },
      { number: 23, text: "Deswegen sagten seine Eltern: Er ist mündig, fragt ihn!" },
      { number: 24, text: "Sie riefen nun zum zweiten Mal den Menschen, der blind gewesen war, und sprachen zu ihm: Gib Gott die Ehre*! Wir wissen, dass dieser Mensch ein Sünder ist.", footnotes: ["℘ Jos 7,19"] },
      { number: 25, text: "Da antwortete er: Ob er ein Sünder ist, weiß ich nicht; eins weiß ich, dass ich blind war und jetzt sehe." },
      { number: 26, text: "Und sie sprachen wieder zu ihm: Was hat er dir getan? Wie öffnete er deine Augen?" },
      { number: 27, text: "Er antwortete ihnen: Ich habe es euch schon gesagt, und ihr habt nicht gehört. Warum wollt ihr es nochmals hören? Wollt ihr etwa auch seine Jünger werden?" },
      { number: 28, text: "Sie schmähten ihn und sprachen: Du bist sein Jünger; wir aber sind Moses Jünger*.", footnotes: ["℘ Mt 23,2"] },
      { number: 29, text: "Wir wissen, dass Gott zu Mose geredet hat; von diesem aber wissen wir nicht, woher er ist*.", footnotes: ["℘ Kap. 6,42"] },
      { number: 30, text: "Der Mensch antwortete und sprach zu ihnen: Hierbei ist es doch erstaunlich, dass ihr nicht wisst, woher er ist*, und er hat doch meine Augen geöffnet*.", footnotes: ["℘ Jes 29,14", "℘ Jes 42,7"] },
      { number: 31, text: "Wir wissen, dass Gott Sünder nicht hört*, sondern wenn jemand gottesfürchtig ist und seinen Willen tut, den hört er*.", footnotes: ["℘ Ps 66,18; Jes 1,15; Jak 4,3", "℘ Ps 145,19; Spr 15,29; 1Petr 3,12"] },
      { number: 32, text: "Von Anbeginn* hat man nicht gehört, dass jemand die Augen eines Blindgeborenen geöffnet habe*.", footnotes: ["o. Von Ewigkeit (griech. Äon) her", "℘ Ps 146,8"] },
      { number: 33, text: "Wenn dieser nicht von Gott wäre, so könnte er nichts tun*.", footnotes: ["℘ V. 16; Kap. 3,2"] },
      { number: 34, text: "Sie antworteten und sprachen zu ihm: Du bist ganz in Sünden geboren, und du lehrst uns? Und sie warfen ihn hinaus." },
      { number: 35, text: "Jesus hörte, dass sie ihn hinausgeworfen hatten; und als er ihn fand, sprach er: Glaubst du an den Sohn des Menschen*?", heading: "Der Geheilte und der Sohn Gottes", footnotes: ["mit anderen Handschr.: den Sohn Gottes\n℘ Kap. 12,23.34; Lk 18,8"] },
      { number: 36, text: "Er antwortete und sprach: Und wer ist es, Herr, dass ich an ihn glaube?" },
      { number: 37, text: "Jesus sprach zu ihm: Du hast ihn gesehen, und der mit dir redet, der ist es*.", footnotes: ["℘ Kap. 4,26"] },
      { number: 38, text: "Er aber sprach: Ich glaube, Herr*. Und er warf sich vor ihm nieder*.", footnotes: ["℘ Kap. 11,27", "℘ Mt 14,33"] },
      { number: 39, text: "Und Jesus sprach: Zum Gericht bin ich in diese Welt gekommen, damit die Nichtsehenden sehen und die Sehenden blind werden*.", footnotes: ["℘ Mt 13,15; 23,16 ⇨Esyn: Synopse Nr. 303"] },
      { number: 40, text: "Einige von den Pharisäern, die bei ihm waren, hörten dies und sprachen zu ihm: Sind denn auch wir blind*?", footnotes: ["℘ Offb 3,17"] },
      { number: 41, text: "Jesus sprach zu ihnen: Wenn ihr blind wäret, so hättet ihr keine Sünde*. Nun aber sagt ihr: Wir sehen. Daher bleibt eure Sünde.", footnotes: ["℘ Kap. 15,22.24"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Wahrlich, wahrlich, ich sage euch: Wer nicht durch die Tür in den Hof der Schafe hineingeht, sondern anderswo hinübersteigt, der ist ein Dieb und ein Räuber*.", heading: "Der gute Hirte", footnotes: ["℘ V. 8; Jer 23,1.2; Hes 34,2.3 ⇨Esyn: Synopse Nr. 249"] },
      { number: 2, text: "Wer aber durch die Tür hineingeht, ist Hirte der Schafe." },
      { number: 3, text: "Diesem öffnet der Türhüter, und die Schafe hören seine Stimme*, und er ruft die eigenen Schafe mit Namen* und führt sie heraus.", footnotes: ["℘ V. 16.27", "℘ Jes 43,1"] },
      { number: 4, text: "Wenn er die eigenen Schafe alle herausgebracht hat, geht er vor ihnen her, und die Schafe folgen ihm, weil sie seine Stimme kennen." },
      { number: 5, text: "Einem Fremden aber werden sie nicht folgen, sondern werden vor ihm fliehen, weil sie die Stimme der Fremden nicht kennen." },
      { number: 6, text: "Diese Bildrede sprach Jesus zu ihnen*; sie aber verstanden nicht, was es war, das er zu ihnen redete.", footnotes: ["℘ Kap. 16,25"] },
      { number: 7, text: "Jesus sprach nun wieder zu ihnen: Wahrlich, wahrlich, ich sage euch: Ich bin die Tür der Schafe." },
      { number: 8, text: "Alle, die vor mir gekommen sind, sind Diebe und Räuber*; aber die Schafe hörten nicht auf sie.", footnotes: ["℘ V. 8; Jer 23,1.2; Hes 34,2.3"] },
      { number: 9, text: "Ich bin die Tür; wenn jemand durch mich hineingeht, so wird er gerettet werden* und wird ein- und ausgehen und Weide finden.", footnotes: ["℘ Kap. 14,6"] },
      { number: 10, text: "Der Dieb kommt nur, um zu stehlen und zu schlachten und zu verderben. Ich bin gekommen, damit sie Leben haben* und es in Überfluss haben.", footnotes: ["℘ Kap. 6,33"] },
      { number: 11, text: "Ich bin der gute Hirte*; der gute Hirte lässt* sein Leben für die Schafe*.", footnotes: ["℘ Ps 23,1; Jes 40,11; Hes 34,11-16; Hebr 13,20; 1Petr 2,25; 5,4", "w. setzt . . . ein", "℘ Kap. 15,13; Mt 20,28"] },
      { number: 12, text: "Wer Mietling* und nicht Hirte ist, wer die Schafe nicht zu eigen hat, sieht den Wolf kommen und verlässt die Schafe und flieht — und der Wolf raubt und zerstreut sie* —,", footnotes: ["ein gegen Lohn angestellter Hirte", "℘ Hes 34,2-6; Sach 11,17"] },
      { number: 13, text: "weil er ein Mietling ist und sich um die Schafe nicht kümmert*.", footnotes: ["o. ihm an den Schafen nichts liegt"] },
      { number: 14, text: "Ich bin der gute Hirte*; und ich kenne die Meinen*, und die Meinen kennen mich,", footnotes: ["℘ Ps 23,1; Jes 40,11; Hes 34,11-16; Hebr 13,20; 1Petr 2,25; 5,4", "℘ V. 27; 2Tim 2,19"] },
      { number: 15, text: "wie der Vater mich kennt und ich den Vater kenne*; und ich lasse* mein Leben für die Schafe*.", footnotes: ["℘ Kap. 7,29", "w. setze . . . ein", "℘ Kap. 15,13; Mt 20,28"] },
      { number: 16, text: "Und ich habe andere Schafe, die nicht aus diesem Hof sind; auch diese muss ich bringen*, und sie werden meine Stimme hören*, und es wird eine Herde, ein Hirte sein*.", footnotes: ["℘ Kap. 11,52; Röm 9,24", "℘ V. 3; Apg 28,28", "℘ Eph 2,14"] },
      { number: 17, text: "Darum liebt mich der Vater*, weil ich mein Leben lasse*, um es wiederzunehmen*.", footnotes: ["℘ Kap. 3,35", "w. einsetze", "℘ Kap. 2,21"] },
      { number: 18, text: "Niemand nimmt es von mir, sondern ich lasse* es von mir selbst*. Ich habe Vollmacht, es zu lassen*, und habe Vollmacht, es wiederzunehmen*. Dieses Gebot habe ich von meinem Vater empfangen*. —", footnotes: ["w. setze . . . ein", "℘ Kap. 19,30; Hebr 9,14", "w. einzusetzen", "℘ Kap. 5,26", "℘ Kap. 14,31"] },
      { number: 19, text: "Es entstand wieder ein Zwiespalt unter den Juden dieser Worte wegen*.", footnotes: ["℘ Kap. 7,12 ⇨Esyn: Synopse Nr. 250"] },
      { number: 20, text: "Viele aber von ihnen sagten: Er hat einen Dämon* und ist von Sinnen*. Was hört ihr ihn?", footnotes: ["℘ Kap. 7,20", "℘ Mk 3,21"] },
      { number: 21, text: "Andere sagten: Diese Reden sind nicht die eines Besessenen. Kann etwa ein Dämon der Blinden Augen öffnen?" },
      { number: 22, text: "Es war damals das Fest der Tempelweihe* in Jerusalem; es war Winter. *", footnotes: ["Fest, das jährlich zur Erinnerung an die Neueinweihung des Tempels durch Judas Makkabäus (165 v. Chr.) begangen wurde", "℘ ⇨Esyn: Synopse Nr. 257"] },
      { number: 23, text: "Und Jesus ging in dem Tempel umher, in der Säulenhalle Salomos*.", footnotes: ["℘ Apg 3,11"] },
      { number: 24, text: "Da umringten ihn die Juden und sprachen zu ihm: Bis wann hältst du unsere Seele hin? Wenn du der Christus bist, so sage es uns frei heraus*.", footnotes: ["℘ Mt 11,3; 26,63"] },
      { number: 25, text: "Jesus antwortete ihnen: Ich habe es euch gesagt, und ihr glaubt nicht. Die Werke, die ich in dem Namen meines Vaters tue, diese zeugen von mir*;", footnotes: ["℘ V. 37; Kap. 5,36"] },
      { number: 26, text: "aber ihr glaubt nicht*, denn ihr seid nicht von meinen Schafen, wie ich euch gesagt habe.", footnotes: ["℘ Kap. 5,38"] },
      { number: 27, text: "Meine Schafe hören meine Stimme*, und ich kenne sie*, und sie folgen mir*;", footnotes: ["℘ V. 3; Kap. 8,47", "℘ V. 14", "℘ Offb 14,4"] },
      { number: 28, text: "und ich gebe ihnen ewiges Leben*, und sie gehen nicht verloren in Ewigkeit*, und niemand wird sie aus meiner Hand rauben.", footnotes: ["℘ Kap. 3,15.16; 17,2", "griech. Äon\n℘ Kap. 6,39"] },
      { number: 29, text: "Mein Vater, der sie mir gegeben hat*, ist größer als alle*, und niemand kann sie aus der Hand meines Vaters rauben*.", footnotes: ["℘ Kap. 6,37", "o. alles\n℘ Kap. 14,28", "℘ 1Petr 1,5"] },
      { number: 30, text: "Ich und der Vater sind eins*.", footnotes: ["℘ Kap. 17,11"] },
      { number: 31, text: "Da hoben die Juden wieder Steine auf, dass sie ihn steinigten*.", heading: "Anschläge gegen Jesus", footnotes: ["℘ Kap. 8,59"] },
      { number: 32, text: "Jesus antwortete ihnen: Viele gute Werke habe ich euch von meinem Vater gezeigt*. Für welches Werk unter ihnen steinigt ihr mich?", footnotes: ["℘ Mt 15,31"] },
      { number: 33, text: "Die Juden antworteten ihm: Wegen eines guten Werkes steinigen wir dich nicht, sondern wegen Lästerung*, und weil du, der du ein Mensch bist*, dich selbst zu Gott machst*.", footnotes: ["℘ Mt 26,65.66; Mk 2,7", "℘ Phil 2,8", "℘ Kap. 5,18"] },
      { number: 34, text: "Jesus antwortete ihnen: Steht nicht in eurem Gesetz geschrieben: »Ich habe gesagt: Ihr seid Götter«*?", footnotes: ["℘ Ps 82,6"] },
      { number: 35, text: "Wenn er jene Götter nannte, an die das Wort Gottes erging — und die Schrift kann nicht aufgelöst werden* —,", footnotes: ["℘ Mt 5,17.18"] },
      { number: 36, text: "sagt ihr von dem, den der Vater geheiligt* und in die Welt gesandt hat*: Du lästerst, weil ich sagte: Ich bin Gottes Sohn*?", footnotes: ["℘ Jer 1,5", "℘ Kap. 5,36", "℘ Mt 27,43"] },
      { number: 37, text: "Wenn ich nicht die Werke meines Vaters tue, so glaubt mir nicht*!", footnotes: ["℘ V. 25"] },
      { number: 38, text: "Wenn ich sie aber tue, so glaubt den Werken, wenn ihr auch mir nicht glaubt, damit ihr erkennt und versteht*, dass der Vater in mir ist* und ich in dem Vater*!", footnotes: ["wörtliche Bedeutung unter Berücksichtigung der grammatischen Zeitformen: damit ihr erkennt und im Erkennen bleibt (nach anderen Handschr.: glaubt)", "℘ 2Kor 5,19", "℘ Kap. 14,10.11; 17,21"] },
      { number: 39, text: "Da suchten sie wieder ihn zu greifen, und er entging ihrer Hand*.", footnotes: ["℘ Kap. 7,30; 8,59"] },
      { number: 40, text: "Und er ging wieder weg jenseits des Jordan an den Ort, wo Johannes zuerst taufte*, und er blieb dort*.", footnotes: ["℘ Kap. 1,28", "℘ Mt 19,1 ⇨Esyn: Synopse Nr. 258"] },
      { number: 41, text: "Und viele kamen zu ihm und sagten: Johannes tat zwar kein Zeichen; alles aber, was Johannes von diesem gesagt hat, war wahr." },
      { number: 42, text: "Und es glaubten dort viele an ihn*.", footnotes: ["℘ Kap. 4,39"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Es war aber einer krank, Lazarus, von Betanien, aus dem Dorf der Maria und ihrer Schwester Marta*.", heading: "Krankheit und Tod des Lazarus", footnotes: ["℘ Lk 10,38.39 ⇨Esyn: Synopse Nr. 259"] },
      { number: 2, text: "Maria aber war es, die den Herrn mit Salböl salbte und seine Füße mit ihren Haaren abtrocknete*; deren Bruder Lazarus war krank.", footnotes: ["℘ Kap. 12,3"] },
      { number: 3, text: "Da sandten die Schwestern zu ihm und ließen ihm sagen: Herr, siehe, der, den du lieb hast, ist krank*!", footnotes: ["℘ V. 36"] },
      { number: 4, text: "Als aber Jesus es hörte, sprach er: Diese Krankheit ist nicht zum Tode, sondern um der Herrlichkeit Gottes willen*, damit der Sohn Gottes durch sie verherrlicht werde.", footnotes: ["℘ V. 40; Kap. 9,3"] },
      { number: 5, text: "Jesus aber liebte die Marta und ihre Schwester und den Lazarus." },
      { number: 6, text: "Als er nun hörte, dass er krank sei, blieb er noch zwei Tage an dem Ort, wo er war." },
      { number: 7, text: "Danach erst spricht er zu den Jüngern: Lasst uns wieder nach Judäa gehen." },
      { number: 8, text: "Die Jünger sagen zu ihm: Rabbi*, eben suchten die Juden dich zu steinigen*, und wieder gehst du dahin?", footnotes: ["d. h. Mein Meister!; respektvolle Anrede der geistlichen Lehrer im Spätjudentum", "℘ Kap. 8,59"] },
      { number: 9, text: "Jesus antwortete: Hat der Tag nicht zwölf Stunden? Wenn jemand am Tag umhergeht, stößt er nicht an, weil er das Licht dieser Welt sieht*;", footnotes: ["℘ Kap. 9,5"] },
      { number: 10, text: "wenn aber jemand in der Nacht umhergeht, stößt er an, weil das Licht nicht in ihm ist*.", footnotes: ["℘ Kap. 12,35; 1Jo 2,11"] },
      { number: 11, text: "Dies sprach er, und danach sagt er zu ihnen: Lazarus, unser Freund, ist eingeschlafen*; aber ich gehe hin, damit ich ihn aufwecke.", footnotes: ["℘ Mt 9,24; 1Thes 4,13-15"] },
      { number: 12, text: "Da sprachen die Jünger zu ihm: Herr, wenn er eingeschlafen ist, so wird er geheilt* werden.", footnotes: ["w. gerettet"] },
      { number: 13, text: "Jesus aber hatte von seinem Tod gesprochen: sie aber meinten, er rede von der Ruhe des Schlafes." },
      { number: 14, text: "Dann nun sagte ihnen Jesus geradeheraus: Lazarus ist gestorben*;", footnotes: ["℘ Kap. 12,1; Lk 8,49"] },
      { number: 15, text: "und ich bin froh um euretwillen, dass ich nicht dort war, damit ihr glaubt*; aber lasst uns zu ihm gehen.", footnotes: ["℘ V. 42"] },
      { number: 16, text: "Da sprach Thomas, der auch Zwilling* genannt ist*, zu den Mitjüngern: Lasst auch uns gehen, dass wir mit ihm sterben*.", footnotes: ["griech. Didymos; die griech. Namensform für aram. Thoma; beides bedeutet »Zwilling«", "℘ Kap. 20,24; 21,2; Mt 10,3", "℘ Mt 26,35"] },
      { number: 17, text: "Als nun Jesus kam, fand er ihn schon vier Tage in der Gruft liegen*.", heading: "Auferweckung des Lazarus", footnotes: ["℘ V. 39"] },
      { number: 18, text: "Betanien aber war nahe bei Jerusalem, etwa fünfzehn Stadien* weit;", footnotes: ["Ein Stadion sind ca. 185 m."] },
      { number: 19, text: "und viele von den Juden waren zu Marta und Maria gekommen, um sie über ihren Bruder zu trösten*.", footnotes: ["℘ 1Chr 7,22; Hi 2,11"] },
      { number: 20, text: "Marta nun, als sie hörte, dass Jesus komme, ging ihm entgegen. Maria aber saß im Haus." },
      { number: 21, text: "Da sprach Marta zu Jesus: Herr, wenn du hier gewesen wärest, so wäre mein Bruder nicht gestorben*;", footnotes: ["℘ V. 32"] },
      { number: 22, text: "und* jetzt weiß ich, dass, was du von Gott bitten magst, Gott dir geben wird*.", footnotes: ["mehrere alte Handschr.: aber auch", "℘ V. 41"] },
      { number: 23, text: "Jesus spricht zu ihr: Dein Bruder wird auferstehen." },
      { number: 24, text: "Marta spricht zu ihm: Ich weiß, dass er auferstehen wird in der Auferstehung am letzten Tag*.", footnotes: ["℘ Kap. 6,39.40.44.54"] },
      { number: 25, text: "Jesus sprach zu ihr: Ich bin die Auferstehung und das Leben*; wer an mich glaubt, wird leben, auch wenn er gestorben ist;", footnotes: ["℘ Kap. 5,26"] },
      { number: 26, text: "und jeder, der da lebt und an mich glaubt, wird nicht sterben in Ewigkeit*. Glaubst du das?", footnotes: ["griech. Äon\n℘ Kap. 3,15.16; 6,50"] },
      { number: 27, text: "Sie spricht zu ihm: Ja, Herr, ich glaube*, dass du der Christus bist, der Sohn Gottes, der in die Welt kommen soll*.", footnotes: ["℘ Kap. 9,38", "℘ Kap. 1,49"] },
      { number: 28, text: "Und als sie dies gesagt hatte, ging sie hin und rief heimlich ihre Schwester Maria und sagte: Der Lehrer ist da und ruft dich*.", footnotes: ["℘ Mk 10,49"] },
      { number: 29, text: "Als jene es hörte, stand sie schnell auf und ging zu ihm." },
      { number: 30, text: "Jesus aber war noch nicht in das Dorf gekommen, sondern war an dem Ort, wo Marta ihm begegnet war." },
      { number: 31, text: "Als nun die Juden, die bei ihr im Haus waren und sie trösteten, sahen, dass Maria schnell aufstand und hinausging, folgten sie ihr, da sie meinten, sie gehe zur Gruft, um dort zu weinen." },
      { number: 32, text: "Als nun Maria dahin kam, wo Jesus war, und ihn sah, fiel sie ihm zu Füßen und sprach zu ihm: Herr, wenn du hier gewesen wärest, so wäre mein Bruder nicht gestorben*.", footnotes: ["℘ V. 21"] },
      { number: 33, text: "Als nun Jesus sie weinen sah und die Juden weinen, die mit ihr gekommen waren, ergrimmte er im Geist und wurde erschüttert*", footnotes: ["w. erschütterte sich\n℘ Kap. 13,21; Mk 7,34"] },
      { number: 34, text: "und sprach: Wo habt ihr ihn hingelegt? Sie sagen zu ihm: Herr, komm und sieh!" },
      { number: 35, text: "Jesus weinte*.", footnotes: ["o. brach in Tränen aus; ein anderes griech. Wort als in V. 33\n℘ Lk 19,41"] },
      { number: 36, text: "Da sprachen die Juden: Siehe, wie lieb hat er ihn gehabt*!", footnotes: ["℘ V. 3"] },
      { number: 37, text: "Einige aber von ihnen sagten: Konnte dieser, der die Augen des Blinden öffnete*, nicht machen, dass auch dieser nicht gestorben wäre?", footnotes: ["℘ Kap. 9,6.7"] },
      { number: 38, text: "Jesus nun, wieder in seinem Innern erzürnt, kommt zur Gruft. Es war aber eine Höhle, und ein Stein lag davor*.", footnotes: ["℘ Mt 27,60"] },
      { number: 39, text: "Jesus spricht: Nehmt den Stein weg! Die Schwester des Verstorbenen, Marta, spricht zu ihm: Herr, er riecht schon, denn er ist vier Tage hier*.", footnotes: ["w. denn er ist viertägig\n℘ V. 17"] },
      { number: 40, text: "Jesus spricht zu ihr: Habe ich dir nicht gesagt, wenn du glaubtest*, so würdest du die Herrlichkeit Gottes sehen*?", footnotes: ["℘ Mk 5,36", "℘ V. 4; Kap. 1,14"] },
      { number: 41, text: "Sie nahmen nun den Stein weg. Jesus aber hob die Augen empor* und sprach: Vater, ich danke dir, dass du mich erhört hast*.", footnotes: ["℘ Kap. 17,1; Mt 14,19", "℘ V. 22; Hebr 5,7"] },
      { number: 42, text: "Ich aber wusste, dass du mich allezeit erhörst*; doch um der Volksmenge willen, die umhersteht, habe ich es gesagt*, damit sie glauben, dass du mich gesandt hast*.", footnotes: ["℘ V. 22; Hebr 5,7", "℘ Kap. 12,30", "℘ V. 15; Kap. 5,36"] },
      { number: 43, text: "Und als er dies gesagt hatte, rief er mit lauter Stimme: Lazarus, komm heraus*!", footnotes: ["℘ Lk 7,14"] },
      { number: 44, text: "Und der Verstorbene kam heraus*, an Füßen und Händen mit Grabtüchern umwickelt, und sein Gesicht war mit einem Schweißtuch umbunden. Jesus spricht zu ihnen: Macht ihn frei und lasst ihn gehen!", footnotes: ["℘ Kap. 12,1; Mt 9,25"] },
      { number: 45, text: "Viele nun von den Juden, die zu Maria gekommen waren und sahen, was er getan hatte, glaubten an ihn*.", footnotes: ["℘ Kap. 4,39 ⇨Esyn: Synopse Nr. 274"] },
      { number: 46, text: "Einige aber von ihnen gingen hin zu den Pharisäern und sagten ihnen, was Jesus getan hatte." },
      { number: 47, text: "Da versammelten die Hohenpriester* und die Pharisäer den Hohen Rat* und sprachen: Was tun wir? Denn dieser Mensch tut viele Zeichen*.", heading: "Ratssitzung über Jesus: Beschluss, ihn zu töten", footnotes: ["Nicht nur der amtierende Hohepriester, sondern alle männlichen Mitglieder der hohenpriesterlichen Familien wurden zu den »Hohenpriestern« gerechnet.", "w. ein Synedrium; s. Anm. zu Mt 26,59\n℘ Mt 26,3", "℘ Kap. 12,37; 20,30; Lk 6,11"] },
      { number: 48, text: "Wenn wir ihn so lassen, werden alle an ihn glauben*, und die Römer werden kommen und unsere Stadt wie auch unsere Nation wegnehmen.", footnotes: ["℘ Kap. 12,17.19"] },
      { number: 49, text: "Einer aber von ihnen, Kaiphas, der jenes Jahr Hoherpriester war*, sprach zu ihnen: Ihr wisst nichts", footnotes: ["℘ Kap. 18,13; Lk 3,2"] },
      { number: 50, text: "und überlegt auch nicht, dass es euch nützlich ist, dass ein Mensch für das Volk sterbe* und nicht die ganze Nation umkomme.", footnotes: ["℘ Kap. 18,14"] },
      { number: 51, text: "Dies aber sagte er nicht aus sich selbst, sondern da er jenes Jahr Hoherpriester war, weissagte er, dass Jesus für die Nation sterben sollte;" },
      { number: 52, text: "und nicht für die Nation allein, sondern dass er auch die zerstreuten Kinder Gottes in eins versammelte*.", footnotes: ["℘ Kap. 10,16"] },
      { number: 53, text: "Von jenem Tag an ratschlagten sie nun, um ihn zu töten*.", footnotes: ["℘ Kap. 5,18; Mk 14,1; Lk 19,47"] },
      { number: 54, text: "Jesus ging nun nicht mehr öffentlich unter den Juden umher*, sondern ging von dort weg in die Gegend nahe bei der Wüste, in eine Stadt mit Namen Ephraim; und dort verweilte er mit den Jüngern.", footnotes: ["℘ Kap. 7,1 ⇨Esyn: Synopse Nr. 261"] },
      { number: 55, text: "Es war aber nahe das Passah der Juden*, und viele gingen aus dem Land hinauf nach Jerusalem vor dem Passah, um sich zu reinigen*.", footnotes: ["℘ Kap. 2,13", "℘ 2Chr 30,17"] },
      { number: 56, text: "Sie suchten nun Jesus* und sprachen, als sie im Tempel standen, untereinander: Was meint ihr? Wird er nicht zu dem Fest kommen*?", footnotes: ["℘ Kap. 6,24", "℘ Kap. 7,11"] },
      { number: 57, text: "Es hatten aber die Hohenpriester und die Pharisäer Befehl gegeben, wenn jemand wisse, wo er sei, dass er es anzeigen solle, damit sie ihn griffen*.", footnotes: ["℘ Mt 26,14"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "*Jesus nun kam sechs Tage vor dem Passah nach Betanien, wo Lazarus war, den Jesus aus den Toten auferweckt hatte*.", heading: "Salbung Jesu in Betanien", footnotes: ["℘ Mt 26,6-13; Mk 14,3-9", "℘ V. 9; Kap. 11,14.43 ⇨Esyn: Synopse Nr. 267"] },
      { number: 2, text: "Sie machten ihm nun dort ein Abendessen*, und Marta diente*; Lazarus aber war einer von denen, die mit ihm zu Tisch lagen.", footnotes: ["o. Gastmahl", "℘ Lk 10,40"] },
      { number: 3, text: "Da nahm Maria ein Pfund* Salböl von echter, sehr kostbarer Narde* und salbte die Füße Jesu und trocknete seine Füße mit ihren Haaren*. Das Haus aber wurde von dem Geruch des Salböls erfüllt.", footnotes: ["w. Litra; s. Tabelle »Gewichte«", "Pflanze, die zur Herstellung von Arzneien, Salben und Ölen diente; als Importartikel aus Indien sehr teuer", "℘ Kap. 11,2; Lk 7,38"] },
      { number: 4, text: "Es sagt aber Judas, der Iskariot*, einer von seinen Jüngern, der ihn überliefern sollte*:", footnotes: ["s. Anm. zu Kap. 6,71", "℘ Kap. 6,71"] },
      { number: 5, text: "Warum ist dieses Salböl nicht für dreihundert Denare verkauft und den Armen gegeben worden?" },
      { number: 6, text: "Er sagte dies aber nicht, weil er für die Armen besorgt war, sondern weil er ein Dieb war und die Kasse hatte* und beiseiteschaffte*, was eingelegt wurde.", footnotes: ["℘ Kap. 13,29", "o. und trug"] },
      { number: 7, text: "Da sprach Jesus: Lass sie! Möge sie es aufbewahrt haben für den Tag meines Begräbnisses*!", footnotes: ["w. Lass sie, damit sie es aufbewahre auf den Tag meines Begräbnisses"] },
      { number: 8, text: "Denn die Armen habt ihr allezeit bei euch, mich aber habt ihr nicht allezeit*.", footnotes: ["℘ Kap. 13,33"] },
      { number: 9, text: "Die große Volksmenge aus den Juden erfuhr nun, dass er dort sei; und sie kamen nicht um Jesu willen allein, sondern damit sie auch den Lazarus sähen, den er aus den Toten auferweckt hatte*.", heading: "Anschläge der Hohenpriester gegen Lazarus", footnotes: ["℘ V. 1 ⇨Esyn: Synopse Nr. 268"] },
      { number: 10, text: "Die Hohenpriester aber ratschlagten, auch den Lazarus zu töten*,", footnotes: ["℘ Lk 16,31"] },
      { number: 11, text: "weil viele von den Juden um seinetwillen hingingen und an Jesus glaubten*.", footnotes: ["℘ Kap. 4,39"] },
      { number: 12, text: "*Am folgenden Tag, als die große Volksmenge, die zu dem Fest gekommen war, hörte, dass Jesus nach Jerusalem komme, *", heading: "Einzug in Jerusalem", footnotes: ["℘ Mt 21,1-11; Mk 11,1-10; Lk 19,28-40", "℘ ⇨Esyn: Synopse Nr. 269"] },
      { number: 13, text: "nahmen sie die Palmzweige und gingen hinaus, ihm entgegen, und schrien: Hosanna!* Gepriesen sei, der da kommt im Namen des Herrn*, und der König Israels*!", footnotes: ["griech. Form des hebr.-aram. Ausdrucks für »Hilf doch Herr!«", "℘ Ps 118,26; Mt 23,39", "℘ Kap. 1,49; 18,37"] },
      { number: 14, text: "Jesus aber fand einen jungen Esel und setzte sich darauf, wie geschrieben steht:" },
      { number: 15, text: "»Fürchte dich nicht, Tochter Zion! Siehe, dein König kommt, sitzend auf einem Eselsfüllen.«*", footnotes: ["℘ Sach 9,9"] },
      { number: 16, text: "Dies verstanden seine Jünger zuerst nicht*; jedoch als Jesus verherrlicht war, da erinnerten sie sich, dass dies von ihm geschrieben war und sie ihm dies getan hatten*.", footnotes: ["℘ Lk 18,34", "℘ Kap. 2,22"] },
      { number: 17, text: "Es bezeugte nun die Volksmenge, die bei ihm war, dass er Lazarus aus dem Grab gerufen und ihn aus den Toten auferweckt habe." },
      { number: 18, text: "Darum ging ihm auch die Volksmenge entgegen, weil sie hörten, dass er dieses Zeichen getan hatte." },
      { number: 19, text: "Da sprachen die Pharisäer zueinander: Ihr seht, dass ihr gar nichts ausrichtet; siehe, die Welt ist ihm nachgegangen*.", footnotes: ["℘ Kap. 11,48"] },
      { number: 20, text: "Es waren aber einige Griechen* unter denen, die hinaufkamen, um auf dem Fest anzubeten*.", heading: "Über das Sterben des Menschensohnes", footnotes: ["wahrscheinlich Proselyten (vgl. Anm. zu Mt 23,15) oder sog. Gottesfürchtige aus der griech. sprechenden Welt des östl. Mittelmeerraumes, die zum Passahfest gekommen waren", "℘ 1Kö 8,41; Apg 8,27 ⇨Esyn: Synopse Nr. 302"] },
      { number: 21, text: "Diese nun kamen zu Philippus von Betsaida in Galiläa* und baten ihn und sagten: Herr, wir möchten Jesus sehen*.", footnotes: ["℘ Kap. 1,44", "℘ Lk 19,3"] },
      { number: 22, text: "Philippus kommt und sagt es Andreas, es kommt Andreas und Philippus, und sie sagen es Jesus." },
      { number: 23, text: "Jesus aber antwortet ihnen und spricht: Die Stunde ist gekommen*, dass der Sohn des Menschen verherrlicht werde*.", footnotes: ["℘ Mt 26,45", "℘ Kap. 13,31; 17,1; Apg 3,13"] },
      { number: 24, text: "Wahrlich, wahrlich, ich sage euch: Wenn das Weizenkorn nicht in die Erde fällt und stirbt, bleibt es allein*; wenn es aber stirbt, bringt es viel Frucht*.", footnotes: ["℘ 1Kor 15,36", "℘ Jes 53,10.11; Hebr 2,10"] },
      { number: 25, text: "Wer sein Leben* liebt, verliert* es; und wer sein Leben in dieser Welt hasst, wird es zum ewigen Leben bewahren*.", footnotes: ["o. seine Seele", "o. verdirbt", "℘ Mt 10,39; Lk 17,33"] },
      { number: 26, text: "Wenn mir jemand dient, so folge er mir nach*! Und wo ich bin, da wird auch mein Diener sein*. Wenn mir jemand dient, so wird der Vater ihn ehren.", footnotes: ["℘ 1Petr 2,21", "℘ Kap. 14,3; 17,24"] },
      { number: 27, text: "Jetzt ist meine Seele bestürzt*. Und was soll ich sagen? Vater, rette mich aus dieser Stunde? Doch darum bin ich in diese Stunde gekommen*.", footnotes: ["o. erschüttert\n℘ Ps 6,4; Mt 26,38", "℘ Kap. 7,30"] },
      { number: 28, text: "Vater, verherrliche deinen Namen! Da kam eine Stimme aus dem Himmel*: Ich habe ihn verherrlicht und werde ihn auch wieder verherrlichen.", footnotes: ["℘ Mt 3,17 ⇨Esyn: Synopse Nr. 161"] },
      { number: 29, text: "Die Volksmenge nun, die dastand und zuhörte, sagte, es habe gedonnert; andere sagten: Ein Engel hat mit ihm geredet*.", footnotes: ["℘ Apg 23,9"] },
      { number: 30, text: "Jesus antwortete und sprach: Nicht um meinetwillen ist diese Stimme geschehen, sondern um euretwillen*.", footnotes: ["℘ Kap. 11,42"] },
      { number: 31, text: "Jetzt ist das Gericht dieser Welt*; jetzt wird der Fürst dieser Welt hinausgeworfen werden*.", footnotes: ["℘ Kap. 16,11; Kol 2,15", "℘ Eph 2,2 ⇨Esyn: Synopse Nr. 180"] },
      { number: 32, text: "Und ich, wenn ich von der Erde erhöht bin*, werde alle zu mir ziehen.", footnotes: ["℘ Kap. 3,14"] },
      { number: 33, text: "Dies aber sagte er, um anzudeuten, welches Todes er sterben sollte*.", footnotes: ["℘ Kap. 18,32"] },
      { number: 34, text: "Die Volksmenge antwortete ihm nun: Wir haben aus dem Gesetz gehört, dass der Christus bleibe in Ewigkeit*, und wie sagst du, dass der Sohn des Menschen erhöht werden müsse? Wer ist dieser, der Sohn des Menschen*?", footnotes: ["griech. Äon\n℘ Lk 1,33", "℘ Mt 16,13"] },
      { number: 35, text: "Da sprach Jesus zu ihnen: Noch eine kleine Zeit ist das Licht* unter euch*. Wandelt, während ihr das Licht habt, damit nicht Finsternis euch ergreife*! Und wer in der Finsternis wandelt, weiß nicht, wohin er geht*.", footnotes: ["℘ Kap. 8,12", "℘ Kap. 7,33", "℘ Jer 13,16", "℘ Kap. 11,10"] },
      { number: 36, text: "Während ihr das Licht habt, glaubt an das Licht*, damit ihr Söhne des Lichtes werdet*! Dies redete Jesus und ging weg und verbarg sich vor ihnen*.", footnotes: ["℘ V. 46", "℘ Lk 16,8; Eph 5,8; 1Thes 5,5", "℘ Kap. 8,59"] },
      { number: 37, text: "Obwohl er aber so viele Zeichen vor ihnen getan hatte*, glaubten sie nicht an ihn,", heading: "Unglaube und Glaube bei den Juden", footnotes: ["℘ Kap. 2,23; 11,47; Apg 2,22 ⇨Esyn: Synopse Nr. 303"] },
      { number: 38, text: "damit das Wort des Propheten Jesaja erfüllt würde, das er sprach: »Herr, wer hat unserer Verkündigung geglaubt, und wem ist der Arm des Herrn offenbart worden?«*", footnotes: ["℘ Jes 53,1; Röm 10,16"] },
      { number: 39, text: "Darum konnten sie nicht glauben, weil Jesaja wieder gesagt hat:" },
      { number: 40, text: "»Er hat ihre Augen verblendet und ihr Herz verstockt*, dass sie nicht mit den Augen sehen und mit dem Herzen verstehen und sich bekehren und ich sie heile.«*", footnotes: ["℘ Ps 81,13", "℘ Jes 6,10; Mt 13,14.15"] },
      { number: 41, text: "Dies sprach Jesaja, weil er seine Herrlichkeit sah und von ihm redete*.", footnotes: ["℘ Jes 6,1.5"] },
      { number: 42, text: "Dennoch aber glaubten auch von den Obersten viele an ihn; doch wegen der Pharisäer bekannten sie ihn nicht, damit sie nicht aus der Synagoge ausgeschlossen würden*;", footnotes: ["℘ Kap. 7,13; 9,22"] },
      { number: 43, text: "denn sie liebten die Ehre bei den Menschen mehr als die Ehre bei Gott*.", footnotes: ["w. die Ehre der Menschen mehr als die Ehre Gottes\n℘ Kap. 5,44"] },
      { number: 44, text: "Jesus aber rief und sprach: Wer an mich glaubt, glaubt nicht an mich, sondern an den, der mich gesandt hat*;", heading: "Abschluss der öffentlichen Wirksamkeit Jesu: Folgen des Glaubens und des Unglaubens", footnotes: ["℘ Kap. 7,16; 13,20; Mt 10,40; 1Petr 1,21 ⇨Esyn: Synopse Nr. 304"] },
      { number: 45, text: "und wer mich sieht, sieht den, der mich gesandt hat*.", footnotes: ["℘ Kap. 14,9; 2Kor 4,6; Kol 1,15; Hebr 1,3"] },
      { number: 46, text: "Ich bin als Licht in die Welt gekommen*, damit jeder, der an mich glaubt, nicht in der Finsternis bleibe*;", footnotes: ["℘ Kap. 8,12", "℘ V. 35.36; Kap. 1,9; 1Petr 2,9"] },
      { number: 47, text: "und wenn jemand meine Worte hört und nicht befolgt*, so richte ich ihn nicht, denn ich bin nicht gekommen, dass ich die Welt richte, sondern dass ich die Welt rette*.", footnotes: ["o. beachtet, einhält", "℘ Kap. 3,17"] },
      { number: 48, text: "Wer mich verwirft und meine Worte nicht annimmt, hat den, der ihn richtet: Das Wort, das ich geredet habe, das wird ihn richten am letzten Tag*.", footnotes: ["℘ Kap. 6,39.40.44.54"] },
      { number: 49, text: "Denn ich habe nicht aus mir selbst geredet, sondern der Vater, der mich gesandt hat, er hat mir ein Gebot gegeben, was ich sagen und was ich reden soll*;", footnotes: ["℘ Kap. 3,34; 5,19"] },
      { number: 50, text: "und ich weiß, dass sein Gebot ewiges Leben ist*. Was ich nun rede, rede ich so, wie mir der Vater gesagt hat*.", footnotes: ["℘ Kap. 3,16", "℘ Kap. 3,34; 5,19"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Vor dem Passahfest aber, als Jesus wusste*, dass seine Stunde gekommen war*, aus dieser Welt zu dem Vater hinzugehen* — da er die Seinen, die in der Welt waren, geliebt hatte, liebte er sie bis ans Ende*.", heading: "Die Fußwaschung", footnotes: ["℘ Kap. 18,4; 19,28", "℘ Kap. 7,30", "℘ Kap. 8,14", "℘ Kap. 15,9; Offb 1,5 ⇨Esyn: Synopse Nr. 309"] },
      { number: 2, text: "Und bei einem Abendessen, als der Teufel schon dem Judas, Simons Sohn, dem Iskariot*, es ins Herz gegeben hatte*, dass er ihn überliefere*,", footnotes: ["Der Beiname bedeutete wahrscheinlich »Mann aus Kariot« und diente viell. zur Unterscheidung von dem anderen Jünger namens Judas (vgl. Kap. 14,22).", "℘ Apg 5,3", "℘ Mk 14,10"] },
      { number: 3, text: "steht Jesus — im Bewusstsein, dass der Vater ihm alles in die Hände gegeben* und dass er von Gott ausgegangen war und zu Gott hingehe* —", footnotes: ["℘ Kap. 3,35", "℘ Kap. 8,14"] },
      { number: 4, text: "von dem Abendessen auf und legt die Oberkleider ab; und er nahm ein leinenes Tuch und umgürtete sich*.", footnotes: ["℘ Lk 12,37 ⇨Esyn: Synopse Nr. 284"] },
      { number: 5, text: "Dann gießt er Wasser in das Waschbecken und fing an, die Füße der Jünger zu waschen und mit dem leinenen Tuch abzutrocknen, mit dem er umgürtet war*.", footnotes: ["℘ Lk 22,27"] },
      { number: 6, text: "Er kommt nun zu Simon Petrus; der spricht zu ihm: Herr, du wäschst meine Füße*?", footnotes: ["℘ Mt 3,14"] },
      { number: 7, text: "Jesus antwortete und sprach zu ihm: Was ich tue, weißt du jetzt nicht, du wirst es aber nachher verstehen." },
      { number: 8, text: "Petrus spricht zu ihm: Du sollst nie und nimmer* meine Füße waschen*! Jesus antwortete ihm: Wenn ich dich nicht wasche, so hast du kein Teil mit mir.", footnotes: ["w. keinesfalls in Ewigkeit (griech. Äon)", "℘ Mt 3,14"] },
      { number: 9, text: "Simon Petrus spricht zu ihm: Herr, nicht meine Füße allein, sondern auch die Hände und das Haupt!" },
      { number: 10, text: "Jesus spricht zu ihm: Wer gebadet ist, hat nicht nötig, sich zu waschen, ausgenommen die Füße, sondern ist ganz rein; und ihr seid rein*, aber nicht alle*.", footnotes: ["℘ Kap. 15,3; 1Kor 6,11; Tit 3,5", "℘ Kap. 6,64"] },
      { number: 11, text: "Denn er kannte den, der ihn überlieferte; darum sagte er: Ihr seid nicht alle rein*.", footnotes: ["℘ Kap. 6,64"] },
      { number: 12, text: "Als er nun ihre Füße gewaschen und seine Oberkleider genommen hatte, legte er sich wieder zu Tisch und sprach zu ihnen: Wisst ihr, was ich euch getan habe? *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 263"] },
      { number: 13, text: "Ihr nennt mich Lehrer und Herr, und ihr sagt recht, denn ich bin es*.", footnotes: ["℘ Mt 23,8"] },
      { number: 14, text: "Wenn nun ich, der Herr und der Lehrer, eure Füße gewaschen habe, so seid auch ihr schuldig, einander die Füße zu waschen." },
      { number: 15, text: "Denn ich habe euch ein Beispiel gegeben, dass auch ihr tut, wie ich euch getan habe*.", footnotes: ["℘ Phil 2,5; Kol 3,13; 1Petr 2,21; 1Jo 2,6"] },
      { number: 16, text: "Wahrlich, wahrlich, ich sage euch: Ein Sklave ist nicht größer als sein Herr, auch ein Gesandter* nicht größer als der, der ihn gesandt hat*.", footnotes: ["o. Apostel", "℘ Kap. 15,20; Mt 10,24 ⇨Esyn: Synopse Nr. 81"] },
      { number: 17, text: "Wenn ihr dies wisst, glückselig seid ihr, wenn ihr es tut*!", footnotes: ["℘ Lk 11,28; Jak 1,25"] },
      { number: 18, text: "*Ich rede nicht von euch allen, ich weiß, welche ich erwählt habe*; aber damit die Schrift erfüllt würde*: »Der mit mir das Brot isst, hat seine Ferse gegen mich aufgehoben.«*", heading: "Bezeichnung des Verräters", footnotes: ["℘ Mt 26,20-25; Mk 14,17-21; Lk 22,14.21-23", "℘ Kap. 6,70", "℘ Kap. 17,12; 19,28; Lk 24,44", "℘ Ps 41,10"] },
      { number: 19, text: "Von jetzt an sage ich es euch, ehe es geschieht, damit ihr, wenn es geschieht, glaubt, dass ich es bin*.", footnotes: ["℘ Kap. 14,29; 16,4"] },
      { number: 20, text: "Wahrlich, wahrlich, ich sage euch: Wer aufnimmt, wen ich senden werde, nimmt mich auf; wer aber mich aufnimmt, nimmt den auf, der mich gesandt hat*.", footnotes: ["℘ Kap. 12,44; Lk 9,48; 10,16 ⇨Esyn: Synopse Nr. 104"] },
      { number: 21, text: "Als Jesus dies gesagt hatte, wurde er im Geist erschüttert* und bezeugte und sprach: Wahrlich, wahrlich, ich sage euch: Einer von euch wird mich überliefern.", footnotes: ["℘ Kap. 11,33 ⇨Esyn: Synopse Nr. 310"] },
      { number: 22, text: "Die Jünger blickten einander an, in Verlegenheit darüber, von wem er rede." },
      { number: 23, text: "Einer von seinen Jüngern, den Jesus liebte*, lag zu Tisch an der Brust Jesu*.", footnotes: ["℘ Kap. 19,26; 20,2; 21,7.20", "Der Ausdruck erklärt sich aus der damaligen Sitte, dass man zu Tisch zu liegen pflegte."] },
      { number: 24, text: "Diesem nun winkt Simon Petrus, zu erfragen, wer es wohl sei, von dem er rede." },
      { number: 25, text: "Jener lehnt sich an die Brust Jesu und spricht zu ihm: Herr, wer ist es*?", footnotes: ["℘ Kap. 21,20"] },
      { number: 26, text: "Jesus antwortete: Der ist es, für den ich den Bissen eintauchen und ihm geben werde. Und als er den Bissen eingetaucht hatte, nimmt er ihn und gibt ihn dem Judas, Simons Sohn, dem Iskariot*.", footnotes: ["Der Beiname bedeutete wahrscheinlich »Mann aus Kariot« und diente viell. zur Unterscheidung von dem anderen Jünger namens Judas (vgl. Kap. 14,22).\n℘ Kap. 6,71"] },
      { number: 27, text: "Und nach dem Bissen fuhr dann der Satan in ihn*. Jesus spricht nun zu ihm: Was du tust, tu schnell!", footnotes: ["℘ Lk 22,3"] },
      { number: 28, text: "Keiner aber von den zu Tisch Liegenden verstand, wozu er ihm dies sagte:" },
      { number: 29, text: "Denn einige meinten, weil Judas die Kasse hatte*, dass Jesus zu ihm sage: Kaufe, was wir für das Fest benötigen, oder dass er den Armen etwas geben solle.", footnotes: ["℘ Kap. 12,6"] },
      { number: 30, text: "Als nun jener den Bissen genommen hatte, ging er sogleich hinaus. Es war aber Nacht." },
      { number: 31, text: "Als er nun hinausgegangen war, spricht Jesus: Jetzt ist der Sohn des Menschen verherrlicht*, und Gott ist verherrlicht in ihm.", heading: "Das neue Gebot: Liebe", footnotes: ["℘ Kap. 12,23 ⇨Esyn: Synopse Nr. 314"] },
      { number: 32, text: "Wenn Gott verherrlicht ist in ihm, so wird auch Gott ihn verherrlichen in sich selbst, und er wird ihn sogleich verherrlichen*.", footnotes: ["℘ Kap. 17,4.5"] },
      { number: 33, text: "Kinder, noch eine kleine Weile bin ich bei euch*; ihr werdet mich suchen, und wie ich den Juden sagte: Wohin ich gehe, könnt ihr nicht hinkommen, so sage ich jetzt auch euch*.", footnotes: ["℘ Kap. 12,8", "℘ Kap. 7,33.34"] },
      { number: 34, text: "Ein neues Gebot gebe ich euch*, dass ihr einander liebt*, damit, wie ich euch geliebt habe*, auch ihr einander liebt.", footnotes: ["℘ 1Jo 2,8", "℘ Kap. 15,12.17; Röm 12,10; 1Thes 4,9; Hebr 13,1; 1Petr 1,22; 1Jo 3,11", "℘ Eph 5,2"] },
      { number: 35, text: "Daran werden alle erkennen, dass ihr meine Jünger seid, wenn ihr Liebe untereinander habt." },
      { number: 36, text: "*Simon Petrus spricht zu ihm: Herr, wohin gehst du*? Jesus antwortete ihm: Wohin ich gehe, dorthin kannst du mir jetzt nicht folgen*; du wirst mir aber später folgen*.", heading: "Ankündigung der Verleugnung durch Petrus", footnotes: ["℘ Mt 26,31-35; Mk 14,27-31; Lk 22,31-34", "℘ Kap. 14,5; 16,5", "℘ Kap. 7,34", "℘ Kap. 21,18.19 ⇨Esyn: Synopse Nr. 367"] },
      { number: 37, text: "Petrus spricht zu ihm: Herr, warum kann ich dir jetzt nicht folgen? Mein Leben will ich für dich lassen." },
      { number: 38, text: "Jesus antwortet: Dein Leben willst du für mich lassen? Wahrlich, wahrlich, ich sage dir, der Hahn wird nicht krähen, bis du mich dreimal verleugnet hast*.", footnotes: ["℘ Kap. 18,27"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Euer Herz werde nicht bestürzt*. Ihr glaubt an Gott, glaubt auch an mich!", heading: "Hingang zum Vater und Wiederkunft — Offenbarung des Vaters", footnotes: ["o. erschüttert; so auch V. 27\n℘ V. 27 ⇨Esyn: Synopse Nr. 317"] },
      { number: 2, text: "Im Hause meines Vaters sind viele Wohnungen. Wenn es nicht so wäre, würde ich euch gesagt haben: Ich gehe hin, euch eine Stätte zu bereiten?*", footnotes: ["o. Wenn es nicht so wäre, würde ich es euch gesagt haben; denn ich gehe hin, euch eine Stätte zu bereiten."] },
      { number: 3, text: "Und wenn ich hingehe und euch eine Stätte bereite, so komme ich wieder* und werde euch zu mir nehmen, damit auch ihr seid, wo ich bin*.", footnotes: ["℘ Apg 1,11; Hebr 9,28; Offb 22,7", "℘ Kap. 12,26; 1Thes 4,17"] },
      { number: 4, text: "Und wohin ich gehe, dahin wisst ihr den Weg." },
      { number: 5, text: "Thomas spricht zu ihm: Herr, wir wissen nicht, wohin du gehst. Und wie können wir den Weg wissen*?", footnotes: ["℘ Kap. 13,36"] },
      { number: 6, text: "Jesus spricht zu ihm: Ich bin der Weg* und die Wahrheit und das Leben*. Niemand kommt zum Vater als nur durch mich*.", footnotes: ["℘ Hebr 10,20", "℘ Kap. 5,26", "℘ Kap. 10,9; 1Petr 3,18"] },
      { number: 7, text: "Wenn ihr mich erkannt habt, werdet ihr auch meinen Vater erkennen*; und von jetzt an erkennt ihr ihn und habt ihn gesehen*.", footnotes: ["mit anderen alten Handschr.: Wenn ihr mich erkannt hättet, würdet ihr auch meinen Vater kennen\n℘ Kap. 8,19", "℘ Kap. 1,18"] },
      { number: 8, text: "Philippus spricht zu ihm: Herr, zeige uns den Vater, und es genügt uns." },
      { number: 9, text: "Jesus spricht zu ihm: So lange Zeit bin ich bei euch, und du hast mich nicht erkannt, Philippus? Wer mich gesehen hat, hat den Vater gesehen*. Und wie sagst du: Zeige uns den Vater?", footnotes: ["℘ Kap. 12,45"] },
      { number: 10, text: "Glaubst du nicht, dass ich in dem Vater bin und der Vater in mir ist? Die Worte, die ich zu euch rede, rede ich nicht von mir selbst*; der Vater aber, der in mir bleibt, tut seine Werke*.", footnotes: ["℘ V. 24; Kap. 3,34", "℘ Kap. 5,19"] },
      { number: 11, text: "Glaubt mir, dass ich in dem Vater bin und der Vater in mir ist*; wenn aber nicht, so glaubt um der Werke selbst willen*!", footnotes: ["℘ V. 20; Kap. 10,38", "℘ Kap. 5,36"] },
      { number: 12, text: "Wahrlich, wahrlich, ich sage euch: Wer an mich glaubt, der wird auch die Werke tun, die ich tue, und wird größere als diese tun, weil ich zum Vater gehe*.", footnotes: ["℘ Kap. 7,33"] },
      { number: 13, text: "Und was ihr bitten werdet in meinem Namen, das werde ich tun*, damit der Vater verherrlicht werde im Sohn.", footnotes: ["℘ Kap. 15,7; Mk 11,24; 1Jo 3,22 ⇨Esyn: Synopse Nr. 275"] },
      { number: 14, text: "Wenn ihr mich* etwas bitten werdet in meinem Namen, so werde ich es tun*.", footnotes: ["in mehreren alten Handschr. nicht enthalten", "℘ Kap. 16,23.24; Mt 7,7.8"] },
      { number: 15, text: "Wenn ihr mich liebt, so werdet ihr meine Gebote halten*;", heading: "Sendung des Beistands", footnotes: ["℘ Kap. 15,10; 1Jo 2,5; 5,3 ⇨Esyn: Synopse Nr. 318"] },
      { number: 16, text: "und ich werde den Vater bitten, und er wird euch einen anderen Beistand* geben*, dass er bei euch sei in Ewigkeit*,", footnotes: ["o. Fürsprecher; o. Helfer; w. der zur Unterstützung Herbeigerufene", "℘ Kap. 7,39", "griech. Äon"] },
      { number: 17, text: "den Geist der Wahrheit*, den die Welt nicht empfangen kann, weil sie ihn nicht sieht noch ihn kennt. Ihr kennt ihn*, denn er bleibt bei euch und wird in euch sein*.", footnotes: ["℘ Kap. 15,26; 16,13; 1Jo 4,6; 5,6", "℘ Röm 8,9", "℘ 1Kor 3,16; 1Jo 2,27"] },
      { number: 18, text: "Ich werde euch nicht verwaist zurücklassen, ich komme zu euch." },
      { number: 19, text: "Noch eine kleine Weile, und die Welt sieht mich nicht mehr; ihr aber seht mich*: Weil ich lebe, werdet auch ihr leben*.", footnotes: ["℘ Kap. 16,16", "℘ 1Thes 5,10"] },
      { number: 20, text: "An jenem Tag werdet ihr erkennen, dass ich in meinem Vater bin* und ihr in mir und ich in euch*.", footnotes: ["℘ V. 10.11", "℘ Kap. 17,21-23; 1Jo 5,20"] },
      { number: 21, text: "Wer meine Gebote hat und sie hält, der ist es, der mich liebt*; wer aber mich liebt, wird von meinem Vater geliebt werden*; und ich werde ihn lieben und mich selbst ihm offenbaren.", footnotes: ["℘ Kap. 15,10; 1Jo 2,5; 5,3", "℘ Kap. 16,27"] },
      { number: 22, text: "Judas, nicht der Iskariot, spricht zu ihm: Herr, wie kommt es, dass du dich uns offenbaren willst und nicht der Welt*?", footnotes: ["℘ Apg 10,41"] },
      { number: 23, text: "Jesus antwortete und sprach zu ihm: Wenn jemand mich liebt, so wird er mein Wort halten*, und mein Vater wird ihn lieben*, und wir werden zu ihm kommen und Wohnung bei ihm machen*.", footnotes: ["o. bewahren\n℘ Kap. 15,10; 1Jo 2,5; 5,3", "℘ Spr 8,17", "℘ Kap. 17,26 ⇨Esyn: Synopse Nr. 359"] },
      { number: 24, text: "Wer mich nicht liebt, hält* meine Worte nicht; und das Wort, das ihr hört, ist nicht mein, sondern des Vaters, der mich gesandt hat*.", footnotes: ["o. bewahrt", "℘ V. 10"] },
      { number: 25, text: "Dies habe ich zu euch geredet, während ich bei euch weile." },
      { number: 26, text: "Der Beistand* aber*, der Heilige Geist, den der Vater senden wird in meinem Namen, der wird euch alles lehren* und euch an alles erinnern, was ich euch gesagt habe*.", footnotes: ["o. Fürsprecher; o. Helfer; w. der zur Unterstützung Herbeigerufene", "℘ Kap. 7,39", "℘ Kap. 16,13; 1Jo 2,20.27", "℘ Kap. 2,22"] },
      { number: 27, text: "Frieden lasse ich euch*, meinen Frieden gebe ich euch*; nicht wie die Welt gibt, gebe ich euch. Euer Herz werde nicht bestürzt*, sei auch nicht furchtsam.", footnotes: ["℘ Röm 5,1; Eph 2,14", "℘ Kap. 16,33; Kol 3,15; 2Thes 3,16", "℘ V. 1 ⇨Esyn: Synopse Nr. 319"] },
      { number: 28, text: "Ihr habt gehört, dass ich euch gesagt habe: Ich gehe hin, und ich komme zu euch. Wenn ihr mich liebtet, so würdet ihr euch freuen, dass ich zum Vater gehe, denn der Vater ist größer als ich*.", footnotes: ["℘ Kap. 10,29"] },
      { number: 29, text: "Und jetzt habe ich es euch gesagt, ehe es geschieht, damit ihr glaubt, wenn es geschieht*.", footnotes: ["℘ Kap. 13,19; Mt 24,25"] },
      { number: 30, text: "Ich werde nicht mehr vieles mit euch reden, denn der Fürst der Welt kommt; und in mir hat er gar nichts*;", footnotes: ["Andere üs.: an mir freilich hat er ganz und gar nichts; d. h. auf mich hat er keinerlei Anspruch"] },
      { number: 31, text: "aber damit die Welt erkenne, dass ich den Vater liebe und so tue, wie mir der Vater geboten hat*. — Steht auf, lasst uns von hier fortgehen*!", footnotes: ["℘ Kap. 10,18", "℘ Mt 26,30 ⇨Esyn: Synopse Nr. 330"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Ich bin der wahre Weinstock*, und mein Vater ist der Weingärtner.", heading: "Der wahre Weinstock", footnotes: ["℘ Ps 80,9 ⇨Esyn: Synopse Nr. 320"] },
      { number: 2, text: "Jede Rebe an mir, die nicht Frucht bringt, die nimmt er weg*; und jede, die Frucht bringt, die reinigt er, dass sie mehr Frucht bringe.", footnotes: ["o. hebt er hoch\n℘ Röm 11,22"] },
      { number: 3, text: "Ihr seid schon rein um des Wortes willen, das ich zu euch geredet habe*.", footnotes: ["℘ Kap. 13,10; Eph 5,26; 1Petr 1,22"] },
      { number: 4, text: "Bleibt in mir* und ich in euch*! Wie die Rebe nicht von sich selbst Frucht bringen kann, sie bleibe denn am Weinstock, so auch ihr nicht, ihr bleibt denn in mir.", footnotes: ["℘ Phil 3,9; 1Jo 2,28", "℘ Kap. 6,56; Gal 4,19"] },
      { number: 5, text: "Ich bin der Weinstock, ihr seid die Reben. Wer in mir bleibt und ich in ihm, der bringt viel Frucht, denn getrennt von mir könnt ihr nichts tun*.", footnotes: ["℘ 2Kor 3,5; Phil 1,11"] },
      { number: 6, text: "Wenn jemand nicht in mir bleibt, so wird er hinausgeworfen wie die Rebe und verdorrt; und man sammelt sie und wirft sie ins Feuer, und sie verbrennen*.", footnotes: ["℘ Mt 3,10"] },
      { number: 7, text: "Wenn ihr in mir bleibt und meine Worte in euch bleiben*, so werdet ihr bitten, was ihr wollt, und es wird euch geschehen*.", footnotes: ["℘ 1Jo 2,14", "℘ V. 16; Kap. 14,13 ⇨Esyn: Synopse Nr. 275"] },
      { number: 8, text: "Hierin wird mein Vater verherrlicht, dass ihr viel Frucht bringt* und meine Jünger werdet*.", footnotes: ["℘ Mt 5,16", "℘ Kap. 8,31"] },
      { number: 9, text: "Wie der Vater mich geliebt hat*, habe auch ich euch geliebt*. Bleibt in meiner Liebe!", heading: "Das Gebot der Liebe", footnotes: ["℘ Kap. 3,35", "℘ Kap. 13,1 ⇨Esyn: Synopse Nr. 321"] },
      { number: 10, text: "Wenn ihr meine Gebote haltet, so werdet ihr in meiner Liebe bleiben*, wie ich die Gebote meines Vaters gehalten habe und in seiner Liebe bleibe.", footnotes: ["℘ Kap. 14,15.21.23"] },
      { number: 11, text: "Dies habe ich zu euch geredet, damit meine Freude in euch sei und eure Freude völlig werde*.", footnotes: ["℘ Kap. 16,24; 17,13; 1Jo 1,4"] },
      { number: 12, text: "Dies ist mein Gebot, dass ihr einander liebt*, wie ich euch geliebt habe*.", footnotes: ["℘ Kap. 13,34", "℘ Eph 5,2.25"] },
      { number: 13, text: "Größere Liebe hat niemand als die, dass er sein Leben hingibt für seine Freunde*.", footnotes: ["℘ Kap. 10,11; 1Jo 3,16"] },
      { number: 14, text: "Ihr seid meine Freunde, wenn ihr tut, was ich euch gebiete." },
      { number: 15, text: "Ich nenne euch nicht mehr Sklaven, denn der Sklave weiß nicht, was sein Herr tut; euch aber habe ich Freunde genannt*, weil ich alles, was ich von meinem Vater gehört, euch kundgetan habe.", footnotes: ["℘ Lk 12,4"] },
      { number: 16, text: "Ihr habt nicht mich erwählt, sondern ich habe euch erwählt* und euch dazu bestimmt*, dass ihr hingeht und Frucht bringt und eure Frucht bleibe*, damit, was ihr den Vater bitten werdet in meinem Namen, er euch gebe*.", footnotes: ["℘ Kap. 6,70; Mk 3,13", "w. gesetzt, o. eingesetzt", "℘ Lk 8,15; Kol 1,10", "℘ V. 7"] },
      { number: 17, text: "Dies gebiete ich euch, dass ihr einander liebt*!", footnotes: ["℘ Kap. 13,34"] },
      { number: 18, text: "Wenn die Welt euch hasst, so wisst, dass sie mich vor euch gehasst hat*.", heading: "Ankündigung von Verfolgungen", footnotes: ["℘ Kap. 7,7; 1Jo 3,13 ⇨Esyn: Synopse Nr. 322"] },
      { number: 19, text: "Wenn ihr von der Welt wäret, würde die Welt das Ihre lieben*; weil ihr aber nicht von der Welt seid, sondern ich euch aus der Welt erwählt habe, darum hasst euch die Welt*.", footnotes: ["℘ 1Jo 4,5", "℘ Kap. 17,14; Gal 4,29"] },
      { number: 20, text: "Gedenkt des Wortes, das ich euch gesagt habe: Ein Sklave ist nicht größer als sein Herr*. Wenn sie mich verfolgt haben, werden sie auch euch verfolgen*; wenn sie mein Wort gehalten haben, werden sie auch das eure halten.", footnotes: ["℘ Kap. 13,16", "℘ Kap. 16,2; 2Tim 3,12"] },
      { number: 21, text: "Aber dies alles werden sie euch tun um meines Namens willen*, weil sie den nicht kennen, der mich gesandt hat*.", footnotes: ["℘ Mt 10,22", "℘ Kap. 8,19"] },
      { number: 22, text: "Wenn ich nicht gekommen wäre und zu ihnen geredet hätte, so hätten sie keine Sünde; jetzt aber haben sie keinen Vorwand für ihre Sünde." },
      { number: 23, text: "Wer mich hasst, hasst auch meinen Vater*.", footnotes: ["℘ Kap. 5,23"] },
      { number: 24, text: "Wenn ich nicht die Werke unter ihnen getan hätte, die kein anderer getan hat*, so hätten sie keine Sünde; jetzt aber haben sie sie gesehen* und doch sowohl mich als auch meinen Vater gehasst.", footnotes: ["℘ Kap. 5,36", "℘ Kap. 9,41"] },
      { number: 25, text: "Aber dies geschieht, damit das Wort erfüllt würde, das in ihrem Gesetz geschrieben steht: »Sie haben mich ohne Ursache gehasst.«*", footnotes: ["℘ Ps 35,19"] },
      { number: 26, text: "Wenn der Beistand* gekommen ist, den ich euch von dem Vater senden werde, der Geist der Wahrheit*, der von dem Vater ausgeht*, so wird der von mir zeugen*.", footnotes: ["o. Fürsprecher; o. Helfer; w. der zur Unterstützung Herbeigerufene", "℘ Kap. 14,17", "℘ Kap. 7,39", "℘ Apg 5,32; 1Jo 5,6 ⇨Esyn: Synopse Nr. 323"] },
      { number: 27, text: "Aber auch ihr zeugt*, weil ihr von Anfang an bei mir seid*.", footnotes: ["℘ Kap. 19,35; 21,24; Mt 10,18; Apg 1,8; 1Petr 5,1; 1Jo 1,2", "℘ Lk 1,2"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Dies habe ich zu euch geredet, damit ihr euch nicht ärgert*.", footnotes: ["Das griech. Wort bedeutet auch: Anstoß nehmen, zu Fall kommen, sich zur Sünde verleiten lassen.\n℘ Mt 13,21 ⇨Esyn: Synopse Nr. 324"] },
      { number: 2, text: "Sie werden euch aus der Synagoge ausschließen*; es kommt sogar die Stunde, dass jeder, der euch tötet*, meinen wird, Gott einen Dienst zu tun*.", footnotes: ["℘ Kap. 9,22", "℘ Mt 24,9", "w. Gottesdienst darzubringen\n℘ V. 33; Kap. 15,20"] },
      { number: 3, text: "Und dies werden sie tun, weil sie weder den Vater noch mich erkannt haben*.", footnotes: ["℘ Kap. 8,19; Röm 10,2; 1Jo 3,1"] },
      { number: 4, text: "Dies aber habe ich zu euch geredet, damit ihr, wenn ihre Stunde* gekommen ist, daran gedenkt, dass ich es euch gesagt habe*. Dies aber habe ich euch von Anfang an nicht gesagt, weil ich bei euch war.", footnotes: ["o. die Stunde dafür", "℘ Kap. 13,19"] },
      { number: 5, text: "Jetzt aber gehe ich hin zu dem, der mich gesandt hat*, und niemand von euch fragt mich: Wohin gehst du*?,", heading: "Die Wirksamkeit des Heiligen Geistes", footnotes: ["℘ V. 16.28; Kap. 7,33", "℘ Kap. 13,36 ⇨Esyn: Synopse Nr. 325"] },
      { number: 6, text: "sondern weil ich dies zu euch geredet habe, hat Traurigkeit euer Herz erfüllt*.", footnotes: ["℘ V. 22; Mt 17,23"] },
      { number: 7, text: "Doch ich sage euch die Wahrheit: Es ist euch nützlich, dass ich weggehe, denn wenn ich nicht weggehe, wird der Beistand* nicht zu euch kommen; wenn ich aber hingehe, werde ich ihn zu euch senden*.", footnotes: ["o. Fürsprecher; o. Helfer; w. der zur Unterstützung Herbeigerufene", "℘ Kap. 7,39"] },
      { number: 8, text: "Und wenn er gekommen ist, wird er die Welt überführen von Sünde und von Gerechtigkeit und von Gericht." },
      { number: 9, text: "Von Sünde, weil sie nicht an mich glauben*;", footnotes: ["℘ Kap. 8,24"] },
      { number: 10, text: "von Gerechtigkeit aber, weil ich zum Vater gehe* und ihr mich nicht mehr seht;", footnotes: ["℘ 1Tim 3,16"] },
      { number: 11, text: "von Gericht aber, weil der Fürst dieser Welt gerichtet ist*.", footnotes: ["℘ Kap. 12,31"] },
      { number: 12, text: "Noch vieles habe ich euch zu sagen, aber ihr könnt es jetzt nicht tragen." },
      { number: 13, text: "Wenn aber jener, der Geist der Wahrheit*, gekommen ist, wird er euch in die ganze Wahrheit leiten*; denn er wird nicht aus sich selbst reden, sondern was er hören wird, wird er reden, und das Kommende wird er euch verkündigen*.", footnotes: ["℘ Kap. 14,17; Ps 25,5; 1Jo 2,27", "℘ Kap. 14,26; 1Kor 2,10-13", "℘ Apg 21,11; 1Tim 4,1-3; Offb 22,6"] },
      { number: 14, text: "Er wird mich verherrlichen, denn von dem Meinen wird er nehmen und euch verkündigen*.", footnotes: ["℘ 1Kor 2,12"] },
      { number: 15, text: "Alles, was der Vater hat, ist mein*; darum sagte ich, dass er von dem Meinen nimmt und euch verkündigen wird.", footnotes: ["℘ Kap. 3,35"] },
      { number: 16, text: "Eine kleine Weile, und ihr seht mich nicht mehr, und wieder eine kleine Weile, und ihr werdet mich sehen*.", heading: "Trost und Freude im Blick auf Jesu Abscheiden und Wiederkehr", footnotes: ["℘ Kap. 14,19; Mt 28,7; Apg 1,3 ⇨Esyn: Synopse Nr. 326"] },
      { number: 17, text: "Es sprachen nun einige von seinen Jüngern zueinander: Was ist das, was er zu uns sagt: Eine kleine Weile, und ihr seht mich nicht, und wieder eine kleine Weile, und ihr werdet mich sehen, und: Ich gehe hin zum Vater?" },
      { number: 18, text: "Sie sprachen nun: Was ist das für eine »kleine Weile«, wovon er redet? Wir wissen nicht, was er sagt." },
      { number: 19, text: "Jesus erkannte, dass sie ihn fragen wollten, und sprach zu ihnen: Forscht ihr darüber miteinander, dass ich sagte: Eine kleine Weile, und ihr seht mich nicht, und wieder eine kleine Weile, und ihr werdet mich sehen?" },
      { number: 20, text: "Wahrlich, wahrlich, ich sage euch, dass ihr weinen und wehklagen werdet, aber die Welt wird sich freuen; ihr werdet traurig sein, aber eure Traurigkeit wird zur Freude werden*.", footnotes: ["℘ Jes 61,3; Mt 5,4; Mk 2,20"] },
      { number: 21, text: "Die Frau hat Traurigkeit, wenn sie gebiert, weil ihre Stunde gekommen ist*; wenn sie aber das Kind geboren hat, gedenkt sie nicht mehr der Bedrängnis um der Freude willen, dass ein Mensch in die Welt geboren ist.", footnotes: ["℘ Jes 26,17"] },
      { number: 22, text: "Auch ihr nun habt jetzt zwar Traurigkeit*; aber ich werde euch wiedersehen, und euer Herz wird sich freuen*, und eure Freude nimmt niemand von euch.", footnotes: ["℘ V. 6", "℘ Kap. 20,20; Lk 24,41.52"] },
      { number: 23, text: "Und an jenem Tag werdet ihr mich nichts fragen. Wahrlich, wahrlich, ich sage euch: Was ihr den Vater bitten werdet in meinem Namen, wird er euch geben. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 327"] },
      { number: 24, text: "Bis jetzt habt ihr nichts gebeten in meinem Namen. Bittet, und ihr werdet empfangen*, damit eure Freude völlig sei*!", footnotes: ["℘ Kap. 14,13.14", "℘ Kap. 15,11"] },
      { number: 25, text: "Dies habe ich in Bildreden zu euch geredet*; es kommt die Stunde, da ich nicht mehr in Bildreden zu euch sprechen, sondern euch offen von dem Vater verkündigen werde.", footnotes: ["℘ Kap. 10,6"] },
      { number: 26, text: "An jenem Tag werdet ihr bitten in meinem Namen, und ich sage euch nicht, dass ich den Vater für euch bitten werde;" },
      { number: 27, text: "denn der Vater selbst hat euch lieb*, weil ihr mich geliebt und geglaubt habt, dass ich von Gott ausgegangen bin*.", footnotes: ["℘ Kap. 14,21; 1Jo 3,1", "℘ Kap. 17,8.25"] },
      { number: 28, text: "Ich bin von dem Vater ausgegangen und in die Welt gekommen; wieder verlasse ich die Welt und gehe zum Vater*.", footnotes: ["℘ V. 5; Kap. 8,14"] },
      { number: 29, text: "Seine Jünger sprechen zu ihm: Siehe, jetzt redest du offen und gebrauchst keine Bildrede; *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 328"] },
      { number: 30, text: "jetzt wissen wir, dass du alles weißt* und nicht nötig hast, dass dich jemand fragt; hierdurch glauben wir, dass du von Gott ausgegangen bist.", footnotes: ["℘ Kap. 2,25"] },
      { number: 31, text: "Jesus antwortete ihnen: Glaubt ihr jetzt?" },
      { number: 32, text: "Siehe, es kommt die Stunde und ist gekommen, dass ihr euch zerstreuen werdet, ein jeder in seine Heimat* und mich allein lassen werdet*; doch ich bin nicht allein, denn der Vater ist bei mir*.", footnotes: ["w. dass ihr zerstreut werdet, jeder in das Seinige", "℘ Ps 69,21; Mt 26,31", "℘ Kap. 8,16.29 ⇨Esyn: Synopse Nr. 367"] },
      { number: 33, text: "Dies habe ich zu euch geredet, damit ihr in mir Frieden habt*. In der Welt habt ihr Bedrängnis*; aber seid guten Mutes, ich habe die Welt überwunden*.", footnotes: ["℘ Kap. 14,27; Phil 4,7", "℘ V. 2; 1Thes 3,3.4", "℘ 1Jo 5,4; Offb 3,21"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Dies redete Jesus und hob seine Augen auf zum Himmel und sprach: Vater, die Stunde ist gekommen*. Verherrliche deinen Sohn*, damit der Sohn dich verherrliche*,", heading: "Das Gebet Jesu für seine Jünger", footnotes: ["℘ Kap. 7,30; Mk 14,41", "℘ Hebr 5,5", "℘ Kap. 12,23 ⇨Esyn: Synopse Nr. 329"] },
      { number: 2, text: "wie du ihm Vollmacht gegeben hast über alles Fleisch*, dass er allen, die du ihm gegeben hast, ewiges Leben gebe*!", footnotes: ["℘ Mt 11,27", "℘ Kap. 6,40; 10,28"] },
      { number: 3, text: "Dies aber ist das ewige Leben, dass sie dich, den allein wahren Gott*, und den du gesandt hast, Jesus Christus, erkennen*.", footnotes: ["℘ 1Kor 8,6", "℘ 2Petr 1,2.3; 1Jo 5,20"] },
      { number: 4, text: "Ich habe dich verherrlicht auf der Erde; das Werk habe ich vollbracht, das du mir gegeben hast, dass ich es tun sollte*.", footnotes: ["℘ Kap. 4,34; Hebr 3,2"] },
      { number: 5, text: "Und nun verherrliche du, Vater, mich bei dir selbst mit der Herrlichkeit, die ich bei dir hatte, ehe die Welt war*!", footnotes: ["℘ Kap. 13,32; Kol 1,17"] },
      { number: 6, text: "Ich habe deinen Namen den Menschen offenbart, die du mir aus der Welt gegeben hast. Dein waren sie, und mir hast du sie gegeben*, und sie haben dein Wort bewahrt*.", footnotes: ["℘ Kap. 6,37; Hebr 2,13", "o. gehalten\n℘ Offb 3,8"] },
      { number: 7, text: "Jetzt haben sie erkannt, dass alles, was du mir gegeben hast, von dir ist;" },
      { number: 8, text: "denn die Worte, die du mir gegeben hast*, habe ich ihnen gegeben, und sie haben sie angenommen und wahrhaftig erkannt, dass ich von dir ausgegangen bin, und haben geglaubt, dass du mich gesandt hast*.", footnotes: ["℘ Kap. 3,34", "℘ Kap. 4,42; 16,27.30"] },
      { number: 9, text: "Ich bitte für sie*; nicht für die Welt bitte ich, sondern für die, welche du mir gegeben hast, denn sie sind dein", footnotes: ["℘ Röm 8,34; Hebr 7,25"] },
      { number: 10, text: "— und alles, was mein ist, ist dein, und was dein ist, mein* —, und ich bin in ihnen verherrlicht.", footnotes: ["℘ Kap. 3,35"] },
      { number: 11, text: "Und ich bin nicht mehr in der Welt, und diese sind in der Welt, und ich komme zu dir. Heiliger Vater! Bewahre sie in deinem Namen, den du mir gegeben hast*, dass sie eins seien wie wir*!", footnotes: ["℘ Jud 1", "℘ V. 21.22; Kap. 10,30"] },
      { number: 12, text: "Als ich bei ihnen war, bewahrte ich sie in deinem Namen, den du mir gegeben hast; und ich habe sie behütet*, und keiner von ihnen ist verloren*, als nur der Sohn des Verderbens*, damit die Schrift erfüllt werde*.", footnotes: ["o. mit anderer Lesart: Namen, die du mir gegeben hast, habe ich behütet", "℘ Kap. 6,39", "℘ Mk 14,21; 2Thes 2,3", "℘ Kap. 13,18"] },
      { number: 13, text: "Jetzt aber komme ich zu dir; und dieses rede ich in der Welt, damit sie meine Freude völlig in sich haben*.", footnotes: ["℘ Kap. 15,11"] },
      { number: 14, text: "Ich habe ihnen dein Wort gegeben, und die Welt hat sie gehasst, weil sie nicht von der Welt sind, wie ich nicht von der Welt bin*.", footnotes: ["℘ Kap. 15,18.19"] },
      { number: 15, text: "Ich bitte nicht, dass du sie aus der Welt wegnimmst*, sondern dass du sie bewahrst vor dem Bösen*.", footnotes: ["℘ 1Kor 5,10", "℘ Ps 12,8; Mt 6,13"] },
      { number: 16, text: "Sie sind nicht von der Welt, wie ich nicht von der Welt bin*.", footnotes: ["℘ Kap. 8,23"] },
      { number: 17, text: "Heilige sie durch die Wahrheit! Dein Wort ist Wahrheit*.", footnotes: ["℘ 2Sam 7,28; Ps 119,160; Eph 1,13"] },
      { number: 18, text: "Wie du mich in die Welt gesandt hast*, habe auch ich sie in die Welt gesandt*;", footnotes: ["℘ Hebr 3,1", "℘ Kap. 20,21"] },
      { number: 19, text: "und ich heilige mich selbst für sie*, damit auch sie Geheiligte seien* durch Wahrheit.", footnotes: ["℘ Hebr 10,10", "℘ 1Kor 1,30; Hebr 2,11"] },
      { number: 20, text: "Aber nicht für diese allein bitte ich, sondern auch für die, welche durch ihr Wort an mich glauben*,", footnotes: ["℘ Röm 10,17"] },
      { number: 21, text: "damit sie alle eins seien*, wie du, Vater, in mir und ich in dir*, dass auch sie in uns eins seien, damit die Welt glaube, dass du mich gesandt hast.", footnotes: ["℘ V. 11", "℘ Kap. 10,38"] },
      { number: 22, text: "Und die Herrlichkeit, die du mir gegeben hast, habe ich ihnen gegeben*, dass sie eins seien, wie wir eins sind*", footnotes: ["℘ 2Thes 2,14", "℘ V. 11; Apg 4,32"] },
      { number: 23, text: "— ich in ihnen* und du in mir* —, dass sie in eins vollendet seien, damit die Welt erkenne, dass du mich gesandt und sie geliebt hast*, wie du mich geliebt hast*.", footnotes: ["℘ Kol 1,27", "℘ Kap. 14,20", "℘ 1Jo 3,1", "℘ Kap. 3,35"] },
      { number: 24, text: "Vater, ich will, dass die, welche du mir gegeben hast, auch bei mir seien, wo ich bin*, damit sie meine Herrlichkeit schauen*, die du mir gegeben hast, denn du hast mich geliebt vor Grundlegung der Welt.", footnotes: ["w. Vater, die (nach anderer Lesart: was) du mir gegeben hast — ich will, dass, wo ich bin, auch jene seien\n℘ Kap. 12,26", "℘ 1Jo 3,2"] },
      { number: 25, text: "Gerechter Vater! Und die Welt hat dich nicht erkannt*; ich aber habe dich erkannt*, und diese haben erkannt, dass du mich gesandt hast*.", footnotes: ["℘ Kap. 7,28; 8,19; 1Kor 1,21; 1Jo 3,1", "℘ Kap. 7,29", "℘ V. 8"] },
      { number: 26, text: "Und ich habe ihnen deinen Namen kundgetan und werde ihn kundtun, damit die Liebe, womit du mich geliebt hast*, in ihnen sei* und ich in ihnen*.", footnotes: ["℘ V. 23", "℘ Röm 5,5", "℘ Kap. 6,56; 15,9; Röm 8,10; 2Kor 13,5; Gal 2,20; Eph 3,17"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "*Als Jesus dies gesagt hatte, ging er mit seinen Jüngern hinaus über den Bach Kidron*, wo ein Garten war, in den er hineinging, er und seine Jünger*.", heading: "Gefangennahme", footnotes: ["℘ Mt 26,47-56; Mk 14,43-50; Lk 22,47-53", "℘ 2Sam 15,23", "℘ Mt 26,30.36 ⇨Esyn: Synopse Nr. 330"] },
      { number: 2, text: "Aber auch Judas, der ihn überlieferte*, wusste den Ort, weil Jesus dort oft mit seinen Jüngern zusammen war*.", footnotes: ["℘ Kap. 6,71; Mk 3,19", "℘ Kap. 8,1 ⇨Esyn: Synopse Nr. 331"] },
      { number: 3, text: "Als nun Judas die Schar* und von den Hohenpriestern und Pharisäern Diener genommen hatte, kommt er dahin mit Leuchten und Fackeln und Waffen*.", footnotes: ["Gemeint ist »Kohorte«, eine militärische Einheit der Römer von etwa 600 Mann unter dem Befehl eines Obersten (s. Anm. zu V. 12).", "℘ Mt 26,46"] },
      { number: 4, text: "Jesus nun, der alles wusste*, was über ihn kommen würde, ging hinaus und sprach zu ihnen: Wen sucht ihr?", footnotes: ["℘ Kap. 13,1"] },
      { number: 5, text: "Sie antworteten ihm: Jesus, den Nazoräer*. Er spricht zu ihnen: Ich bin es*! Aber auch Judas, der ihn überlieferte, stand bei ihnen*.", footnotes: ["eine andere Form für das bei Mk (und teilweise Lk) überlieferte »Nazarener«; vgl. auch Anm. zu Mt 2,23\n℘ Kap. 19,19; Mt 2,23", "℘ Kap. 6,20", "℘ Apg 1,16"] },
      { number: 6, text: "Als er nun zu ihnen sagte: Ich bin es!, wichen sie zurück und fielen zu Boden*.", footnotes: ["℘ Ps 27,2"] },
      { number: 7, text: "Da fragte er sie wieder: Wen sucht ihr? Sie aber sprachen: Jesus, den Nazoräer*.", footnotes: ["eine andere Form für das bei Mk (und teilweise Lk) überlieferte »Nazarener«; vgl. auch Anm. zu Mt 2,23"] },
      { number: 8, text: "Jesus antwortete: Ich habe euch gesagt, dass ich es bin. Wenn ihr nun mich sucht, so lasst diese gehen!" },
      { number: 9, text: "Damit das Wort erfüllt würde, das er sprach: Von denen, die du mir gegeben hast, habe ich keinen verloren*.", footnotes: ["℘ Kap. 6,39"] },
      { number: 10, text: "Simon Petrus nun, der ein Schwert hatte, zog es und schlug den Knecht* des Hohenpriesters und hieb ihm das rechte Ohr ab*. Der Name des Knechtes aber war Malchus.", footnotes: ["w. Sklaven", "℘ V. 26"] },
      { number: 11, text: "Da sprach Jesus zu Petrus: Stecke das Schwert in die Scheide! Den Kelch, den mir der Vater gegeben hat, soll ich den nicht trinken*?", footnotes: ["℘ Mt 26,39.42"] },
      { number: 12, text: "*Die Schar nun und der Oberst* und die Diener der Juden nahmen Jesus und banden ihn;", heading: "Verhör durch Hannas — Verleugnung durch Petrus", footnotes: ["℘ Mt 26,57-75; Mk 14,53-72; Lk 22,54-71", "griech. Chiliarch; d. h. Tausendschaftsführer; hier Anführer einer Kohorte"] },
      { number: 13, text: "und sie führten ihn zuerst hin zu Hannas, denn er war Schwiegervater des Kaiphas, der jenes Jahr Hoherpriester war*.", footnotes: ["℘ Kap. 11,49; Apg 4,6 ⇨Esyn: Synopse Nr. 332"] },
      { number: 14, text: "Kaiphas aber war es, der den Juden geraten hatte, es sei nützlich, dass ein Mensch für das Volk sterbe*.", footnotes: ["℘ Kap. 11,50"] },
      { number: 15, text: "Simon Petrus aber folgte Jesus und ein anderer Jünger*. Dieser Jünger aber war dem Hohenpriester bekannt und ging mit Jesus hinein in den Hof des Hohenpriesters.", footnotes: ["℘ Kap. 20,2.3.8"] },
      { number: 16, text: "Petrus aber stand an der Tür draußen. Da ging der andere Jünger, der dem Hohenpriester bekannt war, hinaus und sprach mit der Türhüterin und führte Petrus hinein." },
      { number: 17, text: "Da spricht die Magd, die Türhüterin, zu Petrus: Bist nicht auch du einer von den Jüngern dieses Menschen? Er sagt: Ich bin es nicht." },
      { number: 18, text: "Es standen aber die Knechte* und die Diener da, die ein Kohlenfeuer gemacht hatten, weil es kalt war, und wärmten sich; Petrus aber stand auch bei ihnen und wärmte sich.", footnotes: ["w. Sklaven"] },
      { number: 19, text: "Der Hohepriester nun fragte Jesus über seine Jünger und über seine Lehre." },
      { number: 20, text: "Jesus antwortete ihm: Ich habe öffentlich zu der Welt geredet; ich habe allezeit in der Synagoge und in dem Tempel gelehrt, wo alle Juden zusammenkommen, und im Verborgenen habe ich nichts geredet*.", footnotes: ["℘ Kap. 7,14.26"] },
      { number: 21, text: "Was fragst du mich? Frage die, welche gehört haben, was ich zu ihnen geredet habe; siehe, diese wissen, was ich gesagt habe." },
      { number: 22, text: "Als er aber dies sagte, gab einer der Diener, der dabeistand, Jesus einen Schlag ins Gesicht* und sagte: Antwortest du so dem Hohenpriester*?", footnotes: ["℘ Kap. 19,3", "℘ Apg 23,2.4"] },
      { number: 23, text: "Jesus antwortete ihm: Wenn ich schlecht geredet habe, so gib Zeugnis von dem Schlechten! Wenn aber recht, was schlägst du mich*?", footnotes: ["℘ 1Petr 2,23"] },
      { number: 24, text: "Hannas nun sandte ihn gebunden zu Kaiphas, dem Hohenpriester." },
      { number: 25, text: "Simon Petrus aber stand da und wärmte sich. Da sprachen sie zu ihm: Bist nicht auch du einer von seinen Jüngern? Er leugnete und sprach: Ich bin es nicht. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 333"] },
      { number: 26, text: "Es spricht einer von den Knechten* des Hohenpriesters, der ein Verwandter dessen war, dem Petrus das Ohr abgehauen hatte: Sah ich dich nicht in dem Garten bei ihm*?", footnotes: ["w. Sklaven", "℘ V. 10"] },
      { number: 27, text: "Da leugnete Petrus wieder; und gleich darauf krähte der Hahn*.", footnotes: ["℘ Kap. 13,38"] },
      { number: 28, text: "*Sie führen nun Jesus von Kaiphas in das Prätorium*; es war aber frühmorgens. Und sie gingen nicht hinein in das Prätorium, damit sie sich nicht verunreinigten, sondern das Passahmahl essen könnten*.", heading: "Verhör durch Pilatus", footnotes: ["℘ Mt 27,2.11-26; Mk 15,1-15; Lk 23,1-5.13-25", "So hieß der Palast eines Statthalters in den röm. Provinzen.", "℘ 2Chr 30,18 ⇨Esyn: Synopse Nr. 334"] },
      { number: 29, text: "Pilatus* ging nun zu ihnen hinaus und sprach: Welche Anklage bringt ihr gegen diesen Menschen vor? *", footnotes: ["kaiserlicher Statthalter von ca. 26—36 n. Chr. in Judäa und Samaria", "℘ ⇨Esyn: Synopse Nr. 336"] },
      { number: 30, text: "Sie antworteten und sprachen zu ihm: Wenn dieser nicht ein Übeltäter wäre, würden wir ihn dir nicht überliefert haben." },
      { number: 31, text: "Da sprach Pilatus zu ihnen: Nehmt ihr ihn und richtet ihn nach eurem Gesetz*. Da sprachen die Juden zu ihm: Es ist uns nicht erlaubt, jemanden zu töten;", footnotes: ["℘ Kap. 19,6.7; Apg 18,15"] },
      { number: 32, text: "damit das Wort Jesu erfüllt würde, das er sprach, um anzudeuten, welches Todes er sterben sollte*.", footnotes: ["℘ Kap. 12,33"] },
      { number: 33, text: "Pilatus ging nun wieder hinein in das Prätorium und rief Jesus und sprach zu ihm: Bist du der König der Juden*?", footnotes: ["℘ Kap. 19,19"] },
      { number: 34, text: "Jesus antwortete: Sagst du dies von dir selbst aus, oder haben dir andere von mir gesagt?" },
      { number: 35, text: "Pilatus antwortete: Bin ich etwa ein Jude? Deine Nation und die Hohenpriester haben dich mir überliefert*. Was hast du getan?", footnotes: ["℘ Kap. 19,11; Apg 4,26.27"] },
      { number: 36, text: "Jesus antwortete: Mein Reich* ist nicht von dieser Welt*; wenn mein Reich* von dieser Welt wäre, so hätten meine Diener gekämpft, damit ich den Juden nicht überliefert würde, jetzt aber ist mein Reich* nicht von hier.", footnotes: ["o. meine Königsherrschaft", "℘ Kap. 6,15; Lk 17,20", "o. meine Königsherrschaft", "o. meine Königsherrschaft"] },
      { number: 37, text: "Da sprach Pilatus zu ihm: Also bist du doch ein König? Jesus antwortete: Du sagst es, dass ich ein König bin*. Ich bin dazu geboren und dazu in die Welt gekommen, dass ich für die Wahrheit Zeugnis gebe*. Jeder, der aus der Wahrheit ist, hört meine Stimme*.", footnotes: ["℘ Kap. 12,13", "℘ 1Tim 6,13; Offb 1,5", "℘ Kap. 8,47"] },
      { number: 38, text: "Pilatus spricht zu ihm: Was ist Wahrheit? Und als er dies gesagt hatte, ging er wieder zu den Juden hinaus und spricht zu ihnen: Ich finde keinerlei Schuld an ihm*.", footnotes: ["℘ Kap. 7,18"] },
      { number: 39, text: "Es ist aber ein Brauch bei euch, dass ich euch an dem Passah einen losgebe. Wollt ihr nun, dass ich euch den König der Juden losgebe? *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 339"] },
      { number: 40, text: "Da schrien wieder alle und sagten: Nicht diesen, sondern den Barabbas! Barabbas aber war ein Räuber*.", footnotes: ["℘ Apg 3,13.14"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "*Dann nahm nun Pilatus Jesus und ließ ihn geißeln*.", heading: "Geißelung und Verurteilung", footnotes: ["℘ V. 1-5: Mt 27,26-31; Mk 15,15-20", "℘ Jes 50,6; 53,5; Mt 20,19 ⇨Esyn: Synopse Nr. 340"] },
      { number: 2, text: "Und die Soldaten flochten eine Krone aus Dornen und setzten sie auf sein Haupt und warfen ihm ein Purpurgewand um;" },
      { number: 3, text: "und sie kamen zu ihm und sagten: Sei gegrüßt, König der Juden! Und sie gaben ihm Schläge ins Gesicht*.", footnotes: ["℘ Kap. 18,22; Mt 26,67"] },
      { number: 4, text: "Und Pilatus ging wieder hinaus und spricht zu ihnen: Siehe, ich führe ihn zu euch heraus, damit ihr wisst, dass ich keinerlei Schuld an ihm finde*.", footnotes: ["℘ Kap. 7,18; Lk 23,4"] },
      { number: 5, text: "Jesus nun ging hinaus und trug die Dornenkrone und das Purpurgewand. Und er spricht zu ihnen: Siehe, der Mensch!" },
      { number: 6, text: "Als ihn nun die Hohenpriester* und die Diener sahen, schrien sie* und sagten: Kreuzige, kreuzige ihn*! Pilatus spricht zu ihnen: Nehmt ihr ihn hin und kreuzigt ihn! Denn ich finde keine Schuld an ihm*.", footnotes: ["s. Anm. zu Kap. 11,47", "℘ Ps 22,14", "℘ V. 15; Mk 15,14", "℘ Kap. 7,18; Lk 23,4"] },
      { number: 7, text: "Die Juden antworteten ihm: Wir haben ein Gesetz, und nach dem Gesetz muss er sterben*, weil er sich selbst zu Gottes Sohn gemacht hat*.", footnotes: ["℘ Kap. 18,31", "℘ Kap. 5,18; 3Mo 24,16; Mt 26,66"] },
      { number: 8, text: "Als nun Pilatus dieses Wort hörte, fürchtete er sich noch mehr; *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 336"] },
      { number: 9, text: "und er ging wieder hinein in das Prätorium und spricht zu Jesus: Woher bist du? Jesus aber gab ihm keine Antwort*.", footnotes: ["℘ Mt 26,63; Mk 15,5"] },
      { number: 10, text: "Da spricht Pilatus zu ihm: Redest du nicht mit mir? Weißt du nicht, dass ich Macht* habe, dich loszugeben, und Macht habe, dich zu kreuzigen?", footnotes: ["o. Vollmacht"] },
      { number: 11, text: "Jesus antwortete: Du hättest keinerlei Macht* über mich, wenn sie dir nicht von oben gegeben wäre; darum hat der, welcher mich dir überliefert hat*, größere Sünde.", footnotes: ["o. Vollmacht", "℘ Kap. 18,35"] },
      { number: 12, text: "Daraufhin suchte Pilatus ihn loszugeben. Die Juden aber schrien und sagten: Wenn du diesen losgibst, bist du des Kaisers Freund* nicht; jeder, der sich selbst zum König macht, widersetzt sich dem Kaiser*.", footnotes: ["Der Ausdruck »Freund des Kaisers« bezeichnet eine besondere Stellung beim Kaiser.", "℘ Lk 23,2"] },
      { number: 13, text: "Als nun Pilatus diese Worte hörte, führte er Jesus hinaus und setzte sich auf den Richterstuhl an einen Ort, genannt Steinpflaster*, auf Hebräisch aber Gabbata*.", footnotes: ["erhöhter gepflasterter Platz vor dem Prätorium, wo der Statthalter Gericht hielt", "℘ Mt 27,19"] },
      { number: 14, text: "Es war aber Rüsttag* des Passah*; es war um die sechste Stunde*. Und er spricht zu den Juden: Siehe, euer König!", footnotes: ["der Wochentag vor einem Sabbat oder Fest, in der Regel ein Freitag", "℘ V. 31", "d. i. zwischen 11 und 12 Uhr vormittags; vgl. auch Anm. zu Mt 27,45"] },
      { number: 15, text: "Sie aber schrien: Weg, weg! Kreuzige ihn*! Pilatus spricht zu ihnen: Euren König soll ich kreuzigen? Die Hohenpriester antworteten: Wir haben keinen König außer dem Kaiser*.", footnotes: ["℘ V. 6; Lk 23,23; Apg 13,28", "℘ Apg 3,13"] },
      { number: 16, text: "Dann nun lieferte er ihn an sie aus, dass er gekreuzigt würde. Sie aber nahmen Jesus hin *und führten ihn fort*. *", footnotes: ["Diese Wörter sind in mehreren alten Handschr. nicht enthalten.", "Diese Wörter sind in mehreren alten Handschr. nicht enthalten.", "℘ ⇨Esyn: Synopse Nr. 343"] },
      { number: 17, text: "*Und er selbst trug sein Kreuz und ging hinaus nach der Stätte, genannt Schädelstätte, die auf Hebräisch Golgatha heißt, *", heading: "Golgatha: Kreuzigung", footnotes: ["℘ Mt 27,32-44; Mk 15,21-32; Lk 23,26-43", "℘ ⇨Esyn: Synopse Nr. 344"] },
      { number: 18, text: "wo sie ihn kreuzigten*, und zwei andere mit ihm, auf dieser und auf jener Seite, Jesus aber in der Mitte.", footnotes: ["℘ Ps 22,17; Mt 20,19; Lk 20,15; Offb 11,8 ⇨Esyn: Synopse Nr. 345"] },
      { number: 19, text: "Pilatus schrieb aber auch eine Aufschrift und setzte sie auf das Kreuz. Es war aber geschrieben: Jesus, der Nazoräer*, der König der Juden*.", footnotes: ["eine andere Form für das bei Mk (und teilweise Lk) überlieferte »Nazarener«; vgl. auch Anm. zu Mt 2,23", "℘ Kap. 18,5.33-37; Mt 2,2"] },
      { number: 20, text: "Diese Aufschrift nun lasen viele von den Juden, denn die Stätte, wo Jesus gekreuzigt wurde, war nahe bei der Stadt; und es war geschrieben auf Hebräisch, Lateinisch und Griechisch." },
      { number: 21, text: "Die Hohenpriester der Juden sagten nun zu Pilatus: Schreibe nicht: Der König der Juden, sondern dass jener gesagt hat: Ich bin König der Juden*.", footnotes: ["℘ Mk 15,2.12"] },
      { number: 22, text: "Pilatus antwortete: Was ich geschrieben habe, habe ich geschrieben." },
      { number: 23, text: "Die Soldaten nun nahmen, als sie Jesus gekreuzigt hatten, seine Kleider — und machten vier Teile, einem jeden Soldaten einen Teil — und das Untergewand. Das Untergewand aber war ohne Naht, von obenan durchgewebt." },
      { number: 24, text: "Da sprachen sie zueinander: Lasst es uns nicht zerreißen, sondern darum losen, wessen es sein soll! Damit die Schrift erfüllt würde, die spricht: »Sie haben meine Kleider unter sich verteilt, und über mein Gewand haben sie das Los geworfen.«* Die Soldaten nun haben dies getan.", footnotes: ["℘ Ps 22,19"] },
      { number: 25, text: "Es standen aber bei dem Kreuz Jesu seine Mutter und die Schwester seiner Mutter, Maria, des Klopas Frau, und Maria Magdalena*.", footnotes: ["d. h. die aus Magdala (Ort am See Genezareth)\n℘ Mt 27,56"] },
      { number: 26, text: "Als nun Jesus die Mutter sah und den Jünger, den er liebte*, dabeistehen, spricht er zu seiner Mutter: Frau, siehe, dein Sohn!", footnotes: ["℘ Kap. 13,23"] },
      { number: 27, text: "Dann spricht er zu dem Jünger: Siehe, deine Mutter! Und von jener Stunde an nahm der Jünger sie zu sich." },
      { number: 28, text: "*Danach, da Jesus wusste*, dass alles schon vollbracht war, spricht er, damit die Schrift erfüllt würde*: Mich dürstet*!", heading: "Golgatha: Tod", footnotes: ["℘ V. 28-30: Mt 27,45-50; Mk 15,33-37; Lk 23,44-46", "℘ Kap. 13,1", "℘ Kap. 13,38; 1Kor 15,3", "℘ Ps 22,16 ⇨Esyn: Synopse Nr. 347"] },
      { number: 29, text: "Es stand da ein Gefäß voll Essig. Sie legten nun einen Schwamm voller Essig um einen Ysop* und brachten ihn an seinen Mund*.", footnotes: ["ein kleiner Busch mit stark riechenden Blättern; er wurde beim Reinigungsopfer zum Besprengen verwendet", "℘ Lk 23,36"] },
      { number: 30, text: "Als nun Jesus den Essig genommen hatte, sprach er: Es ist vollbracht*! Und er neigte das Haupt und übergab den Geist*.", footnotes: ["℘ Lk 12,50", "℘ Kap. 10,18"] },
      { number: 31, text: "Die Juden nun baten den Pilatus, damit die Leiber nicht am Sabbat am Kreuz blieben*, weil es Rüsttag war* — denn der Tag jenes Sabbats war groß —, dass ihre Beine gebrochen und sie abgenommen werden möchten.", footnotes: ["℘ 5Mo 21,23", "℘ V. 14; Mt 27,62 ⇨Esyn: Synopse Nr. 349"] },
      { number: 32, text: "Da kamen die Soldaten und brachen die Beine des ersten und des anderen, der mit ihm gekreuzigt war." },
      { number: 33, text: "Als sie aber zu Jesus kamen und sahen, dass er schon gestorben war*, brachen sie ihm die Beine nicht,", footnotes: ["℘ Mk 15,44"] },
      { number: 34, text: "sondern einer der Soldaten durchbohrte mit einem Speer seine Seite*, und sogleich kam Blut und Wasser heraus*.", footnotes: ["℘ Kap. 20,20", "℘ 1Jo 5,6"] },
      { number: 35, text: "Und der es gesehen hat, hat es bezeugt*, und sein Zeugnis ist wahr; und er weiß, dass er sagt, was wahr ist*, damit auch ihr glaubt*.", footnotes: ["℘ 1Jo 1,3", "℘ Kap. 15,27", "℘ Kap. 20,31"] },
      { number: 36, text: "Denn dies geschah, damit die Schrift erfüllt würde: »Kein Bein von ihm wird zerbrochen werden.«*", footnotes: ["℘ 2Mo 12,46; 4Mo 9,12; Ps 34,21"] },
      { number: 37, text: "Und wieder sagt eine andere Schrift: »Sie werden den anschauen, den sie durchstochen haben.«*", footnotes: ["℘ Sach 12,10; Offb 1,7"] },
      { number: 38, text: "*Danach aber bat Josef von Arimathäa, der ein Jünger Jesu war, aber ein geheimer aus Furcht vor den Juden*, den Pilatus, dass er den Leib Jesu abnehmen dürfe. Und Pilatus erlaubte es. Er kam nun und nahm den Leib Jesu ab.", heading: "Grablegung", footnotes: ["℘ Mt 27,57-61; Mk 15,42-47; Lk 23,50-56", "℘ Kap. 7,13 ⇨Esyn: Synopse Nr. 350"] },
      { number: 39, text: "Es kam aber auch Nikodemus, der zuerst bei Nacht zu Jesus gekommen war*, und brachte eine Mischung von Myrrhe und Aloe*, ungefähr hundert Pfund*.", footnotes: ["℘ Kap. 3,1.2", "wohlriechende Harze, die zum Einbalsamieren von Toten verwendet wurden", "w. Litra; s. Tabelle »Gewichte«"] },
      { number: 40, text: "Sie nahmen nun den Leib Jesu und wickelten ihn in Leinentücher mit den wohlriechenden Ölen, wie es bei den Juden zu bestatten Sitte ist." },
      { number: 41, text: "Es war aber an dem Ort, wo er gekreuzigt wurde, ein Garten und in dem Garten eine neue Gruft, in die noch nie jemand gelegt worden war." },
      { number: 42, text: "Dorthin nun legten sie Jesus, wegen des Rüsttags der Juden, weil die Gruft nahe war." },
    ]},
    { number: 20, verses: [
      { number: 1, text: "*An dem ersten Wochentag* aber kommt Maria Magdalena* früh, als es noch finster war, zur Gruft und sieht den Stein von der Gruft weggenommen.", heading: "Das leere Grab des Auferstandenen", footnotes: ["℘ Mt 28,1-10; Mk 16,1-11; Lk 24,1-12", "℘ V. 19 ⇨Esyn: Synopse Nr. 352", "d. h. die aus Magdala (Ort am See Genezareth)"] },
      { number: 2, text: "Sie läuft nun und kommt zu Simon Petrus und zu dem anderen Jünger*, den Jesus lieb hatte*, und spricht zu ihnen: Sie haben den Herrn aus der Gruft weggenommen, und wir wissen nicht, wo sie ihn hingelegt haben.", footnotes: ["℘ Kap. 18,15", "℘ Kap. 13,23"] },
      { number: 3, text: "Da ging Petrus hinaus und der andere Jünger*, und sie gingen zu der Gruft.", footnotes: ["℘ Kap. 18,15"] },
      { number: 4, text: "Die beiden aber liefen zusammen, und der andere Jünger lief voraus, schneller als Petrus, und kam zuerst zu der Gruft;" },
      { number: 5, text: "und als er sich vornüberbeugt, sieht er die Leinentücher daliegen; doch ging er nicht hinein." },
      { number: 6, text: "Da kommt Simon Petrus, der ihm folgte, und ging hinein in die Gruft und sieht die Leinentücher daliegen" },
      { number: 7, text: "und das Schweißtuch, das auf seinem Haupt war, nicht zwischen den Leinentüchern liegen, sondern für sich zusammengewickelt an einem besonderen Ort*.", footnotes: ["℘ Lk 24,24"] },
      { number: 8, text: "Da ging nun auch der andere Jünger* hinein, der zuerst zu der Gruft kam, und er sah und glaubte.", footnotes: ["℘ Kap. 18,15"] },
      { number: 9, text: "Denn sie verstanden die Schrift noch nicht, dass er aus den Toten auferstehen musste*.", footnotes: ["℘ Ps 16,10; Apg 2,31"] },
      { number: 10, text: "Da gingen nun die Jünger wieder heim." },
      { number: 11, text: "Maria aber stand draußen bei der Gruft und weinte. Als sie nun weinte, beugte sie sich vornüber in die Gruft", heading: "Erscheinung des Auferstandenen vor Maria Magdalena" },
      { number: 12, text: "und sieht zwei Engel in weißen Kleidern dasitzen, einen bei dem Haupt und einen bei den Füßen, wo der Leib Jesu gelegen hatte." },
      { number: 13, text: "Und jene sagen zu ihr: Frau, was weinst du? Sie spricht zu ihnen: Weil sie meinen Herrn weggenommen und ich nicht weiß, wo sie ihn hingelegt haben." },
      { number: 14, text: "Als sie dies gesagt hatte, wandte sie sich zurück und sieht Jesus dastehen; und sie wusste nicht, dass es Jesus war*.", footnotes: ["℘ Kap. 21,4; Lk 24,16 ⇨Esyn: Synopse Nr. 353"] },
      { number: 15, text: "Jesus spricht zu ihr: Frau, was weinst du? Wen suchst du? Sie, in der Meinung, es sei der Gärtner, spricht zu ihm: Herr, wenn du ihn weggetragen, so sage mir, wo du ihn hingelegt hast! Und ich werde ihn wegholen." },
      { number: 16, text: "Jesus spricht zu ihr: Maria! Sie wendet sich um und spricht zu ihm auf Hebräisch: Rabbuni*! — das heißt Lehrer.", footnotes: ["Ausdruck gesteigerter Ehrerbietung für die Anredeform Rabbi; vgl. auch Anm. zu Kap. 1,38"] },
      { number: 17, text: "Jesus spricht zu ihr: Rühre mich nicht an! Denn ich bin noch nicht aufgefahren zum Vater. Geh aber hin zu meinen Brüdern* und sprich zu ihnen: Ich fahre auf* zu meinem Vater und eurem Vater* und zu meinem Gott* und eurem Gott*!", footnotes: ["℘ Hebr 2,11.12", "℘ Kap. 6,62", "℘ Röm 8,15", "℘ Eph 1,17", "℘ Gal 1,4"] },
      { number: 18, text: "Maria Magdalena kommt und verkündet den Jüngern, dass sie den Herrn gesehen und er dies zu ihr gesagt habe." },
      { number: 19, text: "Als es nun Abend war an jenem Tag, dem ersten der Woche*, und die Türen, wo die Jünger waren, aus Furcht vor den Juden* verschlossen waren, kam Jesus und trat in die Mitte* und spricht zu ihnen: Friede euch!", heading: "Erscheinung des Auferstandenen vor den Jüngern", footnotes: ["℘ V. 1", "℘ Kap. 7,13", "℘ 1Kor 15,5; Mk 16,14 ⇨Esyn: Synopse Nr. 356"] },
      { number: 20, text: "Und als er dies gesagt hatte, zeigte er ihnen die Hände und die Seite*. Da freuten sich die Jünger, als sie den Herrn sahen*.", footnotes: ["℘ Kap. 19,34; Lk 24,39", "℘ Kap. 16,22; Mt 28,8"] },
      { number: 21, text: "Jesus sprach nun wieder zu ihnen: Friede euch! Wie der Vater mich ausgesandt hat, sende ich auch euch*.", footnotes: ["℘ Kap. 17,18"] },
      { number: 22, text: "Und als er dies gesagt hatte, hauchte er sie an und spricht zu ihnen: Empfangt Heiligen Geist! *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 158"] },
      { number: 23, text: "Wenn ihr jemandem die Sünden vergebt, dem sind sie vergeben, wenn ihr sie jemandem behaltet, sind sie ihm behalten*.", footnotes: ["℘ Mt 18,18"] },
      { number: 24, text: "Thomas aber, einer von den Zwölfen, genannt Zwilling*, war nicht bei ihnen, als Jesus kam.", footnotes: ["griech. Didymos; die griech. Namensform für aram. Thoma; beides bedeutet »Zwilling«\n℘ Kap. 11,16 ⇨Esyn: Synopse Nr. 357"] },
      { number: 25, text: "Da sagten die anderen Jünger zu ihm: Wir haben den Herrn gesehen. Er aber sprach zu ihnen: Wenn ich nicht in seinen Händen das Mal der Nägel sehe und meine Finger in das Mal der Nägel lege* und lege meine Hand in seine Seite*, so werde ich nicht glauben*.", footnotes: ["℘ Ps 22,17", "℘ Kap. 19,34; Lk 24,39", "℘ Mk 16,11"] },
      { number: 26, text: "Und nach acht Tagen waren seine Jünger wieder drinnen und Thomas bei ihnen. Da kommt Jesus, als die Türen verschlossen waren, und trat in die Mitte und sprach: Friede euch!" },
      { number: 27, text: "Dann spricht er zu Thomas: Reiche deinen Finger her und sieh meine Hände, und reiche deine Hand her und lege sie in meine Seite*, und sei nicht ungläubig, sondern gläubig!", footnotes: ["℘ Kap. 19,34; Lk 24,39"] },
      { number: 28, text: "Thomas antwortete und sprach zu ihm: Mein Herr und mein Gott*!", footnotes: ["℘ Ps 84,4"] },
      { number: 29, text: "Jesus spricht zu ihm: Weil du mich gesehen hast, hast du geglaubt. Glückselig sind, die nicht gesehen und doch geglaubt haben*!", footnotes: ["℘ 2Kor 5,7; 1Petr 1,8"] },
      { number: 30, text: "Auch viele andere Zeichen hat nun zwar Jesus vor den Jüngern getan*, die nicht in diesem Buch geschrieben sind*.", heading: "Zweck dieses Buches", footnotes: ["℘ Kap. 11,47", "℘ Kap. 21,25 ⇨Esyn: Synopse Nr. 366"] },
      { number: 31, text: "Diese aber sind geschrieben, damit ihr glaubt*, dass Jesus der Christus ist, der Sohn Gottes*, und damit ihr durch den Glauben* Leben habt in seinem Namen*.", footnotes: ["℘ Kap. 19,35", "℘ Kap. 1,49", "w. damit ihr glaubend", "℘ Kap. 3,15.16; 1Jo 5,13"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "Nach diesem offenbarte Jesus sich wieder den Jüngern am See von Tiberias. Er offenbarte sich aber so: *", heading: "Erscheinung des Auferstandenen vor den Jüngern am See Tiberias", footnotes: ["℘ ⇨Esyn: Synopse Nr. 367"] },
      { number: 2, text: "Simon Petrus und Thomas, genannt Zwilling*, und Nathanael*, der von Kana in Galiläa war, und die Söhne des Zebedäus und zwei andere von seinen Jüngern waren zusammen. Simon Petrus spricht zu ihnen:", footnotes: ["griech. Didymos; die griech. Namensform für aram. Thoma; beides bedeutet »Zwilling«\n℘ Kap. 11,16", "℘ Kap. 1,45"] },
      { number: 3, text: "Ich gehe hin fischen. Sie sprechen zu ihm: Auch wir gehen mit dir. Sie gingen hinaus und stiegen in das Boot; und in jener Nacht fingen sie nichts*.", footnotes: ["℘ Ps 127,2; Lk 5,5"] },
      { number: 4, text: "Als aber schon der frühe Morgen anbrach, stand Jesus am Ufer; doch wussten die Jünger nicht, dass es Jesus war*.", footnotes: ["℘ Kap. 20,14"] },
      { number: 5, text: "Jesus spricht nun zu ihnen: Kinder, habt ihr wohl etwas zu essen*? Sie antworteten ihm: Nein.", footnotes: ["w. etwas Zukost (zum Brot)\n℘ Lk 24,41"] },
      { number: 6, text: "Er aber sprach zu ihnen: Werft das Netz auf der rechten Seite des Bootes aus*! Und ihr werdet finden. Da warfen sie es aus und konnten es vor der Menge der Fische nicht mehr ziehen*.", footnotes: ["℘ Lk 5,4", "℘ Lk 5,6"] },
      { number: 7, text: "Da sagt jener Jünger, den Jesus liebte*, zu Petrus: Es ist der Herr! Simon Petrus nun, als er hörte, dass es der Herr sei, gürtete das Oberkleid um — denn er war nackt — und warf sich in den See.", footnotes: ["℘ V. 20; Kap. 13,23"] },
      { number: 8, text: "Die anderen Jünger aber kamen in dem Boot — denn sie waren nicht weit vom Land, sondern etwa zweihundert Ellen — und zogen das Netz mit den Fischen nach." },
      { number: 9, text: "Als sie nun ans Land ausstiegen, sehen sie ein Kohlenfeuer liegen und Fisch daraufliegen und Brot." },
      { number: 10, text: "Jesus spricht zu ihnen: Bringt her von den Fischen, die ihr jetzt gefangen habt!" },
      { number: 11, text: "Da ging Simon Petrus hinauf und zog das Netz voll großer Fische, hundertdreiundfünfzig, auf das Land; und obwohl es so viele waren, zerriss das Netz nicht." },
      { number: 12, text: "Jesus spricht zu ihnen: Kommt her, frühstückt! Keiner aber von den Jüngern wagte ihn zu fragen: Wer bist du? Denn sie wussten, dass es der Herr war." },
      { number: 13, text: "Jesus kommt und nimmt das Brot und gibt es ihnen und ebenso den Fisch*.", footnotes: ["℘ Kap. 6,11; Apg 10,41"] },
      { number: 14, text: "Dies ist schon das dritte Mal, dass Jesus sich den Jüngern offenbarte, nachdem er aus den Toten auferweckt war*.", footnotes: ["℘ Kap. 20,19.26"] },
      { number: 15, text: "Als sie nun gefrühstückt hatten, spricht Jesus zu Simon Petrus: Simon, Sohn des Johannes*, liebst du mich mehr als diese? Er spricht zu ihm: Ja, Herr, du weißt, dass ich dich lieb habe. Spricht er zu ihm: Weide meine Lämmer!", heading: "Gespräch mit Petrus", footnotes: ["℘ Kap. 1,42 ⇨Esyn: Synopse Nr. 315"] },
      { number: 16, text: "Wieder spricht er zum zweiten Mal zu ihm: Simon, Sohn des Johannes*, liebst du mich? Er spricht zu ihm: Ja, Herr, du weißt, dass ich dich lieb habe. Spricht er zu ihm: Hüte meine Schafe*!", footnotes: ["℘ Kap. 1,42", "℘ Apg 20,28; 1Petr 5,2"] },
      { number: 17, text: "Er spricht zum dritten Mal zu ihm: Simon, Sohn des Johannes*, hast du mich lieb? Petrus wurde traurig, dass er zum dritten Mal zu ihm sagte: Hast du mich lieb?, und sprach zu ihm: Herr, du weißt alles*; du erkennst, dass ich dich lieb habe. Jesus spricht zu ihm: Weide meine Schafe!", footnotes: ["℘ Kap. 1,42", "℘ Kap. 2,25"] },
      { number: 18, text: "Wahrlich, wahrlich, ich sage dir: Als du jünger warst, gürtetest du dich selbst und gingst, wohin du wolltest; wenn du aber alt geworden bist, wirst du deine Hände ausstrecken, und ein anderer wird dich gürten und hinbringen, wohin du nicht willst*.", footnotes: ["℘ Kap. 13,36; 2Petr 1,14"] },
      { number: 19, text: "Dies aber sagte er, um anzudeuten, mit welchem Tod er Gott verherrlichen sollte. Und als er dies gesagt hatte, spricht er zu ihm: Folge mir nach*!", footnotes: ["℘ Kap. 1,43"] },
      { number: 20, text: "Petrus wandte sich um und sieht den Jünger nachfolgen, den Jesus liebte*, der sich auch bei dem Abendessen an seine Brust gelehnt und gesagt hatte: Herr, wer ist es, der dich überliefert*?", footnotes: ["℘ V. 7", "℘ Kap. 13,25"] },
      { number: 21, text: "Als nun Petrus diesen sah, spricht er zu Jesus: Herr, was soll aber dieser?" },
      { number: 22, text: "Jesus spricht zu ihm: Wenn ich will, dass er bleibe, bis ich komme, was geht es dich an? Folge du mir nach*!", footnotes: ["℘ Kap. 1,43"] },
      { number: 23, text: "Es ging nun dieses Wort hinaus unter die Brüder: Jener Jünger stirbt nicht. Aber Jesus sprach nicht zu ihm, dass er nicht sterbe, sondern: Wenn ich will, dass er bleibe, bis ich komme, was geht es dich an?" },
      { number: 24, text: "Das ist der Jünger, der von diesen Dingen zeugt* und der dies geschrieben hat; und wir wissen, dass sein Zeugnis wahr ist*.", heading: "Schlusswort", footnotes: ["℘ Offb 1,2", "℘ Kap. 15,27; 3Jo 12"] },
      { number: 25, text: "Es gibt aber auch viele andere Dinge, die Jesus getan hat; wenn diese alle einzeln niedergeschrieben würden, so würde, scheint mir, selbst die Welt die geschriebenen Bücher nicht fassen*.", footnotes: ["℘ Kap. 20,30"] },
    ]},
  ]
};
